window.JASTROW_CHUNKS[25]={"10000":{"h":"חֲרַס","r":"H01727","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Deut. XXVIII, 27</span> (Y. quot. in Ar. <a href=\"#\" data-headword=\"חַרְסוֹנָא\">חַרְסוֹנָא</a>, v. <a href=\"#\" data-headword=\"חִיכּוּכָא\">חִיכּוּכָא</a>).</div>","alt":["(חֶרֶס)"]},"10001":{"h":"חַרְסוּם","r":"H01728","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥarsum</i>.—<span class=\"citation\">Yoma 9ᵃ</span>; Y. ib. III, 40ᵈ <span dir=\"rtl\">אלעזר בן ח׳</span> (or <a href=\"#\" data-headword=\"אֱלִיעֶזֶר\">אליעזר</a>) El b. Ḥ. a highpriest; <span class=\"citation\">Tosef. ib. I, 22</span> <a href=\"#\" data-headword=\"חרסות\">חרסות</a> ed. Zuck. (Var. <span dir=\"rtl\">סום …</span>).—<span class=\"citation\">Yoma 35ᵇ</span> R. El b. Ḥ. a rich scholar; <span class=\"citation\">Lam. R. to II, 2</span> (some ed. <a href=\"#\" data-headword=\"חַרְסָנָה\">חַרְסָנָה</a>) <span class=\"citation\">Treat. S’maḥoth ch. IX</span> <span dir=\"rtl\">בימי ח׳</span> (prob. to be read: <span dir=\"rtl\">בן ח׳</span></div>","alt":[]},"10002":{"h":"חַרְסוּן","r":"H01729","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥarsun</i>. <span class=\"citation\">Koh. R. to IV, 8</span> גביני בן ח׳ G. b. H., a rich heir (cmp. <a href=\"#\" data-headword=\"חַרְסוּם\">preced.</a>).</div>","alt":[]},"10003":{"h":"חַרְסוֹנָא","r":"H01730","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲרַס\">חֲרַס</a></div>","alt":[]},"10004":{"h":"חרסות","r":"H01731","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַרְסוּם\">חַרְסוּם</a></div>","alt":[]},"10005":{"h":"חַרְסִית I","r":"H01732","html":"<div class=\"sense\"> (b. h.) pr. n., <span dir=\"rtl\">שער הח׳</span> <i>Gate of Ḥarsith</i>, one of the Jerusalem gates. <span class=\"citation\">Y. Erub. V, 22ᶜ</span> (the Eastern gate) was called <span dir=\"rtl\">שער חריסית שהוא מכוון וכ׳</span> (corr. acc.) Gate of Ḥ., because it was facing the East; v. <a href=\"#\" data-headword=\"חֶרֶס II\"><span dir=\"rtl\">חֶרֶס</span> II</a>.</div>","alt":[]},"10006":{"h":"חַרְסִית II","r":"H01733","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חֶרֶס I) <i>potter’s clay, clay-ground.</i> <span class=\"citation\">Maas. Sh. V, 1</span> <span dir=\"rtl\">בח׳</span> must be marked off with burned clay. <span class=\"citation\">Ḥull. VI, 7</span> <span dir=\"rtl\">בח׳</span>; <span class=\"citation\">ib. 88ᵃ</span> <span dir=\"rtl\">שחיקת ח׳</span> powdered burned clay. <span class=\"citation\">Kel. III, 7</span>; a. fr.—[<span class=\"citation\">Tosef. Ter. IX, 3</span> <span dir=\"rtl\">חרסיות</span>, v. <a href=\"#\" data-headword=\"חָסִית I\"><span dir=\"rtl\">חָסִית</span> I</a>.]</div>","alt":[]},"10007":{"h":"חַרְסָן","r":"H01734","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חַרְסִית II\">preced.</a>) <i>earthen vessel, bed-chamber</i>. <span class=\"citation\">Tosef. Ter. X, 13</span>; <span class=\"citation\">Tosef. Toh. V, 3</span>; <span class=\"citation\">Y. Ter. XI, 48ᵃ</span> <a href=\"#\" data-headword=\"הריוסן\">הריוסן</a> (corr. acc.). [Ar. ed. Koh., s. v. <a href=\"#\" data-headword=\"הַרְסָנָא\">הרסנא</a>, reads <a href=\"#\" data-headword=\"הַרְסָן\">הַרְסָן</a>.]</div>","alt":[]},"10008":{"h":"חַרְסָנָה","r":"H01735","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַרְסוּם\">חַרְסוּם</a></div>","alt":[]},"10009":{"h":"חרספותייא","r":"H01736","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַרְסְפִיתִין\">next w.</a></div>","alt":[]},"10010":{"h":"חַרְסְפִיתִין","r":"H01737","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲסַף I\">חסף</a> with <a href=\"#\" data-headword=\"ר\">ר</a> inserted, v. <a href=\"#\" data-headword=\"חַסְפְּנִיתָא\">חַסְפְּנִיתָא</a>) <i>scales</i>. <span class=\"citation\">Targ. Y. Lev. XI, 9</span>, sq. <span class=\"citation\">Targ. Y. Deut. XIV, 9</span> sq.—<span class=\"citation\">Pesik. R. s. 14</span> <span dir=\"rtl\">דמיין לחַרְסְפוּתַיָּיא דנוני</span>, v. <a href=\"#\" data-headword=\"חַסְפְּנִיתָא\">חַסְפְּנִיתָא</a>; Pesik. Par., p. 35ᵃ <span dir=\"rtl\">להחרפותא דיונה</span> (corr. acc.).</div>","alt":[]},"10011":{"h":"חֵרֶף","r":"H01738","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָרַף\">next w.</a>) [<i>shame</i>,] <i>ḥeref</i>, a phonetic substitute for <a href=\"#\" data-headword=\"חֵרֶם\">חֵרֶם</a>. <span class=\"citation\">Ned. I, 2</span>.—Pl. <span dir=\"rtl\">חֲרָפִים</span>, v. <a href=\"#\" data-headword=\"חֲרָפַיָּיא\">חֲרָפַיָּיא</a>.</div>","alt":[]},"10012":{"h":"חָרַף","r":"H01739","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to scrape, sharpen, grind</i>.—Part. pass. <a href=\"#\" data-headword=\"חֵירוּף\">חָרוּף</a>, f. <a href=\"#\" data-headword=\"חֲרוּפָה\">חֲרוּפָה</a>, pl. <span dir=\"rtl\">חֲרוּפוֹת</span>. <span class=\"citation\">Pesik. R. s. 21</span> <span dir=\"rtl\">פנים ח׳</span> sharp (severe) countenance (Var. <span dir=\"rtl\">הדופות</span>).—Trnsf. <i>to deflour</i>, v. infra.</div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">חלף</span>) <i>to change, transform; to change possession.</i> <i> Part. pass</i>. f. <a href=\"#\" data-headword=\"חֲרוּפָה\">חֲרוּפָה</a> <i>designated for change of condition</i>, v. <a href=\"#\" data-headword=\"חֲרוּפָה\">חֲרוּפָה</a>.</div><div class=\"sense\"><b>Nif. נֶחֱרַף</b> <div class=\"sense\"><b>1)</b>  (of grist) (of grist) <i>to be ground;</i> trnsf. <i>to be defloured, have intercourse</i>. Y. Kidd. I, 59ᵃ top (expl. <span class=\"citation\">Lev. XIX, 20</span>) <span dir=\"rtl\">נֶחֱרֶפֶת … בכתושה לפני איש</span> <i>‘neḥĕrefeth</i> by a man’ means crushed before a man (with ref. to <span class=\"citation\">Prov. XXVII, 22</span>, v. <a href=\"#\" data-headword=\"הֲרִיפוֹת\">הֲרִיפוֹת</a>).</div><div class=\"sense\"><b>—2)</b> <i>to change condition</i>. <span class=\"citation\">Kerith. 11ᵃ</span> (ref. to <span dir=\"rtl\">נחרפת</span> explained by <a href=\"#\" data-headword=\"בְּתוּלָה\">בְּעוּלָה</a>) <span dir=\"rtl\">מאי משמע … דשנויי הוא</span> (Rashi: <span dir=\"rtl\">דשינויא</span>) what proof is there that <i>neḥĕrefeth</i> has the meaning of change from natural condition? Answ. ref. to <a href=\"#\" data-headword=\"הֲרִיפוֹת\">הָרִיפוֹת</a> (<span class=\"citation\">II Sam. XVII, 19</span>) and to Prov. l. c.</div></div><div class=\"sense\"><b>Pi. חֵרֵף  חֵירֵף</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"גָּרַף\">גָּרַף</a>, <a href=\"#\" data-headword=\"גָּדַף\">גָּדַף</a>) [<i>to scrape off</i>,] <i>to revile, blaspheme, shame</i>. <span class=\"citation\">Lev. R. s. 7</span>, end <span dir=\"rtl\">מְחָרֶפֶת ומגדפת</span> she (Rome) blasphemes and reviles. <span class=\"citation\">Num. R. s. 10</span> <span dir=\"rtl\">מְחָרְפָם</span>, v. <a href=\"#\" data-headword=\"גָּדַף\">גָּדַף</a>. <span class=\"citation\">Snh. 94ᵃ</span>, sq. <span dir=\"rtl\">שחי׳ ע&quot;י וכ׳</span> who blasphemed (the Lord) through a messenger; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְחָרֵף</b> </div><div class=\"sense\"><b>Nithpa. נִתְחָרֵף</b> <div class=\"sense\"><b>1)</b> <i>to be reviled</i>. <span class=\"citation\">Midr. Till. to Ps. LXXIV</span>, end <span dir=\"rtl\">שמִתְחָרֵף ומתנאץ</span> which is reviled and blasphemed. <span class=\"citation\">Midr. Till. to Ps. XVIII, 1</span> <span dir=\"rtl\">עד שנִתְחָרַפְתִּי</span> until I was reviled; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to become white, pale</i>. Tanḥ. <span class=\"citation\">B’resh. 12</span> (play on <span dir=\"rtl\">קיץ וחרף</span>) <span dir=\"rtl\">שתהיו מתקייצין ופניכם מִתְחָרְפִין</span> (some ed. <span dir=\"rtl\">מתחפרין</span>) that you will feel nauseous and your faces become pale.</div></div>","alt":[]},"10013":{"h":"חֲרַף","r":"H01740","html":"<div class=\"sense\">; <i>Pa.</i> <a href=\"#\" data-headword=\"חָרַף\">חָרֵף</a> </div><div class=\"sense\"><b>1)</b> <i>to sharpen, grind</i>. <span class=\"citation\">Targ. I Sam. XIII, 20</span>, sq. <span class=\"citation\">Targ. Job XVI, 9</span> (not <a href=\"#\" data-headword=\"חָרִיף\">חָרִיף</a>; h. text <span dir=\"rtl\">ילטש</span>).—Part. pass. <span dir=\"rtl\">מְחַרַף</span>. <span class=\"citation\">Targ. Jer. IX, 7</span> ed. Lag. (oth. ed. <span dir=\"rtl\">מְחָרֵיף</span>, corr. acc.). <span class=\"citation\">Targ. Is. V, 28</span>.</div><div class=\"sense\"><b>—2)</b> <i>to blaspheme, revile</i>. <span class=\"citation\">Targ. Y. Lev. XXIV, 11</span>.; a. fr.—[<span class=\"citation\">Ib. 15</span>, sq. <span dir=\"rtl\">יֶחֱרַף</span> <i>Pe.!</i>]</div><div class=\"sense\"><b>Af. אַחֲרִיף</b> <div class=\"sense\"><i>to be quick, be early</i>. <span class=\"citation\">Snh. 70ᵇ</span> <span dir=\"rtl\">אַחֲרִיפוּ ועולו וכ׳</span> go in early (before sunset), and leave early, that people may take notice of you. <span class=\"citation\">Sabb. 115ᵃ</span> <span dir=\"rtl\">דהוו קא מַחְרְפֵי</span> that they did it earlier (than they were told to).</div></div>","alt":[]},"10014":{"h":"חֹרֶף","r":"H01741","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוֹרֶף\">חוֹרֶף</a></div>","alt":[]},"10015":{"h":"חֲרָפָא","r":"H01742","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֲרַף\">חֲרַף</a><i>Af.</i>) <i>early</i>. <span class=\"citation\">B. Bath. 90ᵇ</span> <span dir=\"rtl\">תרעא ח׳ וכ׳</span> the early market (soon after the crop) at the early market price, opp. <span dir=\"rtl\">תרעא אפלא</span> later market.—Pl. <span dir=\"rtl\">חָרְפֵי</span>. <span class=\"citation\">Targ. Koh. XI, 2</span> early seeds.—<span class=\"citation\">Taan. 3ᵇ</span> <span dir=\"rtl\">בח׳</span> concerning early clouds (when rain is gathering). <span class=\"citation\">Nidd. 65ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲפֵילָא\">אֲפֵילָא</a>.—<i>Fem. </i> pl. <span dir=\"rtl\">חֲרָפָתָא</span>. <span class=\"citation\">R. Hash. 8ᵃ</span> Ar. (ed. <span dir=\"rtl\">חָרְפְּיָיתָא</span>), v. <a href=\"#\" data-headword=\"אֲפֵילָא\">אֲפֵילָא</a>.</div>","alt":["חָרְפָא"]},"10016":{"h":"חֶרְפָּה","r":"H01743","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> [<i>paleness</i>,] <i>shame; revilement</i>. <span class=\"citation\">Gen. R. s. 80</span>. <span class=\"citation\">Sabb. 88ᵇ</span>, a. e. <span dir=\"rtl\">שומעין חֶרְפָּתָן וכ׳</span> hear themselves reviled and answer not.</div>","alt":[]},"10017":{"h":"חַרְפּוּפִיתָא","r":"H01744","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲרַף\">חֲרַף</a>) <i>scab</i>, v. <a href=\"#\" data-headword=\"חִיפּוּפִיתָא\">חִיפּוּפִיתָא</a>.</div>","alt":["חַרְפּוּפְתָּא"]},"10018":{"h":"חֲרָפַיָּיא","r":"H01745","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֵרֶף\">חֵרֶף</a>) <i>ḥărafaya</i>, a phonetic substitute of <a href=\"#\" data-headword=\"חֵרֶף\">חֵרֶף</a> in place of <a href=\"#\" data-headword=\"חֵרֶם\">חֵרֶם</a>. <span class=\"citation\">Ned. 10ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲרָקַיָּיא\">חֲרָקַיָּיא</a>.</div>","alt":[]},"10019":{"h":"חָרְפִּיתָא","r":"H01746","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>early conceiving, vigorous sheep</i>. v. <a href=\"#\" data-headword=\"חֲרָפָא\">חֲרָפָא</a>; cmp. <a href=\"#\" data-headword=\"חוּרְפָא\">חוּרְפָא</a>.</div>","alt":[]},"10020":{"h":"חֶרְפְּתָא","r":"H01747","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"חֶרְפָּה\">חֶרְפָּה</a>. <span class=\"citation\">Targ. Ps. XXII, 7</span> חֶרְפַּת Ms. (ed. <span dir=\"rtl\">חִיסּוּדֵי</span>).</div>","alt":[]},"10021":{"h":"חֲרַפְתָּא","r":"H01748","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>bat</i>. <span class=\"citation\">Targ. Y. II, Deut. XIV, 18</span> (Y. I <a href=\"#\" data-headword=\"עַרְפְּדָא\">ערפדא</a>).</div>","alt":[]},"10022":{"h":"חָרַץ","r":"H01749","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to dig a cavity, to cut a trench</i> of even width all through. Y. Kil. VII, 31ᵇ bot. <span dir=\"rtl\">חפר ח׳ נעץ וכ׳</span> if (on the Sabbath) one dug (a pit), made a trench, and cut a wedge-like ditch (narrow below), he is guilty of one act; <span class=\"citation\">Y. Sabb. VII, 9ᵈ</span> bot.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to decree, designate</i>. Tanḥ. <span class=\"citation\">B’ḥuck. 1</span> (ref. to <span class=\"citation\">Job XIV, 5</span>) <span dir=\"rtl\">ח׳ ימיו וכ׳</span> He designated the duration of life of every creature.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חָרוּץ\">חָרוּץ</a>, f. <span dir=\"rtl\">חֲרוּצָה</span>; pl. <span dir=\"rtl\">חֲרוּצִים</span>, <span dir=\"rtl\">חֲרוּצוֹת</span> a) <i>grooved</i>. <span class=\"citation\">Sabb. 98ᵇ</span> <span dir=\"rtl\">ח׳ היו הקרשים וב׳</span> the boards of the Tabernacle were grooved, and the sockets hollowed out correspondingly.—b) <i>decreed, decided; determined</i>. <span class=\"citation\">Gen. R. s. 67</span> (ref. to <span class=\"citation\">Prov. XII, 27</span>) the blessings <span dir=\"rtl\">שמעיקר העולם חרוצות לו</span> which were designated to him from primeval days. Ib. <span dir=\"rtl\">חרוצה ביד וכ׳</span> it is a decided fact known to the righteous that they will in this world receive none &amp;c. <span class=\"citation\">Deut. R. s. 1</span> <span dir=\"rtl\">שידיך חדות וח׳</span> that thy hands are quick and determined.—c) <i>flat-nosed</i>, v. <a href=\"#\" data-headword=\"חָרוּץ\">חָרוּץ</a>.</div><div class=\"sense\"><b>Nif. נֶחֲרַץ</b> <div class=\"sense\"><i>to be cut into, dug, ploughed</i>. Y. Nidd. I, 49ᵃ bot. a soil is called virgin <span dir=\"rtl\">כל שלא נ׳ בה מימיה</span> when it has never been cut into; v. <a href=\"#\" data-headword=\"חֶרֶץ\">חֶרֶץ</a>.</div></div>","alt":[]},"10023":{"h":"חֲרַץ","r":"H01750","html":"<div class=\"sense\">, <i>to cut into</i>. Part. pass. <a href=\"#\" data-headword=\"חָרִיץ\">חָרִיץ</a>. <span class=\"citation\">Gitt. 20ᵃ</span> <span dir=\"rtl\">רושמא מִיחֲרַץ ח׳ וכ׳</span> is the stamp of a coin dug into (are the devices formed with a loss of substance), or is it pressed into (by compressing the substance)?—<span class=\"citation\">Bekh. 41ᵃ</span> <span dir=\"rtl\">מיחרץ ח׳</span> (a dry scab is) cut into (deeper than the surface).</div><div class=\"sense\"><b>Ithpe. אִיחֲרַץ</b> <div class=\"sense\"><i>to be cut into</i>, v. supra.</div></div>","alt":[]},"10024":{"h":"חֶרֶץ","r":"H01751","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲרַץ\">preced.</a>) <i>incision, groove, mark of a seam</i>. <span class=\"citation\">Y. Nidd. I, 49ᵃ</span> bot. <span dir=\"rtl\">כל שאין בה ח׳</span> (a virgin soil is) such as shows no grooves. <span class=\"citation\">Y. Maasr. I, 48ᵈ</span> bot. <span dir=\"rtl\">משיתמלא הח׳</span> from the time the incision in the growing fruits begins to fill up.—<span class=\"citation\">Y. Bets. II, end, 61ᵈ</span>, a. e., v. <a href=\"#\" data-headword=\"חָרִיץ\">חֲרִיץ</a>.</div>","alt":[]},"10025":{"h":"חֶרֶץ ²","r":"H01752","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>loin</i>, v. <a href=\"#\" data-headword=\"חַרְצָא II\"><span dir=\"rtl\">חַרְצָא</span> II</a>.</div>","alt":[]},"10026":{"h":"חַרְצָא I","r":"H01753","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲרַץ\">חֲרַץ</a>) <i>digging, a digger</i>. <span class=\"citation\">B. Kam. 80ᵃ</span> (marginal version) <span dir=\"rtl\">שרצא ח׳ וא&quot;ד ח׳</span> a digging animal, and some use only the word <i>ḥartsa:</i> digger; v. <a href=\"#\" data-headword=\"חַרְזָא\">חַרְזָא</a>.</div>","alt":[]},"10027":{"h":"חַרְצָא II","r":"H01754","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲרַץ\">חֲרַץ</a>) </div><div class=\"sense\"><b>1)</b> <i>groove, channel</i>, v. <a href=\"#\" data-headword=\"חֲרִיצָא\">חֲרִיצָא</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כֶּסֶל\">כֶּסֶל</a>) [<i>incision</i>,] <i>loins</i>. <span class=\"citation\">Targ. Deut. XXXIII, 11</span> (Y. II <a href=\"#\" data-headword=\"חֶרֶץ\">חֶרֶץ</a>).—<span class=\"citation\">Targ. Gen. XXXVII, 34</span> (Y. <span dir=\"rtl\">חַרְצוֹי</span> <i>pl</i>.); a. fr.—Pl. <span dir=\"rtl\">חַרְצִין</span>, constr. <span dir=\"rtl\">חַרְצֵי</span>. <span class=\"citation\">Targ. O. Ex. XXVIII, 42</span> (some ed. <a href=\"#\" data-headword=\"חַרְצַן\">חַרְצָן</a> <i>their</i> loins); Y. ib. <span dir=\"rtl\">אתר קטור חַרְצֵיהוֹן חַרְצֵיהוֹן</span> the place of the knot of their loins (belt). <span class=\"citation\">Targ. Y. Gen. L, 11</span>; a. fr.</div>","alt":[]},"10028":{"h":"חַרְצִינִיתָא","r":"H01755","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַרְצָנִיתָא\">חַרְצָנִיתָא</a></div>","alt":["חרצינתא"]},"10029":{"h":"חַרְצַן","r":"H01756","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">חַרְצַנִּים</span> (b. h.) <i>a pomace of kernels</i> or <i>shells of grapes;</i> v. <a href=\"#\" data-headword=\"זָג\">זָג</a>. <span class=\"citation\">Naz. VI, 2</span>. <span class=\"citation\">Ib. 35ᵃ</span>; a. fr.—<span class=\"citation\">Ib. 38ᵇ</span> <span dir=\"rtl\">אכל חרצן</span> if he ate the shell (or the interior) of one berry. <span class=\"citation\">Ḥull. 82ᵇ</span> <span dir=\"rtl\">זרע חטה וח׳</span> if he sowed a wheat grain and a kernel; a. fr.—V. <a href=\"#\" data-headword=\"גּוּהַרְקָא II\"><span dir=\"rtl\">גּוּחַרְקָא</span> II</a>.</div>","alt":[]},"10030":{"h":"חַרְצָנָה","r":"H01757","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חַרְצַן\">preced.</a>; collect. noun) <i>kernels</i>. <span class=\"citation\">Y. Maasr. I, 48ᵈ</span> <span dir=\"rtl\">שתהא ח׳ שלהן וכ׳</span> their kernels must be seen through the berries.</div>","alt":[]},"10031":{"h":"חַרְצָנִיתָא","r":"H01758","html":"<div class=\"sense\">, <i>stones of a fruit</i>. Tanḥ. Vaëra 14 <span dir=\"rtl\">כהדא פרטתא דרמונא דח׳ מתחמיא מלגאו</span> like the berry of a pome-granate whose stones are seen from within (shining through); Pesik. Vayhi, p. 3ᵇ <span dir=\"rtl\">דחרצנייתא</span> (read: <span dir=\"rtl\">דחַרְצִינִיתָא</span>); <span class=\"citation\">Ex. R. s. 12</span> <span dir=\"rtl\">דחַרְצִינִיתֵיה</span>; <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">דחרצינתה</span> (corr. acc.); <span class=\"citation\">Cant. R. to III, 11</span> <span dir=\"rtl\">דכל הדא פיטרתא</span> (read: … <a href=\"#\" data-headword=\"חַרְצָנִיתָא\">חרצנתא</a>); <span class=\"citation\">Yalk. Ex. 186</span> <span dir=\"rtl\">דחרצנתי</span> (read: … <span dir=\"rtl\">תֵּיה</span>); <span class=\"citation\">Yalk. Job 912</span> (corr. acc.).</div>","alt":["חַרְצַנְתָּא"]},"10032":{"h":"חֵרֶק","r":"H01759","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָרַק\">next w.</a>) [<i>cleft</i>,] <i>ḥerek</i>, a phonetic substitute for <i>ḥerem</i> <a href=\"#\" data-headword=\"חֵרֶם\">(חֵרֶם</a>). <span class=\"citation\">Ned. I, 2</span>.—Pl. <span dir=\"rtl\">חֲרָקִים</span>, v. <a href=\"#\" data-headword=\"חֲרָקַיָּיא\">חֲרָקַיָּיא</a>.</div>","alt":[]},"10033":{"h":"חָרַק","r":"H01760","html":"<div class=\"sense\"> (b. h.) <i>to cut a gap; to squeeze into a gap; to prick.</i> <i> Part. pass</i>. <span dir=\"rtl\">חָרוּק</span>, f. <a href=\"#\" data-headword=\"*חֲלוּקָה\">חֲרוּקָה</a>; pl. <span dir=\"rtl\">חֲרוּקִים</span>, <span dir=\"rtl\">חֲרוּקוֹת</span> a) <i>having incisions, edged, serried</i>. <span class=\"citation\">Ḥull. 59ᵇ</span> ed., v. <a href=\"#\" data-headword=\"חָדַק\">חָדַק</a>.—b) <i>wedged in.</i> <span class=\"citation\">Par. XII, 8</span> <span dir=\"rtl\">החרוקות</span> (Var. <span dir=\"rtl\">החֲדוּקוֹת</span>) those handles which are squeezed into holes, opp. <span dir=\"rtl\">הקדוחות</span> bored handles; <span class=\"citation\">Tosef. ib. XII</span> (<span class=\"citation\">XI), 17</span> <span dir=\"rtl\">אף הרוק וצואה וכ׳</span> (read: <span dir=\"rtl\">אף החרוקות</span> · <span dir=\"rtl\">צואה וכ׳</span>).</div><div class=\"sense\"><b>Pi. חֵרֵק</b> <div class=\"sense\"> [<i>to set at edge</i>,] (with <a href=\"#\" data-headword=\"שֵׁן\">שֵׁן</a>) <i>to gnash, grind the teeth</i>. <span class=\"citation\">Pesik. R. s. 37</span> <span dir=\"rtl\">מְחָרְקִין שיניהם</span> ground their teeth (in sneer). <span class=\"citation\">Ex. R. s. 5</span>; Tanḥ. Vaëra 6 <span dir=\"rtl\">התחיל מְחָרֵק עליהם וכ׳</span> he began to gnash his teeth against them (in rage).</div></div>","alt":[]},"10034":{"h":"חֲרַק","r":"H01761","html":"<div class=\"sense\"><span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">לִיחֲרוֹק ביה פורתא</span> let him cut a little notch into it. Part. <span dir=\"rtl\">חָרֵיק</span>. <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> bot. <span dir=\"rtl\">וח׳ בשינוי</span> and gnashing his teeth; <span class=\"citation\">Y. Keth. XII, 35ᵇ</span> <span dir=\"rtl\">וחרוק</span> (corr. acc.).</div><div class=\"sense\"><b>Ithpe. אִיחֲרוֹק  אִחֲ׳</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָרַק\">same</a>. Y. Kil. l. c. <span dir=\"rtl\">הויתא א׳ בשינייך</span> thou wast gnashing thy teeth; Y. Keth. l. c. <span dir=\"rtl\">הוות א׳ בשינוי</span> (corr. acc.).</div></div>","alt":[]},"10035":{"h":"חִרְקָא","r":"H01762","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲרַק\">preced.</a>) <i>edge, notch</i>. . <span class=\"citation\">Ḥull. 59ᵇ</span> <span dir=\"rtl\">והוא דמיבלע חִירְקַיְיהוּ</span> provided the edges of their horns run irregularly into one another. <span class=\"citation\">Sabb. 46ᵃ</span> דאית בה חרקי Ar. it has indentations (making the candlestick appear as if composed of movable parts), v. <a href=\"#\" data-headword=\"חִדְקָא\">חדְקָא</a>.</div>","alt":["חִירְ׳"]},"10036":{"h":"חֲרָקַיָּיא","r":"H01763","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חִרְקָא\">preced.</a>) [<i>incisions</i>,]<i>ḥărakaya</i>, a Chaldaic substitute of <a href=\"#\" data-headword=\"חֵרֶק\">חֵרֶק</a> which is itself a substitute of <a href=\"#\" data-headword=\"חֵרֶם\">חֵרֶם</a>. <span class=\"citation\">Ned. 10ᵇ</span> what are the substitutes of <i>ḥerem?</i> ח׳ חרכייא חרפייא Rashi (Ar. <span dir=\"rtl\">הר׳</span>; ed. <span dir=\"rtl\">חֲרָקִים</span> &amp;c., h. pl. of <a href=\"#\" data-headword=\"חֵרֶק\">חֵרֶק</a></div>","alt":[]},"10037":{"h":"חָרַר I","r":"H01764","html":"<div class=\"sense\">, <i>Pi</i>. <a href=\"#\" data-headword=\"חֵרַר\">חֵרֵר</a> (v. <a href=\"#\" data-headword=\"חוֹר I\"><span dir=\"rtl\">חוֹר</span> I</a>) <i>to break through, to cave.</i> Ohol. III, 7; <span class=\"citation\">Succ. 20ᵇ</span> <span dir=\"rtl\">חור שחֵרְרוּהוּ מים</span> (or <span dir=\"rtl\">שחֲרָרוּהוּ</span></div>","alt":[]},"10038":{"h":"חֲרַר","r":"H01765","html":"<div class=\"sense\">, <i>to perforate</i>.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חֲרִיר\">חֲרִיר</a> <i>discharging</i> (v. <a href=\"#\" data-headword=\"חָרֵי\">חָרַיָּא</a>). <span class=\"citation\">Targ. Y. Lev. XV, 3</span> <span dir=\"rtl\">חֲ׳ … ית וכ׳</span> (some ed. <a href=\"#\" data-headword=\"חֲרַר ³\">חָרֵיר</a></div>","alt":[]},"10039":{"h":"חָרַר II","r":"H01766","html":"<div class=\"sense\">, <i>Pi</i>. <a href=\"#\" data-headword=\"חֵרַר\">חֵרֵר</a> (denom. of <a href=\"#\" data-headword=\"חוֹר II\"><span dir=\"rtl\">חוֹר</span> II</a>) <i>to set free</i>.—<i>Part. pass</i>. <span dir=\"rtl\">מְחוֹרָר</span> <i>freed, free</i>. <span class=\"citation\">Gen. R. s. 14</span>, end (ref. to <span class=\"citation\">Gen. II, 7</span> <span dir=\"rtl\">נפש חיה</span>) <span dir=\"rtl\">עבד מח׳ בפני עצמו וכ׳</span> (Var. <span dir=\"rtl\">מכודן</span>, v. <a href=\"#\" data-headword=\"כָּדַן\">כָּדַן</a>) a freed slave left to himself for a living.—<span class=\"citation\">Keth. 51ᵇ</span>; <span class=\"citation\">B. Kam. 95ᵃ</span> <span dir=\"rtl\">המְחוֹרָרִין</span> (<a href=\"#\" data-headword=\"נְכָסִים\">נכסים</a>) unencumbered property. [Shaf. <a href=\"#\" data-headword=\"שִׁחֲרֵר\">שִׁחֲרֵר</a>.]</div>","alt":[]},"10040":{"h":"חֲרַר ²","r":"H01767","html":"<div class=\"sense\">, <i>to set free</i>. <span class=\"citation\">Targ. Y. Gen. XVI, 2</span> אַחְרְרִינָהּ I will liberate her. <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">חֲרַרְתָּהּ</span> (not … <a href=\"#\" data-headword=\"תָּא\">תא</a>). <span class=\"citation\">Ib. 5</span>.</div><div class=\"sense\"><b>Ithpa. אִתְחָרַר  אִיתְחַר</b> <div class=\"sense\"><i>to be set free</i>. <span class=\"citation\">Targ. Lev. XIX, 20</span>.</div></div>","alt":[]},"10041":{"h":"חָרַר III","r":"H01768","html":"<div class=\"sense\"> [<i>to be rough, excited</i>,] <i>to glow.</i> <i> Pilp</i>. <a href=\"#\" data-headword=\"חִרְחֵר\">חִרְחֵר</a>, q. v.</div>","alt":[]},"10042":{"h":"חֲרַר ³","r":"H01769","html":"<div class=\"sense\">, <i>to burn, to be blackened, charred</i>. <span class=\"citation\">Targ. Ps. II, 12</span> <a href=\"#\" data-headword=\"יִחוּר\">יֵיחוֹר</a>. <span class=\"citation\">Ib. CII, 4</span>. <span class=\"citation\">Targ. Ez. XV, 4</span>, sq. <a href=\"#\" data-headword=\"חַר\">חַר</a>; a. e.</div><div class=\"sense\"><b>[. חָרֵיר</b> <div class=\"sense\"><i>to stir the fire</i>. <span class=\"citation\">Ab. Zar. 38ᵇ</span> <a href=\"#\" data-headword=\"חֲרוּרֵי\">חָרוּרֵי</a>, v. <a href=\"#\" data-headword=\"חֲרֵי\">חֲרֵי</a>.]</div></div><div class=\"sense\"><b>Ithpa. אִתְחַר</b> <div class=\"sense\"><i>to be heated, dried up</i>. Targ. II Esth. V, 1.</div></div><div class=\"sense\"><b>Ithpalp. אִתְחַרְחַר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָרַר III\">same</a>. <span class=\"citation\">Targ. Ps. LXIX, 4</span>.</div></div>","alt":[]},"10043":{"h":"חָרַר IV","r":"H01770","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">חרר I</span>) <i>to heap up, round</i>. Denom. <a href=\"#\" data-headword=\"חֲרָרָה\">חֲרָרָה</a>, <a href=\"#\" data-headword=\"חוֹרָר\">חוֹרָר</a>.</div>","alt":[]},"10044":{"h":"חֲרַר ⁴","r":"H01771","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"חָרַר IV\">same</a>.—<i>Pa.</i> חָרֵיר <i>to round, make a</i> <a href=\"#\" data-headword=\"חֲרָר\">חֲרָרָא</a>. <span class=\"citation\">Targ. Ez. IV, 12</span> (some ed. <span dir=\"rtl\">תַּחְרְ׳</span> <i>Af.</i>; h. text <span dir=\"rtl\">תעגינה</span>).</div>","alt":[]},"10045":{"h":"חֵרַר","r":"H01772","html":"<div class=\"sense\"><i>freedom</i>, v. <a href=\"#\" data-headword=\"חֵירַר\">חֵירַר</a>.</div>","alt":[]},"10046":{"h":"חָרָר","r":"H01773","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>needle-eye</i>, v. <a href=\"#\" data-headword=\"חוֹר I\">חוֹר</a> 1. 1.</div><div class=\"sense\"><b>—2)</b> <i>pile</i>, v. <a href=\"#\" data-headword=\"חוֹרָר\">חוֹרָר</a>.—<i>pl</i>. <span dir=\"rtl\">חֲרָרִין</span>, v. <a href=\"#\" data-headword=\"חֲרָרָה\">חֲרָרָה</a>.</div>","alt":[]},"10047":{"h":"חֲרָר","r":"H01774","html":"<div class=\"sense\"> c. = <a href=\"#\" data-headword=\"חֲרָרָה\">next w.</a>, </div><div class=\"sense\"><b>1)</b> <i>a cake</i>. <span class=\"citation\">Targ. Jud. VII, 13</span> (h. text <a href=\"#\" data-headword=\"צָלִיל\">צליל</a>). <span class=\"citation\">Targ. I Kings XVII, 13</span> (h. text <span dir=\"rtl\">עגה</span>); a. fr.—<span class=\"citation\">Pesik. R. s. 18</span> [read:] <span dir=\"rtl\">תמן אמרין עבדין מיניה ח׳ לכלבא ולא טעמיה</span> there (in Babylonia) they say, they made out of it a cake for a dog, but he would not taste it (v. <span class=\"citation\">Erub. 81ᵃ</span>); Pesik. Haomer, p. 71ᵇ <a href=\"#\" data-headword=\"חֲרָרָה\">חֲרָרָה</a>.—Pl. <span dir=\"rtl\">חֲרָרָן</span>. <span class=\"citation\">Targ. Y. I Num. XI, 8</span>. <span class=\"citation\">Targ. Y. Ex. XII, 39</span> (some ed. <a href=\"#\" data-headword=\"חֲרִירָא\">חֲרִירָן</a>; <a href=\"#\" data-headword=\"חרידן\">חרידן</a>, corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>clot</i>. <span class=\"citation\">Lev. R. s. 24</span> <span dir=\"rtl\">ח׳ דדמא</span> (ed. <a href=\"#\" data-headword=\"חרדא\">חרדא</a>, <a href=\"#\" data-headword=\"חרדא\">חרדה</a>, corr. acc.) a clot of blood.</div>","alt":["חֲרָרָא"]},"10048":{"h":"חֲרָרָה","r":"H01775","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חרר IV) [<i>rounded heap</i>,] </div><div class=\"sense\"><b>1)</b> <i>a thick cake</i> baked on coals. <span class=\"citation\">Kidd. 59ᵃ</span>, v. <a href=\"#\" data-headword=\"הָפַךְ\">הָפַךְ</a> (v. also Rashi a. l. a. infra). <span class=\"citation\">Sabb. I, 10</span>. <span class=\"citation\">Tosef. Ḥag. III, 12</span>; Y. ib. III, 79ᵇ, v. <a href=\"#\" data-headword=\"תָּחַב\">תָּחַב</a>. <span class=\"citation\">B. Kam. II, 3</span> <span dir=\"rtl\">שנטל ח׳</span> that took a cake (with live coals sticking to it).—Pl. <span dir=\"rtl\">חֲרָרִין</span>. <span class=\"citation\">Bets. II, 6</span> (<span class=\"citation\">21ᵇ</span>) <span dir=\"rtl\">גריצין וח׳</span> Bab. ed., v. <a href=\"#\" data-headword=\"גְּרִיצָה\">גְּרִיצָה</a> (Mish. ed. <a href=\"#\" data-headword=\"חוֹרִי I\">חוֹרִי</a>, Y. ed. <a href=\"#\" data-headword=\"חֳרִי\">חֹרִי</a> b. h., collect. noun: <i>cakes</i>); Y. ib. 61ᶜ bot. (play on <a href=\"#\" data-headword=\"חֳרִי\">חֳרִי</a>, <span class=\"citation\">Deut. XXIX, 23</span>, a. on <a href=\"#\" data-headword=\"חֳרִי\">חֹרִי</a>, <span class=\"citation\">Gen. XL, 16</span>).</div><div class=\"sense\"><b>—2)</b> <i>pile of sheaves, temporary stack</i> in the field. <span class=\"citation\">Peah V, 8</span> <span dir=\"rtl\">לח׳</span> for the purpose of temporary piling, opp. <span dir=\"rtl\">לגוֹרֶן</span>. [<span class=\"citation\">Kidd. 59ᵃ</span> <span dir=\"rtl\">עני המהפך בח׳</span> a poor man moving about a stack (waiting for its removal to take up eventually a forgotten sheaf); cmp. Peah l. c.; oth. defin. v. <a href=\"#\" data-headword=\"הָפַךְ\">הָפַךְ</a>.]—<span class=\"citation\">Y. Peah V, end, 19ᵃ</span>, expl. <a href=\"#\" data-headword=\"ח׳\">ח׳</a> with <a href=\"#\" data-headword=\"גַּלְגַּל\">גַּלְגַּל</a> a globular heap.</div><div class=\"sense\"><b>—3)</b>  חֲרָרַת דם <i>a clot of blood</i>. <span class=\"citation\">Bekh. III, 1</span> (<span class=\"citation\">21ᵇ</span>). <span class=\"citation\">Nidd. 66ᵃ</span>; a. e.—Tanḥ. K’dosh. 9 <span dir=\"rtl\">כחרדת</span> (corr. acc.)</div><div class=\"sense\"><b>—4)</b> <i>a ball of iron ore.</i> <span class=\"citation\">Kel. XI, 3</span> he who makes vessels <span dir=\"rtl\">מן הח׳</span> of iron ore (before it is smelted).</div>","alt":[]},"10049":{"h":"חֶרֶשׂ","r":"H01776","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲרַס\">חֶרֶס</a></div>","alt":[]},"10050":{"h":"חָרַשׁ I","r":"H01777","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to engrave, draw, design</i>. <span class=\"citation\">Koh. R. to I, 16</span> <span dir=\"rtl\">הלב חוֹרֵשׁ</span> the heart designs.</div><div class=\"sense\"><b>—2)</b> <i>to plough</i>. <span class=\"citation\">Macc. III, 9</span> <span dir=\"rtl\">יש חוֹרֵשׁ תלם וכ׳</span> one may plough one bed and &amp;c. <span class=\"citation\">Taan. 29ᵃ</span> וח׳ את העיר Ms. M. and passed the plough over the city of Jerusalem. <span class=\"citation\">Sabb. VII, 2</span>; a. fr.—Trnsf. <i>to have sexual intercourse</i>. <span class=\"citation\">Y. Yeb. I, 2ᵇ</span> top. <span class=\"citation\">Gen. R. s. 98</span>; a. e.</div><div class=\"sense\"><b>Nif. נֶחְרַשׁ</b> <div class=\"sense\"><i>to be ploughed over</i>. <span class=\"citation\">Taan. IV, 6</span> <span dir=\"rtl\">נֶחְרְשָׁה העיר</span> the plough was passed over the city of Jerusalem; a. e.</div></div>","alt":[]},"10051":{"h":"חָרַשׁ II","r":"H01778","html":"<div class=\"sense\"><i>Pi</i>. <a href=\"#\" data-headword=\"חֵרֵשׁ\">חֵרֵשׁ</a>, <a href=\"#\" data-headword=\"חֵדוּ\">חֵי׳</a> (denom. of <a href=\"#\" data-headword=\"חֵרֵשׁ\">חֵרֵשׁ</a>) <i>to deafen, make deaf</i>. <span class=\"citation\">B. Kam. 86ᵃ</span> <span dir=\"rtl\">שחֵירְשׁוֹ וכ׳</span> when he made him deaf without wounding him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">החוֹרֵשׁ את אביו</span> (Ms. H. a. R. <a href=\"#\" data-headword=\"חֵרֵשׁ\">חֵרֵשׁ</a>); <span class=\"citation\">ib. 98ᵃ</span> <span dir=\"rtl\">חֵרְשׁוֹ לאביו</span> if one injured his father’s hearing; v. <a href=\"#\" data-headword=\"חֲרִישָׁה II\"><span dir=\"rtl\">חֲרִישָׁה</span> II</a>. <span class=\"citation\">Kidd. 24ᵇ</span>.—<span class=\"citation\">Sabb. 109ᵃ</span> top. <span dir=\"rtl\">יד מְחָרֶשֶׁת</span> the unwashed hand put to the ear causes deafness.</div><div class=\"sense\"><b>Hif. הֶחֱרִישׁ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חָרַשׁ I\">same</a>. <span class=\"citation\">B. Kam. 86ᵃ</span> <span dir=\"rtl\">להַחֲרִישׁ</span>, v. <a href=\"#\" data-headword=\"חֲרִישָׁה II\"><span dir=\"rtl\">חֲרִישָׁה</span> II</a>.</div><div class=\"sense\"><b>—2)</b>  (b. h.) <i>to be silent</i>. Y. Pes. IX, end. 37ᵃ (ref. to <span class=\"citation\">Prov. XVII, 28</span>) <span dir=\"rtl\">ואין צ&quot;ל חכם מַחֲרִישׁ</span> and it is needless to say the same of a wise man keeping silence. [Usu. <a href=\"#\" data-headword=\"שָׁתַק\">שָׁתַק</a>.]</div></div><div class=\"sense\"><b>Nithpa. נִתְחָרֵשׁ</b> <div class=\"sense\"><i>to become deaf</i> (<i>and dumb</i>). <span class=\"citation\">Yeb. XIV, 1</span>; <span class=\"citation\">Tosef. Ter. I, 1</span> <span dir=\"rtl\">פיקח ונ׳</span> if he had been well-hearing and became etc.; v. <a href=\"#\" data-headword=\"חֵרֵשׁ\">חֵרֵשׁ</a>.</div></div>","alt":[]},"10052":{"h":"חֲרַשׁ","r":"H01779","html":"<div class=\"sense\">(v. <a href=\"#\" data-headword=\"חָרַשׁ II\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>to be entangled</i>. <span class=\"citation\">Targ. Job VIII, 17</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be choked, obstructed, deaf</i>. <span class=\"citation\">Gen. R. s. 81</span> (prov.) <span dir=\"rtl\">מהולתך חַרְשָׁה וכ׳</span> if thy sieve is choked, knock at it (when you are forgetful of your duties, the Lord will remind you through affliction); v. <a href=\"#\" data-headword=\"טְרַשׁ II\"><span dir=\"rtl\">טְרַשׁ</span> II</a>.</div><div class=\"sense\"><b>—3)</b> <i>to practice witchcraft</i>. <span class=\"citation\">Gen. R. s. 86</span> <span dir=\"rtl\">באתר דחרשין חֲרִישִׁין</span> where there are sorcerers witchcraft is practiced.</div><div class=\"sense\"><b>Pa. חַרֵשׁ</b> <div class=\"sense\"><i>to entangle, inure</i>. <span class=\"citation\">Targ. Ez. XIII, 20</span> (h. text <span dir=\"rtl\">צדד</span>).</div></div><div class=\"sense\"><b>Ithpa. אִתְחַרֵשׁ</b> <div class=\"sense\"><i>to be entangled, confounded</i>. Y. Ḥag. II, 77ᶜ top (expl. <span dir=\"rtl\">תאלמנה</span>, <span class=\"citation\">Ps. XXXI, 19</span>) <span dir=\"rtl\">יִתְחַרְשָׁן וכ׳</span> may their lips be confounded, crushed, silenced, cmp. <a href=\"#\" data-headword=\"אִלֵּם\">אִלֵּם</a> a. <a href=\"#\" data-headword=\"חֵרֵשׁ\">חֵרֵשׁ</a>; <span class=\"citation\">Gen. R. s. 1</span> (corr. acc.)</div></div>","alt":[]},"10053":{"h":"חָרָשׁ","r":"H01780","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>artist, artisan, carpenter, turner</i> (faber). <span class=\"citation\">Deut. R. s. 2</span> <span dir=\"rtl\">לח׳ שהיה וכ׳</span> like an artist that was making an image &amp;c.—Pl. <span dir=\"rtl\">חָרָשִׁים</span>. <span class=\"citation\">Gen. R. s. 65</span>, end; s. 70, v. <a href=\"#\" data-headword=\"חֲמוֹר\">חֲמוֹר</a>; Pesik. Shek., p. 15ᵃ.—Trsnf. <i>scholar</i>. <span class=\"citation\">Gitt. 88ᵃ</span> (ref. to <span class=\"citation\">II Kings XXIV, 16</span>) <span dir=\"rtl\">חָ׳ שבשעה … כחֵרְשִׁין</span> the scholars were named <i>ḥarash</i>, for when they opened argument, all were like dumb; <span class=\"citation\">Snh. 38ᵃ</span>; Yalk. Dan. 1066; a. e.—<i>Pl.</i> as above. <span class=\"citation\">Ḥag. 14ᵃ</span> (ref. to <span class=\"citation\">Is. III, 3</span>).</div>","alt":[]},"10054":{"h":"חָרָשׁ ²","r":"H01781","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sorcerer</i>, v. <a href=\"#\" data-headword=\"חָרָשָׁא\">חָרָשָׁא</a>.</div>","alt":[]},"10055":{"h":"חֶרֶשׁ","r":"H01782","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"חֵרֵשׁ\">חֵרֵשׁ</a>) <i>silence</i>. Tanḥ. Sh’mini 9 (play on <a href=\"#\" data-headword=\"חָרָשׁ\">חָרָשׁ</a>, <span class=\"citation\">II Kings XXIV, 16</span>) <span dir=\"rtl\">אלו … תפלת ח׳ בלחש וכ׳</span> <i>ḥarash</i></div>","alt":[]},"10056":{"h":"חֶרֶשׂ ²","r":"H01783","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥeres</i> or <i>Ḥeresh.</i> <span class=\"citation\">Ab. IV, 15</span>. <span class=\"citation\">Yoma 4ᵇ</span>; a. e.</div>","alt":["חֶרֶשׁ"]},"10057":{"h":"חֵרֵשׁ","r":"H01784","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>closed up</i>,] <i>deaf, dumb</i> (cmp. <a href=\"#\" data-headword=\"אִלֵּם\">אִלֵּם</a>); <i>deaf and dumb.</i> <span class=\"citation\">Ter. I, 2</span> <span dir=\"rtl\">ח׳ שדברו וכ׳</span> the <i>ḥeresh</i> of which the scholars speak (in a legal sense) means everywhere <i>deaf and dumb</i>. Ib. <span dir=\"rtl\">ח׳ המדבר וכ׳</span> a <i>ḥeresh</i> that can talk but not hear. <span class=\"citation\">Meg. II, 4</span> <span dir=\"rtl\">חוץ מח׳</span> except a deaf person. <span class=\"citation\">Sifré Num. 153</span> (ref. to <span class=\"citation\">Num. XXX, 5</span>; <span class=\"citation\">12</span>) <span dir=\"rtl\">להוציא את הח׳</span> this excludes the case of the father (the husband) being deaf; <span class=\"citation\">Ned. 73ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">חֵרְשִׁים</span>, <a href=\"#\" data-headword=\"חַרְשִׁין\">חֵרְשִׁין</a>. <span class=\"citation\">Ḥag. 14ᵃ</span>; <span class=\"citation\">Gitt. 88ᵃ</span>, v. <a href=\"#\" data-headword=\"חָרָשׁ\">חָרָשׁ</a>. <span class=\"citation\">Ruth R. s. 2</span> beg. (ref. to <a href=\"#\" data-headword=\"חָרַשׁ I\">חרש</a>, <span class=\"citation\">Josh. II, 1</span>) <span dir=\"rtl\">עשו עצמכם ח׳</span> pretend to be deaf.—<i>Fem.</i> <span dir=\"rtl\">חֵרֶשֶׁת</span>. <span class=\"citation\">Gitt. V, 5</span>. <span class=\"citation\">Yeb. XIV, 1</span>; a. e.—Pl. <span dir=\"rtl\">חֵרְשׁוֹת</span>. <span class=\"citation\">Ib. 3</span>.</div>","alt":[]},"10058":{"h":"חַרְשָׁא","r":"H01785","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. IV, 11</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"חַרְשִׁין\">חֵרְשִׁין</a>, <a href=\"#\" data-headword=\"חַרְשִׁין\">חַרְשַׁיָּא</a>. <span class=\"citation\">Targ. Is. LVI, 10</span>; a. e.—Y. Ber. IX, end, 14ᵈ כל חרשייא טבין וכ׳ Var. (v. <a href=\"#\" data-headword=\"כַּדָּבָא\">כַּדָּבָא</a>) all dumb (silent) persons are good, but those silent (abstaining) from reciting the Law are bad.</div>","alt":["חֵירְשָׁא"]},"10059":{"h":"חָרָשָׁא","r":"H01786","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֶרֶשׁ\">חֶרֶשׁ</a>; cmp. <a href=\"#\" data-headword=\"לַחַשׁ\">לַחַשׁ</a>) <i>fascinator, charmer, sorcerer</i>. <span class=\"citation\">Targ. O. Deut. XVIII, 10</span> (some ed. <a href=\"#\" data-headword=\"חָרַשׁ I\">חֲרָשׁ</a>); a. e.—<span class=\"citation\">Cant. R. to III, 6</span>. <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> bot. <span dir=\"rtl\">עיסקיה דהדין ח׳ וכ׳</span> it is the nature of a sorcerer that he can do nothing when lifted from the ground. <span class=\"citation\">Ber. 62ᵃ</span> bot. (in an incantation) <span dir=\"rtl\">לא חַרְשֵׁי דח׳ וכ׳</span> (Var. <span dir=\"rtl\">דחָרָשֵׁי …</span> pl., v. Rabb. D. S. a. l, note 8) no charm of a sorcerer or of a sorceress.—Pl. <a href=\"#\" data-headword=\"חַרְשִׁין\">חָרָשִׁין</a>, <span dir=\"rtl\">חָרָשַׁיָּא</span>, <span dir=\"rtl\">חָרָשֵׁי</span>, <a href=\"#\" data-headword=\"חוֹרָן\">חֲרָ׳</a>. Targ. Y. Deut. l. c. (ed. Amst. <a href=\"#\" data-headword=\"חַרְשִׁין\">חַרְשִׁין</a>). <span class=\"citation\">Targ. Ps. LVIII, 6</span>; a. e.—Y. Ḥag. l. c.; Y. Snh. VI, 23ᶜ bot.—<i>Fem.</i> <span dir=\"rtl\">חָרָשָׁא חֲרַשְׁתָּא</span>,. <span class=\"citation\">Targ. O. Ex. XXII, 17</span>.—Ber. l. c. (Var. <a href=\"#\" data-headword=\"חַרְשִׁיתָא\">חַרְשִׁיתָא</a>).—V. <a href=\"#\" data-headword=\"חַרְשִׁין\">חַרְשִׁין</a>.</div>","alt":["חָרָשׁ"]},"10060":{"h":"חַרְשֵׁי","r":"H01787","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"חָרָשָׁא\">preced.</a>) <i>sorcery</i>, v. <a href=\"#\" data-headword=\"חַרְשִׁין\">חַרְשִׁין</a>.</div>","alt":[]},"10061":{"h":"חַרְשְׁיוּתָא","r":"H01788","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"חַרְשֵׁי\">same</a>. <span class=\"citation\">Targ. Y. Ex. XXII, 17</span>; a. e.—V. <a href=\"#\" data-headword=\"חֲרוּשְׁתָּא\">חֲרוּשְׁתָּא</a></div>","alt":[]},"10062":{"h":"חַרְשִׁין","r":"H01789","html":"<div class=\"sense\">, m. pl. <i>sorcery, witchcraft</i>. <span class=\"citation\">Targ. Koh. XI, 4</span> (ed. Amst. <a href=\"#\" data-headword=\"חוֹרָן\">חֲרָ׳</a>); a. fr.—<span class=\"citation\">Sabb. 75ᵃ</span>, v. <a href=\"#\" data-headword=\"אַמְגּוּשְׁתָּא\">אַמְגּוּשְׁתָּא</a>. <span class=\"citation\">Ber. 62ᵃ</span> bot., v. <a href=\"#\" data-headword=\"חָרָשָׁא\">חָרָשָׁא</a>. <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">לית ח׳ מצלחין וכ׳</span> (not <span dir=\"rtl\">חרשון</span>) witchcraft has no effect by night. <span class=\"citation\">Gen. R. s. 86</span> <span dir=\"rtl\">ח׳ במצרים</span> sorcery imported to Egypt!, v. <a href=\"#\" data-headword=\"חֲרַשׁ\">חֲרַשׁ</a> 3.—<span class=\"citation\">Ḥull. 84ᵇ</span>; <span class=\"citation\">B. Mets. 29ᵇ</span> <span dir=\"rtl\">כסא דח׳ וכ׳</span> rather drink a cupfull of witchcraft (charmed drink) than of tepid water. <span class=\"citation\">Pes. 110ᵃ</span>, v. <a href=\"#\" data-headword=\"חַרְשִׁיתָא\">next w.</a></div>","alt":["חַרְשַׁיָּיא","חַרְשֵׁי","חֲרָ׳"]},"10063":{"h":"חַרְשִׁיתָא","r":"H01790","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חַרְשִׁין\">preced.</a>) <i>sorceress</i>. <span class=\"citation\">Ber. 62ᵃ</span>, v. <a href=\"#\" data-headword=\"חָרָשָׁא\">חָרָשָׁא</a>.—Pl. <span dir=\"rtl\">חַרְשָׁיָין</span>, <a href=\"#\" data-headword=\"חַרְשְׁיוּתָא\">חַרְשְׁיָיתָא</a>. <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> bot. <span dir=\"rtl\">נשיין ח׳</span> women practicing witchcraft. <span class=\"citation\">Pes. 110ᵃ</span> נשי ח׳ Rashi (ed. <span dir=\"rtl\">נשי דחרשייא</span>, Ms. M. <span dir=\"rtl\">דחרושתא</span>), v. <a href=\"#\" data-headword=\"חֲרוּשְׁתָּא\">חֲרוּשְׁתָּא</a>.</div>","alt":[]},"10064":{"h":"חֲרַשְׁתָּא","r":"H01791","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָרָשָׁא\">חָרָשָׁא</a></div>","alt":[]},"10065":{"h":"חָ","r":"H01792","html":"<div class=\"sense\"><i>to engrave</i>. Part. pass. <a href=\"#\" data-headword=\"חָרוּת I\">חָרוּת</a>, v. <a href=\"#\" data-headword=\"חֵירוּת\">חֵירוּת</a></div>","alt":["רַ","ת"]},"10066":{"h":"חֲרַת","r":"H01793","html":"<div class=\"sense\">Part. pass. <a href=\"#\" data-headword=\"חָרִית\">חָרִית</a>, pl. <span dir=\"rtl\">חֲרִיתִין</span>. <span class=\"citation\">Targ. O. Lev. XIX, 28</span> (ed. Berl. <span dir=\"rtl\">חֲרִיתִּ׳</span>). <span class=\"citation\">Targ. Jer. XVII, 1</span>.</div>","alt":[]},"10067":{"h":"חֶרֶת","r":"H01794","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חרר III) <i>soot, sediment of ink, shoe-black</i>. <span class=\"citation\">Nidd. II, 7</span> <span dir=\"rtl\">כח׳</span>; <span class=\"citation\">ib. 19ᵃ</span> <span dir=\"rtl\">כחָרוּת</span>; <span class=\"citation\">Tosef. ib. III, 11</span> (not <span dir=\"rtl\">בה׳</span>); expl. <span class=\"citation\">Nidd. 20ᵃ</span> <span dir=\"rtl\">כי חרותא דדיותא</span>, v. <a href=\"#\" data-headword=\"דְּיוּתָא\">דְּיוּתָא</a>.—Y. Sot. VII, 22ᵈ <span dir=\"rtl\">חָרוּתָהּ אש וכ׳</span> its ink was black fire. <span class=\"citation\">Y. Kil. IX, 32ᵃ</span> top <span dir=\"rtl\">פשתן שצבעו בח׳</span> (ed. <span dir=\"rtl\">בחרם</span>, corr. acc.) linen dyed with blacking (looking like wool).</div>","alt":[]},"10068":{"h":"חַרְתָּא I","r":"H01795","html":"<div class=\"sense\"><span class=\"citation\">Sabb. 104ᵇ</span>; <span class=\"citation\">Gitt. 19ᵃ</span>, v. <a href=\"#\" data-headword=\"אוּשְׁכָּפָא\">אוּשְׁכָּפָא</a>. <span class=\"citation\">Lam. R. to IV, 8</span>.</div>","alt":[]},"10069":{"h":"חַרְתָּא II","r":"H01796","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חרר III) [<i>heat</i>,] <i>strife, anger</i>. <span class=\"citation\">Targ. Prov. XV, 18</span>; <span class=\"citation\">XVIII, 6</span> (ed. Lag. <a href=\"#\" data-headword=\"הַרְתָּא\">הַרְתָּא</a>).</div>","alt":[]},"10070":{"h":"חֻרְתָּא","r":"H01797","html":"<div class=\"sense\">, v. <span dir=\"rtl\">חוּר׳</span></div>","alt":[]},"10071":{"h":"חָרְתָּא","r":"H01798","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חוֹרָא II\"><span dir=\"rtl\">חוֹרָא</span> II</a>) <i>a free woman</i>.—Pl. <a href=\"#\" data-headword=\"חַרְתָּא I\">חָרָתָא</a>. <span class=\"citation\">Yeb. 118ᵇ</span> <a href=\"#\" data-headword=\"חוֹזָאֵי\">בי ח׳</a> among the women of nobility; <span class=\"citation\">Keth. 75ᵃ</span> <span dir=\"rtl\">חָרָאתָא</span>.</div>","alt":[]},"10072":{"h":"חַרְתָּנָא","r":"H01799","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חַרְתָּא II\"><span dir=\"rtl\">חַרְתָּא</span> II</a>) <i>querulous man</i>. <span class=\"citation\">Targ. Prov. XVI, 28</span> (ed. Lag. <span dir=\"rtl\">הַ׳</span>; some ed. <a href=\"#\" data-headword=\"דרתנא\">דרתנא</a>, incorr.)</div>","alt":[]},"10073":{"h":"חָשׁ","r":"H01800","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּשׁ\">חוּשׁ</a>, <a href=\"#\" data-headword=\"חָשַׁשׁ\">חָשַׁשׁ</a>, <a href=\"#\" data-headword=\"חֲשַׁשׁ\"><a href=\"#\" data-headword=\"חֲשַׁשׁ\">חֲשַׁשׁ</a>.</a></div>","alt":["חַשׁ"]},"10074":{"h":"חֲשָׁא","r":"H01801","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשִׁי\">חֲשִׁי</a></div>","alt":[]},"10075":{"h":"חָשָׁא","r":"H01802","html":"<div class=\"sense\"> (or <a href=\"#\" data-headword=\"חָשָׁא\">חַשָׁא</a>) m. (<a href=\"#\" data-headword=\"חוּשׁ\">חוּשׁ</a>, <a href=\"#\" data-headword=\"חֲשַׁשׁ\">חֲשַׁשׁ</a>; cmp. P. Sm. 1391) <i>what man has to suffer, predestination, luck</i>.—Pl. <span dir=\"rtl\">חָשַׁיָּא</span> or <a href=\"#\" data-headword=\"חַשָּׁבָא\">חַשַּׁ׳</a>. <span class=\"citation\">Lam. R. to I, 16</span> <span dir=\"rtl\">דחָשַׁיֵּיה קשיי לינוקי</span> hard fates are in store for my child (Matt. K. quotes a version <span dir=\"rtl\">נחשייה</span>, v. <a href=\"#\" data-headword=\"נַחַשׁ ²\">נַחֲשָׁא</a>). Ib. [read:] <span dir=\"rtl\">לא אמרית לך דח׳ קשייא ליה דעל ריגליה חרב בית מקדשא</span>.</div>","alt":[]},"10076":{"h":"חֲשָׁאֵי","r":"H01803","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. P. Sm. 1391) <i>thyme</i>. <span class=\"citation\">Sabb. 128ᵃ</span>, expl. <a href=\"#\" data-headword=\"קוֹרָנִיתָא\">קורניתא</a> (v. Löw Pfl. p. 181).</div>","alt":["חָשֵׁי"]},"10077":{"h":"חֲשַׁאי","r":"H01804","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָשָׁה\">חָשָׁה</a>) <i>whispering, stillness, secret</i>. <span class=\"citation\">Pes. 56ᵃ</span> <span dir=\"rtl\">להביא בח׳</span> to offer it to her in secret. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שיהו אומרים … בח׳</span> that they say it in a whisper. <span class=\"citation\">Arakh. 16ᵃ</span>; <span class=\"citation\">Zeb. 88ᵇ</span>; <span class=\"citation\">Yoma 44ᵃ</span> <span dir=\"rtl\">דבר שבח׳</span> something done in secrecy (the offering of frank-incense on the inner altar); <span dir=\"rtl\">מעשה שבח׳</span> what is committed in secrecy (calumny). <span class=\"citation\">Ber. 15ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">חֲשָׁאִים</span>. <span class=\"citation\">Shek. V, 6</span> <span dir=\"rtl\">לשכת ח׳</span> the Hall of Secret (donations).</div>","alt":[]},"10078":{"h":"חֲשַׁאי ²","r":"H01805","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ps. XLI, 8</span>. <span class=\"citation\">Targ. Job IV, 16</span>; a. e.</div>","alt":["חֲשַׁי","חֲשַׁיי"]},"10079":{"h":"חָשַׁב","r":"H01806","html":"<div class=\"sense\"><b>1)</b> <i>to think, intend, plan</i>. <span class=\"citation\">Ber. 6ᵃ</span>; <span class=\"citation\">Kidd. 40ᵃ</span> (ref. to <span class=\"citation\">Mal. III, 16</span>) <span dir=\"rtl\">אפי׳ ח׳ אדם וכ׳</span> even if one only had the intention of doing etc.; <span class=\"citation\">Sabb. 63ᵃ</span> <a href=\"#\" data-headword=\"חָשַׁב\">חִישֵּׁב</a> (<i>Pi.</i>).—Tanḥ. P’kudé 11 <span dir=\"rtl\">וכשהן חוֹשְׁבִין להעמידו וכ׳</span> and when they thought they had put it up, it fell apart again. <span class=\"citation\">Sot. 35ᵃ</span> אני חֲשַׁבְתִּיהָ … והם חָשְׁבוּ וכ׳ I planned it for their good, but they considered it an evil; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to consider, regard; to count</i>. <span class=\"citation\">Ber. 14ᵃ</span> (ref. to <span class=\"citation\">Is. II, 22</span>) <span dir=\"rtl\">במה חֲשַׁבְתּוֹ לזה ולא לאלוה</span> with what right didst thou pay thy regard to him and not to God?—Sot. l. c., v. supra. <span class=\"citation\">Pesik. R. s. 21</span>, v. <a href=\"#\" data-headword=\"סוֹפִיסְטָא\">סוֹפִיסְטָא</a>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to design, trace</i>. <span class=\"citation\">Yoma 72ᵇ</span> (ref. to <span dir=\"rtl\">חשב</span> a. <span dir=\"rtl\">רקם</span>, <span class=\"citation\">Ex. XXVI</span>, 31ᵃ 36) <span dir=\"rtl\">רוקמין במקום שחוֹשְׁבִין</span> they embroidered over what they had traced.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חָשׁוּב\">חָשׁוּב</a> fem. <span dir=\"rtl\">חֲשׁוּבָה</span> a) <i>counted, regarded</i>; <span dir=\"rtl\">ח׳ כ־</span> <i>equal to</i>. <span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">לא … מדינה ח׳ כלום</span> the country towns were of no account. <span class=\"citation\">Ned. 64ᵇ</span> <span dir=\"rtl\">ח׳ כמת</span> is like dead; <span class=\"citation\">ib.</span> <span dir=\"rtl\">חֲשׁוּבִין כמת</span>; <span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">חֲשׁוּבִים כמתים</span>; a. fr.—b) <i>valuable; important; respectable, of high standing</i>. <span class=\"citation\">Bets. 3ᵇ</span> <span dir=\"rtl\">ביצה ח׳</span> an egg is a valuable object. <span class=\"citation\">Ber. 19ᵃ</span>, a. fr. <span dir=\"rtl\">אדם ח׳ שאני</span> with a man of high standing it is different. <span class=\"citation\">Pes. 108ᵃ</span> <span dir=\"rtl\">אשה ח׳</span> a woman of rank. Tanḥ. Shmini 9 <span dir=\"rtl\">איש ח׳ שמחשבים וכ׳</span> a man of standing whom they respected in his place; a. fr.</div><div class=\"sense\"><b>Pi. חִישֵּׁב</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲשַׁאי ²\">same</a>, </div><div class=\"sense\"><b>1)</b> <i>to consider, regard; to respect</i>, v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to account, calculate, figure</i>. <span class=\"citation\">B. Bath. 78ᵇ</span> <span dir=\"rtl\">המְחַשְּׁבִים</span> the thoughtful. <span class=\"citation\">Sabb. 150ᵃ</span>. <span dir=\"rtl\">חשבונות … לחַשְּׁבָן וכ׳</span> accounts of a religious nature may be figured out on the Sabbath. <span class=\"citation\">Ab. II, 1</span> <span dir=\"rtl\">הוי מְחַשְּׁב וכ׳</span> count what you sacrifice in doing good, against what you gain thereby. <span class=\"citation\">Snh. 65ᵇ</span> <span dir=\"rtl\">המח׳ עתים וכ׳</span> he who calculates seasons and hours (which are auspicious and which are not). <span class=\"citation\">Ib. 97ᵇ</span> <span dir=\"rtl\">מְחַשְּׁבֵי קיצין</span> those who make calculations (from Biblical verses) as to when the Messiah will come; a. fr.—[<span class=\"citation\">Sabb. 150ᵇ</span> top <span dir=\"rtl\">מותר לחוֹשְׁבָן</span> (Kal), Ms. M. <span dir=\"rtl\">לחַשְּׁ׳</span>.]—V. <a href=\"#\" data-headword=\"חֶשְׁבּוֹן\">חֶשְׁבּוֹן</a>.</div><div class=\"sense\"><b>—3)</b>  (sub. <span dir=\"rtl\">מחשבה זרה</span>) <i>to have in mind an undue intention in the performance of a sacrificial ceremony</i>. <span class=\"citation\">Yoma 48ᵃ</span> <span dir=\"rtl\">חי׳ בחפינת וכ׳</span> if he had an undue intention when grasping the frankincense (e.g. to offer it tomorrow). <span class=\"citation\">Ib.ᵇ</span>; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְחַשֵּׁב</b> </div><div class=\"sense\"><b>Nithpa. נִתְחַשֵּׁב</b> <div class=\"sense\"><b>1)</b> <i>to be counted.</i> Ohol. I, 3 <span dir=\"rtl\">אין האהל מִתְחַשֵּׁב</span> the tent is not counted (as a special item). <span class=\"citation\">Yalk. Num. 768</span> <span dir=\"rtl\">מתח׳ לנו</span> will be counted against us (be deducted from our share). <span class=\"citation\">Mikv. III, 3</span> <span dir=\"rtl\">עד שיִתְחַשֵּׁב וכ׳</span> until it is calculated that all the original water has run off. <span class=\"citation\">Pesik. R. s. 44</span> the former sins <span dir=\"rtl\">אינן מִתְחַשְּׁבוֹת לו וכ׳</span> are not counted or remembered to him.</div><div class=\"sense\"><b>—2)</b> <i>to be considered, believed to be</i>. Tanḥ. Masé 5, v. <a href=\"#\" data-headword=\"כַּזְבָּן\">כַּזְבָּן</a>.</div><div class=\"sense\"><b>—3)</b> <i>to occupy a high position.</i> <span class=\"citation\">Shebi. VIII, 11</span> <span dir=\"rtl\">אם מתחשב הוא</span> (Ms. M. <span dir=\"rtl\">כמ׳</span>, v. Rabb. D. S. a. l. note) if he (is like one who) holds a high position.</div><div class=\"sense\"><b>—4)</b> <i>to conspire</i> (with the Romans). <span class=\"citation\">Tosef. Ab. Zar. II, 7</span> <span dir=\"rtl\">ואם מתחשב וכ׳</span> but when he (the Israelite besieging a city) does it as an ally (in the Roman interest), he is forbidden (to conduct the siege); <span class=\"citation\">Ab. Zar. 18ᵇ</span> <span dir=\"rtl\">ובלבד שלא יִתְחַשֵּׁב עמהם</span> provided he does not conspire with them; <span dir=\"rtl\">ואם נתח׳ וכ׳</span> (Ms. M. <span dir=\"rtl\">יתח׳</span>); Y. ib. I, 40ᵃ <span dir=\"rtl\">מתחשד</span> (corr. acc.).</div></div>","alt":[]},"10080":{"h":"חֲשֵׁב","r":"H01807","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. L, 20</span>. <span class=\"citation\">Targ. Esth. VIII, 3</span>; a. fr.—Pesik. B’shall., p. 82ᵃ (translating <span class=\"citation\">Ex. XVIII</span>, 11ᵇ) <span dir=\"rtl\">במחשבה דחַשְׁבוּן איתחשב להון</span> what they had planned (against Israel) was planned against them. <span class=\"citation\">Sabb. 3ᵃ</span> <span dir=\"rtl\">קא חֲשִׁיב</span> he counts in; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חֲשִׁיב\">חָשִׁיב</a>, pl<i>.</i> <span dir=\"rtl\">חֲשִׁיבִין</span> = h. <a href=\"#\" data-headword=\"חָשׁוּב\">חָשׁוּב</a>, v. <a href=\"#\" data-headword=\"חָשַׁב\">preced.</a> <span class=\"citation\">Targ. Y. Ex. IV, 19</span>; a. fr.—<span class=\"citation\">Keth. 8ᵇ</span> <span dir=\"rtl\">ח׳ את וכ׳</span> thou hast been found worthy to be seized (to suffer) for etc. <span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">מאן ח׳ וכ׳</span> who is highly esteemed in that world (the hereafter)?; a. fr.</div><div class=\"sense\"><b>Pa. חַשֵּׁיב</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָשַׁב\">same</a>, <i>to plan, to count, calculate</i>. <span class=\"citation\">Targ. Jer. XXI, 11</span>.—<span class=\"citation\">Targ. O. Lev. XXV, 27</span>; a. fr.—<span class=\"citation\">Meg. 11ᵇ</span> <span dir=\"rtl\">חַשִּׁיב ועייל וכ׳</span> count, and include in their place &amp;c. <span class=\"citation\">Pes. 94ᵃ</span> <span dir=\"rtl\">דקא חַשְּׁבֵי דקדמא וכ׳</span> because they also counted the distances which one walks before dawn and after sunset. <span class=\"citation\">Sabb. 74ᵃ</span> <span dir=\"rtl\">וליחַשֵּׁב וכ׳</span> let him also count the act of pounding; <span class=\"citation\">ib. 6ᵇ</span>; a. e. <span dir=\"rtl\">ולִחְשׁוֹב</span> (Pe.); a. fr. [Y. Pes. IV, end, 31ᶜ <span dir=\"rtl\">מחשבנא</span> v. <a href=\"#\" data-headword=\"חֲשַׂךְ\">חֲשַׂךְ</a>.]</div></div><div class=\"sense\"><b>Ithpa. אִתְחַשֵּׁב</b> </div><div class=\"sense\"><b>Ithpe. אִתְחֲשַׁב</b> <div class=\"sense\"> <span dir=\"rtl\">אִיחֲשַׁב</span> </div><div class=\"sense\"><b>1)</b> <i>to be planned</i>. <span class=\"citation\">Targ. O. Gen. L, 20</span>.—Pesik. l. c., v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to be considered, valued</i>. <span class=\"citation\">Targ. Lev. XVII, 4</span>. <span class=\"citation\">Targ. Ps. L, 23</span>; a. fr.—[<span class=\"citation\">Targ. Prov. XXIX, 11</span> מֵיחֲשַׁב Ms. (ed. Lag. <span dir=\"rtl\">מחשב</span>, Var. <span dir=\"rtl\">מאשב</span>) <i>is respected</i> (v. Pesh. a. l.; ed. Wil. <span dir=\"rtl\">מאכה</span> v. <a href=\"#\" data-headword=\"מְאַךְ\">מְאַךְ</a>).]</div></div>","alt":["(חֲשֵׁיב)"]},"10081":{"h":"חַשָּׁבָא","r":"H01808","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲשֵׁב\">preced.</a>) <i>accountant, calculator</i>.—Pl. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"חַשָּׁבָא\">חֲשָׁ׳</a>) <span dir=\"rtl\">חַשָּׁבַיָּא</span></span>. <span class=\"citation\">Targ. Is. XXXIII, 18</span>.</div>","alt":["(חֲשָׁ׳)"]},"10082":{"h":"חֶשְׁבּוֹן","r":"H01809","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חַשָּׁבָא\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>account, sum; accountability; punishment and reward</i>. <span class=\"citation\">B. Bath. 9ᵇ</span> <span dir=\"rtl\">ח׳ גדול</span> sum total. <span class=\"citation\">Ib. 78ᵇ</span> (play on <i>Ḥeshbon</i>, <span class=\"citation\">Num. XXI, 27</span>; <span class=\"citation\">30</span>) <span dir=\"rtl\">באו ונחשב חֶשְׁבּוֹנוֹ וכ׳</span> come and let us examine the account of the world (human affairs), the loss etc. Ib. <span dir=\"rtl\">אבד ח׳ וכ׳</span> the accountability of the world is gone (there is no reward or punishment). <span class=\"citation\">Ex. R. s. 51</span>, beg., a. fr. <span dir=\"rtl\">ליתן ח׳</span> to render an account. <span class=\"citation\">Tosef. B. Kam. X, 21</span> <span dir=\"rtl\">מה ח׳ עשה וכ׳</span> how our father settled with yon; Y. ib. X, 7ᵇ bot.—<span class=\"citation\">Y. Ab. Zar. II, 42ᵃ</span> top <span dir=\"rtl\">ח׳ מים וכ׳</span> he understands the calculation of the action of the water. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ח׳ גדול הוא</span> this is a great thing to calculate; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>promptness in business</i>. <span class=\"citation\">Deut. R. s. 4</span> איני מכיר חֶשְׁבּוֹנְךָ I do not know your way of settling (whether you are prompt); <span class=\"citation\">ib.</span> <span dir=\"rtl\">עשית לי ח׳ טוב</span> you paid me promptly. [<span class=\"citation\">Yalk. Deut. 808</span> <span dir=\"rtl\">הח׳</span> read <span dir=\"rtl\">בעל הח׳</span> <i>market commissioner</i>.]—Pl. <span dir=\"rtl\">חֶשְׁבּוֹנוֹת</span>. <span class=\"citation\">Sabb. 150ᵃ</span>, sq., v. <a href=\"#\" data-headword=\"חָשַׁב\">חָשַׁב</a>. <span class=\"citation\">Bekh. 5ᵃ</span> <span dir=\"rtl\">בקי בח׳</span> a good arithmetician.</div>","alt":[]},"10083":{"h":"חֶשְׁבּוֹנָא","r":"H01810","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּשְׁבָּנָא\">חוּשְׁבָּנָא</a></div>","alt":[]},"10084":{"h":"חָשַׂד","r":"H01811","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָסַד II\"><span dir=\"rtl\">חָסַד</span> II</a></div>","alt":[]},"10085":{"h":"חָשַׁד","r":"H01812","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חָשָׁה\">חָשָׁה</a>) [<i>to whisper</i>,] <i>to suspect</i> (cmp. <a href=\"#\" data-headword=\"דּוּם\">דּוּם</a> a. <a href=\"#\" data-headword=\"דמי\">דִּימָה</a>). <span class=\"citation\">Yoma 19ᵇ</span>, a. e. <span dir=\"rtl\">החוֹשֵׁד בכשרים</span> he who entertains a suspicion against worthy men. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חֲשָׁדוּהוּ</span> (<a href=\"#\" data-headword=\"ב\">ב</a>)<span dir=\"rtl\">צדוקי</span> they suspected him of being a Sadducee. <span class=\"citation\">Sabb. 127ᵇ</span> <span dir=\"rtl\">במה חֲשַׁדְתַּנִי</span> whereof did you suspect me?—<span class=\"citation\">Ib. 118ᵇ</span>; <span class=\"citation\">M. Kat. 18ᵇ</span> <span dir=\"rtl\">מי שחוֹשְׁדִין וכ׳</span> whom people suspect without cause; a. fr.—Part. pass. <span dir=\"rtl\">חָשׁוּד</span>, f. <span dir=\"rtl\">חֲשׁוּדָה</span>; pl. <span dir=\"rtl\">חֲשׁוּדִים</span>, <span dir=\"rtl\">חֲשׁוּדִין</span>; <span dir=\"rtl\">חֲשׁוּדוֹת</span>. <span class=\"citation\">Dem. III, 5</span>, v. <a href=\"#\" data-headword=\"חָלַף\">חָלַף</a>. <span class=\"citation\">Erub. 69ᵃ</span> <span dir=\"rtl\">ח׳ לדבר אחד ח׳ וכ׳</span> one who is suspected of neglecting one religious law, is suspected of disregarding the whole Law; <span class=\"citation\">Bekh. 30ᵇ</span>. <span class=\"citation\">Ib. 30ᵃ</span> <span dir=\"rtl\">ח׳ על השביעית</span> suspected of ignoring the laws of the Sabbatical year. <span class=\"citation\">Shebu. 32ᵇ</span>, a. fr. <span dir=\"rtl\">ח׳ על השבועה</span> suspected of swearing falsely (not admitted to oaths). <span class=\"citation\">Y. Taan. III, beg. 66ᵇ</span> <span dir=\"rtl\">מפני פרנסת ח׳</span> for the sustenance of those suspected (of neglecting the laws of the Sabbatical year); a. fr.</div><div class=\"sense\"><b>Nif. נֶחְשַׁד</b> <div class=\"sense\"><i>to be suspected</i>. <span class=\"citation\">Ber. 31ᵇ</span> (ref. to <span class=\"citation\">I Sam. I, 16</span>) <span dir=\"rtl\">מבאן לנ׳ בדבר וכ׳</span> from this we learn that he who is unjustly suspected, must make it known (clear himself). <span class=\"citation\">Bekh. 30ᵇ</span>; <span class=\"citation\">Ab. Zar. 39ᵃ</span> <span dir=\"rtl\">עד שיֵחָשְׁדוּ</span> until there is reason to suspect them of neglecting the observances of the associates (v. <a href=\"#\" data-headword=\"חָבֵר\">חָבֵר</a>); a. fr.—[Y. Ab. Zar. I, 40ᵃ <span dir=\"rtl\">מתחשד</span>, v. <a href=\"#\" data-headword=\"חָשַׁב\">חָשַׁב</a>.]</div></div>","alt":[]},"10086":{"h":"חֲשַׁד","r":"H01813","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Deut. XXIV, 9</span>.—<span class=\"citation\">Sabb. 118ᵇ</span> <span dir=\"rtl\">לדידי חַשְׁדָּן וכ׳</span> they suspected me without cause; a. fr.—Part. pass. <a href=\"#\" data-headword=\"חֲשִׁיד\">חָשִׁיד</a>. <span class=\"citation\">Ber. 5ᵇ</span> <span dir=\"rtl\">ומי חֲשִׁידְנָא וכ׳</span> am I suspected by you (of doing wrong)?; <span dir=\"rtl\">ומי ח׳ קב&quot;ה וכ׳</span> can the Lord be suspected of injustice?, v. <a href=\"#\" data-headword=\"דִּין ²\">דִּינָא</a>. <span class=\"citation\">Shebu. 32ᵇ</span> <span dir=\"rtl\">דח׳ מאן</span> which of the contestants is suspected (of swearing falsely)?; a. fr.</div><div class=\"sense\"><b>Ithpe. אִתְחֲשַׁד</b> <div class=\"sense\"><i>to be suspected</i>. <span class=\"citation\">Targ. Y. Deut. XXI, 3</span>.</div></div>","alt":[]},"10087":{"h":"חָשֵׁד","r":"H01814","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲשַׁד\">preced.</a> wds.) <i>suspected</i>.—Pl. <span dir=\"rtl\">חֲשֵׁדִים</span>; constr. <span dir=\"rtl\">חֲשֵׁדֵי</span>. <span class=\"citation\">Pes. 85ᵃ</span> <span dir=\"rtl\">ח׳ כהונה</span> the suspected among the priesthood, i.e. priests suspected of wilfully unfitting a sacrifice in order to spite the owner.</div>","alt":[]},"10088":{"h":"חֲשָׁד","r":"H01815","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָשֵׁד\">preced.</a> wds.) <i>suspicion</i>. <span dir=\"rtl\">מפני הח׳</span> <i>to avoid suspicion</i>. <span class=\"citation\">Sabb. 23ᵇ</span> <span dir=\"rtl\">מפני הח׳</span> (<span class=\"citation\">Tosef. Peah I, 6</span> <span dir=\"rtl\">מפני מראית העין</span>) to avoid suspicion (as if he appropriated to himself the poor man’s share). <span class=\"citation\">Yoma 30ᵃ</span>; a. fr.</div>","alt":[]},"10089":{"h":"חֲשָׁדָא","r":"H01816","html":"<div class=\"sense\"> <span class=\"citation\">Ḥag. 5ᵃ</span> <span dir=\"rtl\">מייתי לה לידי ח׳</span> exposes her to suspicion.—משום ח׳ <i>to avoid suspicion</i>. <span class=\"citation\">Ber. 43ᵇ</span>; a. fr.—</div>","alt":[]},"10090":{"h":"חָשָׁה","r":"H01817","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חשי\">חשי</a></div>","alt":[]},"10091":{"h":"חָשׁוּ","r":"H01818","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥashu</i>. <span class=\"citation\">Keth. 84ᵇ</span> bot. <span dir=\"rtl\">יימר בר ח׳</span>.</div>","alt":[]},"10092":{"h":"חָשׁוּב","r":"H01819","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָשַׁב\">חָשַׁב</a></div>","alt":[]},"10093":{"h":"חָשׁוּךְ","r":"H01820","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>dark, black</i>. <span class=\"citation\">Ab. Zar. 8ᵃ</span>, v. <a href=\"#\" data-headword=\"חָשַׁךְ\">חָשַׁךְ</a>.—Pl. <span dir=\"rtl\">חֲשׁוּכִּים</span>, <span dir=\"rtl\">כִּין …</span>; f. <span dir=\"rtl\">חֲשׁוּכּוֹת</span>. <span class=\"citation\">Bekh. VII, 5</span> (expl. <span dir=\"rtl\">מרוח אשך</span>, <span class=\"citation\">Lev. XXI, 20</span>) <span dir=\"rtl\">שמראיו ח׳</span> whose complexion is very dark. <span class=\"citation\">Yalk. Ex. 258</span> <span dir=\"rtl\">פנים ח׳</span> dark (frowning) countenance; Mekh. B’shall., Vayassa, s. 2 <span dir=\"rtl\">חֲשֵׁכוֹת</span>.</div><div class=\"sense\"><b>—2)</b> <i>obscured, benighted</i>. <span class=\"citation\">Pesik. R. s. 6</span>, beg. (ref. to <span class=\"citation\">Prov. XXII, 29</span>) <span dir=\"rtl\">פרעה הח׳</span> Pharaoh, the benighted.—<i>Pl.</i> as ab. <span class=\"citation\">Cant. R. to I, 1</span> (ref. to Prov. l. c.) <span dir=\"rtl\">לפני ח׳ אלו הרשעים</span> ‘before the benighted’ that means the wicked.</div>","alt":[]},"10094":{"h":"חֲשׁוֹךְ","r":"H01821","html":"<div class=\"sense\"> ch. </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חָשׁוּךְ\">same</a>, <i>dark</i>. <span class=\"citation\">Targ. Am. V, 20</span>.</div><div class=\"sense\"><b>—2)</b>  (חֲשַׁךְ II) <i>lean, reduced, poor</i>. v. <a href=\"#\" data-headword=\"חֲשִׁיךְ ²\"><span dir=\"rtl\">חֲשִׁיךְ</span> II</a>.</div>","alt":["חֲשׁוֹכָא I"]},"10095":{"h":"חֲשׁוֹךְ ²","r":"H01822","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲשׁוֹךְ\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>darkness</i>. <span class=\"citation\">Targ. Ex. X, 21</span>, sq.; a. fr.—<span class=\"citation\">Targ. Ez. XIII, 18</span>, v. <a href=\"#\" data-headword=\"רְקִיעָא II\"><span dir=\"rtl\">רְקִיעָא</span> II</a>.—<span class=\"citation\">Pes. 34ᵇ</span> <span dir=\"rtl\">ארעא דח׳</span> a land of darkness (fogs). <span class=\"citation\">Ḥag. 12ᵇ</span> bot. <span dir=\"rtl\">ומי איכא ח׳ וכ׳</span> is there darkness before the Lord?; a. fr.—Pl. <span dir=\"rtl\">חֲשׁוֹכַיָּא</span>. <span class=\"citation\">Targ. Ps. LXXXVIII, 7</span>.</div><div class=\"sense\"><b>—2)</b> <i>charred wick, snuff</i>. <span class=\"citation\">Bets. 32ᵃ</span> עדויי ח׳ Ar. (ed. <a href=\"#\" data-headword=\"חוּשְׁכָּא\">חוּשְׁכָּא</a>). v. <a href=\"#\" data-headword=\"מָחַט\">מָחַט</a>.</div>","alt":["חֲשׁוֹכָא II"]},"10096":{"h":"חשוף","r":"H01823","html":"<div class=\"sense\">, Tanḥ. P’kudé 3, some ed. (oth. ed. <span dir=\"rtl\">חצוף</span>), read <span dir=\"rtl\">סָחוּף</span>, v. <a href=\"#\" data-headword=\"סָחַף\">סָחַף</a></div>","alt":[]},"10097":{"h":"חשופא","r":"H01824","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשִׂיפָה\">חֲשִׂיפָה</a></div>","alt":[]},"10098":{"h":"חַשְׁחַשׁ","r":"H01825","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשַׁשׁ\">חֲשַׁשׁ</a></div>","alt":[]},"10099":{"h":"חשי","r":"H01826","html":"<div class=\"sense\"> (b. h.) [<i>to whisper</i>,] <i>be silent, quiet</i> (cmp. <span dir=\"rtl\">דום</span>, <a href=\"#\" data-headword=\"דָּמַם\">דמם</a>). Part. (fr. <a href=\"#\" data-headword=\"חוּשׁ\">חוּשׁ</a>) <a href=\"#\" data-headword=\"חָשׁ\">חָשׁ</a>, f. <a href=\"#\" data-headword=\"חָשָׁה\">חָשָׁה</a>, pl. <span dir=\"rtl\">חָשׁוֹת</span>. <span class=\"citation\">Ḥag. 12ᵇ</span> <span dir=\"rtl\">אומרות … וחשות ביום וכ׳</span> say praise by night, and are silent by day. <span class=\"citation\">Ib. 13ᵇ</span> (play on <span dir=\"rtl\">ח̇ש̇מ̇ל̇</span>) <span dir=\"rtl\">חיות עתים ח̇ש̇ות … ממ̇ל̇לות</span> Ms. M. <i>Ḥayoth</i> (v. <a href=\"#\" data-headword=\"חַיָּה I\">חַיָּה</a> I end) who at times are silent etc.</div>","alt":["חָשָׁה"]},"10100":{"h":"חֲשִׁי","r":"H01827","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חשי\">same</a>. <span class=\"citation\">Y. Ab. Zar. I, 39ᵇ</span> top <span dir=\"rtl\">חֲשִׁי דמלכא וכ׳</span> hush, for the king wants it so (desires to be worshipped in the form of a calf).be worshipped in the form of a calf).</div><div class=\"sense\"><b>—2)</b>  (= <a href=\"#\" data-headword=\"חוּשׁ\">חוּשׁ</a>) <i>to feel, suffer</i>, v. <a href=\"#\" data-headword=\"חוּשׁ\">חוּשׁ</a> ch.</div>","alt":["חֲשָׁא"]},"10101":{"h":"חֲשַׁי","r":"H01828","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"חֲשַׁאי\">חֲשַׁאי</a></div>","alt":[]},"10102":{"h":"חָשֵׁי","r":"H01829","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשָׁאֵי\">חֲשָׁאֵי</a></div>","alt":[]},"10103":{"h":"חֲשִׁיב","r":"H01830","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָשַׁב\">חֲשַׁב</a></div>","alt":["חֲשֵׁיב"]},"10104":{"h":"חֲשִׁיבָא","r":"H01831","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָשַׁב\">חֲשַׁב</a>) <i>prominent person, notable</i>. . <span class=\"citation\">Gitt. 58ᵃ</span> <span dir=\"rtl\">ח׳ דרומאי</span> the Roman notables. <span class=\"citation\">Ib. 56ᵇ</span> [read:] <span dir=\"rtl\">ואימנו להו ח׳ דר׳ לאותיבך וכ׳</span> and the Roman nobility resolved to place thee at their head; <span class=\"citation\">Yalk. Prov. 953</span>.</div>","alt":[]},"10105":{"h":"חֲשִׁיבוּתָא","r":"H01832","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲשִׁיבָא\">preced.</a>) <i>importance, value</i>. <span class=\"citation\">B. Bath. 146ᵃ</span> <span dir=\"rtl\">ח׳ דא&quot;י</span> ed. (Ms. M. a. F., Rashb. <a href=\"#\" data-headword=\"שְׁבַח\">שְׁבָחָא</a>) the valuableness of Palestine (for its fertility).</div>","alt":[]},"10106":{"h":"חֲשִׁיד","r":"H01833","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשַׁד\">חֲשַׁד</a></div>","alt":[]},"10107":{"h":"חָשֵיךְ","r":"H01834","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשַׂךְ\">חֲשַׂךְ</a></div>","alt":[]},"10108":{"h":"חֲשִׁיךְ","r":"H01835","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (חֲשַׁךְ I) <i>dark, black</i>. <span class=\"citation\">Targ. Y. Lev. XXI, 20</span> חזוייה ח׳ Ar. s. v. <a href=\"#\" data-headword=\"חֵז\">חז</a> whose complexion is very dark (v. <a href=\"#\" data-headword=\"חָשׁוּךְ\">חָשׁוּךְ</a>; ed. <span dir=\"rtl\">פחדוי וכ׳</span>).—<i>Fem.</i> <a href=\"#\" data-headword=\"חֲשִׁיךְ\">חֲשִׁיכָא</a>, pl. <a href=\"#\" data-headword=\"חֲשִׁיכָה\">חֲשִׁיכַן</a>. <span class=\"citation\">Targ. Lam. V, 17</span>.</div>","alt":["חֲשִׁיכָא I"]},"10109":{"h":"חֲשִׁיךְ ²","r":"H01836","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (חֲשַׁךְ II) <i>lean, poor; luckless</i> (interch. with: <a href=\"#\" data-headword=\"חֲשׁוֹךְ\">חֲשׁוֹךְ</a>, <a href=\"#\" data-headword=\"חֲשׁוֹךְ\">חֲשׁוֹכָא</a>). <span class=\"citation\">Targ. Ez. XVIII, 12</span>. <span class=\"citation\">Targ. II Sam. XIII, 4</span>. <span class=\"citation\">Targ. Ps. LXXII, 13</span>; a. fr.—<span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">ולמה ח׳ כן</span> and why is he so reduced?—<span class=\"citation\">Ib. to III, 20</span> (prov.) <span dir=\"rtl\">עד דשמינא חשיך חשיכא מיית</span> Ar. (Var <span dir=\"rtl\">כחיש כחישא</span>; ed. … <span dir=\"rtl\">קטין … דקטינא …</span>) while the fat one becomes lean, the lean one is dead (retribution to the oppressor comes too late). <span class=\"citation\">Midr. Till. to Ps. XXII, 7</span>, v. <a href=\"#\" data-headword=\"חַי\">חַי</a> ch.—Pl. <span dir=\"rtl\">חֲשִׁיכַיָּא</span>, <span dir=\"rtl\">חֲשׁוּכַּ׳</span>. <span class=\"citation\">Targ. Jer. LII, 15</span>, sq.—<span class=\"citation\">Succ. 44ᵇ</span> <span dir=\"rtl\">לחשוכיא</span> (Ms. M. 2 <span dir=\"rtl\">לחסיניא</span>, read <span dir=\"rtl\">לחֲסִיכַ׳</span>) to the poor.—<i>Fem.</i> <a href=\"#\" data-headword=\"חֲשִׁיךְ\">חֲשִׁיכָא</a>, <a href=\"#\" data-headword=\"חֲשִׁיכְתָּא\">חֲשִׁיכְתָּא</a>. <span class=\"citation\">Targ. Is. LIV, 11</span>.—Pl. <a href=\"#\" data-headword=\"חֲשִׁיכָה\">חֲשִׁיכַן</a>, <a href=\"#\" data-headword=\"חֲשִׁיכְתָּא\">חֲשִׁיכָתָא</a>. <span class=\"citation\">Targ. Y. Gen. XLI, 19</span>, sq; v. <a href=\"#\" data-headword=\"חֲסִיךְ\">חֲסִיךְ</a>.</div>","alt":["חֲשִׁיכָא II"]},"10110":{"h":"חֲשֵׁיכָה","r":"H01837","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>darkness, nightfall</i>. <span class=\"citation\">Sabb. II, 7</span> <span dir=\"rtl\">עם ח׳</span> near nightfall. Ib. <span dir=\"rtl\">ספק ח׳ וכ׳</span> if it is doubtful whether or not night has set in; a. fr.—Pl. <span dir=\"rtl\">חֲשֵׁכוֹת</span> (<i>adj.</i>), v. <a href=\"#\" data-headword=\"חָשׁוּךְ\">חָשׁוּךְ</a>.</div>","alt":["חֲשֵׁכָה"]},"10111":{"h":"חֲשִׁיכָה","r":"H01838","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָשַׁךְ\">חָשַׁךְ</a> I<i>Hif.</i>) <i>awaiting the nightfall</i> (on the Sabbath), <i>approaching the Sabbath limit in day-time and waiting there for the night for the transaction of business</i>. <span class=\"citation\">Sabb. 151ᵃ</span> <span dir=\"rtl\">רשאי אני בחֲשִׁיכָתוֹ</span> (Mish. <span dir=\"rtl\">להחשיך עליו</span>) I am permitted to take the preliminary steps for it before nightfall.</div>","alt":[]},"10112":{"h":"חֲשִׁיכְתָּא","r":"H01839","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשִׁיךְ ²\"><span dir=\"rtl\">חֲשִׁיךְ</span> II</a></div>","alt":[]},"10113":{"h":"חֲשִׁיל","r":"H01840","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשַׁל\">חֲשַׁל</a></div>","alt":[]},"10114":{"h":"חֲשִׁילָא","r":"H01841","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"חֲשַׁל\">חֲשַׁל</a>) <i>mashed</i>.—Pl. fem. <a href=\"#\" data-headword=\"חֲשִׁילְתָּא\">חֲשִׁילָתָא</a>. <span class=\"citation\">Ḥull. 93ᵃ</span> bot. <span dir=\"rtl\">ביעי ח׳</span> mashed testicles (undevelopped).</div>","alt":[]},"10115":{"h":"חֲשִׁילְתָּא","r":"H01842","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲשִׁילָא\">preced.</a>; v. <a href=\"#\" data-headword=\"חוּשְׁלָא\">חוּשְׁלָא</a>) <i>a brew made of peeled and pounded fruits</i>, v. <a href=\"#\" data-headword=\"טרִימָּא\">טְרִימָּא</a>. <span class=\"citation\">Ber. 38ᵃ</span> <a href=\"#\" data-headword=\"ח׳\">ח׳</a> (<a href=\"#\" data-headword=\"וַדַּאי\">ודאי</a>) <span dir=\"rtl\">קאמרת</span> (Ms. F. <span dir=\"rtl\">ח׳ דתמרי</span>, v. Rabb. D. S. a. l. note; Ar. <a href=\"#\" data-headword=\"חלישתא\">חלישתא</a>, incorr.) (by <i>trimma</i>) you (surely) mean a brew of ground dates.</div>","alt":[]},"10116":{"h":"חֲשִׂיפָה","r":"H01843","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">חָשַׂף</span>, v. <a href=\"#\" data-headword=\"חֲסַף I\"><span dir=\"rtl\">חֲסַף</span> I</a>) </div><div class=\"sense\"><b>1)</b> <i>stripping, uncovering</i>. <span class=\"citation\">Y. Ber. IX, 13ᵃ</span> top <span dir=\"rtl\">חֲשִׂיפַת זרועו</span> the baring of His arm (<span class=\"citation\">Is. LII, 10</span>).</div><div class=\"sense\"><b>—2)</b> <i>paring, shavings</i> used for basket work. <span class=\"citation\">Tosef. Kil. III, 14</span> הח׳ Var. (ed. Zuck. <span dir=\"rtl\">השופה</span>); Y. ib. V, end, 30ᵃ <span dir=\"rtl\">השיפה</span>. <span class=\"citation\">Tosef. Toh. XI, 16</span> <span dir=\"rtl\">של ח׳</span> quot. by R. s. to <span class=\"citation\">Toh. X, 8</span> (ed. Zuck. <span dir=\"rtl\">של השיפה</span>) basket work made of shavings; <span class=\"citation\">Ab. Zar. 75ᵃ</span> <span dir=\"rtl\">של שיפה</span> (ed. Pes. <a href=\"#\" data-headword=\"חַשָּׁבָא\">חש׳</a>). <span class=\"citation\">Succ. 20ᵃ</span> מחצלת של ח׳ Ms. M. (ed. <span dir=\"rtl\">שיפה</span>) matting made of etc.; <span class=\"citation\">Tosef. ib. I, 10</span> <a href=\"#\" data-headword=\"שיהופא\">שיהופא</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"חשופא\">חשופא</a>, oth. ed. <span dir=\"rtl\">חשי׳</span>).</div>","alt":[]},"10117":{"h":"חֲשִׁיקָה","r":"H01844","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָשַׁק\">חָשַׁק</a>) <i>pleasure, favor, use of the root</i> <a href=\"#\" data-headword=\"חָשַׁק\">חָשַׁק</a>. <span class=\"citation\">Gen. R. s. 80</span>, a. e.; v. <a href=\"#\" data-headword=\"חֲפִיצָה\">חֲפִיצָה</a>.</div>","alt":[]},"10118":{"h":"חָשַׂךְ","r":"H01845","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָסַךְ\">חָסַךְ</a></div>","alt":[]},"10119":{"h":"חֲשַׂךְ","r":"H01846","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָסַךְ\">חָסַךְ</a>) <i>to spare, withhold</i>. <span class=\"citation\">Targ. Prov. XIII, 24</span> <a href=\"#\" data-headword=\"חָשַׂךְ\">חָשֵׂךְ</a>, <a href=\"#\" data-headword=\"חָשֵיךְ\">חָשֵׂיךְ</a> (part.). <span class=\"citation\">Ib. XVII, 27</span>.</div><div class=\"sense\"><b>Af. אַחְשַׂךְ</b> <div class=\"sense\"><i>to deduct</i>. Y. Pes. IV, end, 31ᶜ <span dir=\"rtl\">מַחְשַׂכְנָא</span> (not <span dir=\"rtl\">מחשב׳</span>), v. <a href=\"#\" data-headword=\"גּוֹדְלָנָא\">גּוֹדְלָנָא</a>.</div></div>","alt":[]},"10120":{"h":"חָשַׁךְ","r":"H01847","html":"<div class=\"sense\"> [<i>to be pressed, thick</i>,] <i>to be dark</i>. <span class=\"citation\">Sabb. 34ᵃ</span>; <span class=\"citation\">51ᵃ</span> <span dir=\"rtl\">משחָשְׁכָה</span>; <span class=\"citation\">ib. IV, 2</span> <span dir=\"rtl\">משתֶּחְשַׁךְ</span> when it darkens (at nightfall, v. <a href=\"#\" data-headword=\"חֲשֵׁיכָה\">חֲשֵׁיכָה</a>). <span class=\"citation\">Snh. 22ᵃ</span> <span dir=\"rtl\">עולם ח׳ בעדו</span> the world around him is dark; <span class=\"citation\">Ab. Zar. 8ᵃ</span> (some ed. <a href=\"#\" data-headword=\"חָשׁוּךְ\">חָשׁוּךְ</a>). <span class=\"citation\">Ber. 16ᵇ</span> <span dir=\"rtl\">אל יֶחְשְׁכוּ וכ׳</span> let not our eyes be obscured; a. fr. V. <a href=\"#\" data-headword=\"חָשׁוּךְ\">חָשׁוּךְ</a>.</div><div class=\"sense\"><b>Hif. הֶחְשִׁיךְ</b> <div class=\"sense\"><b>1)</b> <i>to be overtaken by</i> (<i>the Sabbath</i>) <i>nightfall</i>. <span class=\"citation\">Sabb. XXIV, 1</span> <span dir=\"rtl\">מי שה׳ בדרך</span> he who is on the road at nightfall (on Friday).</div><div class=\"sense\"><b>—2)</b> <i>to wait for the nightfall, to make preparations to be ready for work on the exit of the Sabbath</i>, v. <a href=\"#\" data-headword=\"חֲשִׁיכָה\">חֲשִׁיכָה</a>. Ib. XXIII, 3 <span dir=\"rtl\">אין מַחְשִׁיכִין על וכ׳</span> you must not, during the day, walk to the extreme end of the Sabbath limit to await the night there for the purpose of hiring workmen etc.; <span dir=\"rtl\">אבל מַחְשִׁיךְ הוא וכ׳</span> but one may do so for the purpose of going at nightfall to watch his field, and then he may also take his fruits home. Ib. <span dir=\"rtl\">להַחְשִׁיךְ עליו</span> to await the night at the Sabbath limit for the purpose of doing it. Ib. 4; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to darken, obscure</i>. <span class=\"citation\">Cant. R. to I, 1</span> (ref. to <span dir=\"rtl\">חשכים</span>, <span class=\"citation\">Prov. XXII, 29</span>) that is Potifar <span dir=\"rtl\">שה׳ הקב&quot;ה וכ׳</span> whose eyes the Lord darkened etc. <span class=\"citation\">Ex. R. s. 51</span> (ref. to <span dir=\"rtl\">חשכה</span>, <span class=\"citation\">Gen. XV, 12</span>) that is Media <span dir=\"rtl\">שהֶחְשִׁיכָה וכ׳</span> who made Israel’s eyes dim (with tears) by her decrees. <span class=\"citation\">Pesik. R. s. 47</span> (ref. to <span class=\"citation\">Job XXXVIII, 2</span>) <span dir=\"rtl\">הֶחְשַׁכְתָּ וכ׳</span> (not <span dir=\"rtl\">החשב׳</span>) thou hast obscured the council which I held in heavens (when the Lord vouched for Job’s integrity); a. fr.</div><div class=\"sense\"><b>—4)</b> <i>to become dark</i>. <span class=\"citation\">Midr. Till. to Ps. XVIII, 12</span> (ref. to the versions <span dir=\"rtl\">חשכת</span>, Ps. l. c., and <span dir=\"rtl\">חשרת</span> <span class=\"citation\">II Sam. XXII, 12</span>) when the clouds are laden with the waters, <span dir=\"rtl\">הן מַחְשִׁיכִין מן המים וכ׳</span> they receive a dark color from the waters, and afterwards they drop them as through a sieve.</div></div>","alt":[]},"10121":{"h":"חֲשַׁךְ","r":"H01848","html":"<div class=\"sense\"><span class=\"citation\">Targ. Job. XVIII, 6</span>. <span class=\"citation\">Targ. Ex. X, 15</span>; a. fr.—<span class=\"citation\">Taan. 10ᵃ</span> <span dir=\"rtl\">חֲשׁוּךְ ענני וכ׳</span> when the clouds are dark, they contain much water.</div><div class=\"sense\"><b>Pa. חַשֵּׁיךְ</b> <div class=\"sense\"><b>1)</b> <i>to darken, obscure</i>. <span class=\"citation\">Targ. Ps. CV, 28</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to do something at night, to be late</i>. <span class=\"citation\">Tam. 27ᵇ</span> <span dir=\"rtl\">חַשֵּׁיךְ תקין נפשך וכ׳</span> at bed-time attend to thy body, and in the morning etc. <span class=\"citation\">Ber. 8ᵃ</span> <span dir=\"rtl\">מקדמי ומְחַשְּׁכֵי וכ׳</span> they go to Synagogue early and late. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">קדימו וחַשִּׁיכוּ ועיילו וכ׳</span> (Ms. M. <span dir=\"rtl\">ואַחְשִׁיכוּ</span>, <i>Af.</i>, v. Rabb. D. S. a. l.) go ye early and late to etc. <span class=\"citation\">Targ. Y. Deut. XXVIII, 65</span>, v. <a href=\"#\" data-headword=\"מַחַשְׁכָן\">מַחַשְׁכָן</a>.</div></div><div class=\"sense\"><b>Af. אַחְשִׁיךְ</b> <div class=\"sense\"><b>1)</b> <i>to obscure</i>. <span class=\"citation\">Targ. Job XXXVIII, 2</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to do something late</i>. <span class=\"citation\">Targ. I Sam. XVII, 16</span>.—Ber. l. c., v. supra.</div></div><div class=\"sense\"><b>Ithpe. אִיתְחֲשַׁךְ  אַיחֲשַׁךְ</b> <div class=\"sense\"><i>to grow dark</i>. <span class=\"citation\">Targ. Ps. LXIX, 24</span>; a. e.—<span class=\"citation\">Snh. 96ᵃ</span> <span dir=\"rtl\">עד דאתא איח׳</span> by the time he came it had grown dark.</div></div>","alt":["חֲשׁוֹךְ I"]},"10122":{"h":"חֲשַׁךְ ²","r":"H01849","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">חסך</span>) <i>to be reduced, lean</i>. <span class=\"citation\">Targ. Ps. XXXI, 11</span> (h. text <span dir=\"rtl\">עששו</span>, v. Rashi a. l.)</div><div class=\"sense\"><b>Ithpe. אִיתְחֲשַׁךְ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲשַׁךְ\">same</a>. <span class=\"citation\">Targ. Job XXXIII, 21</span> Ms. (ed. <span dir=\"rtl\">שפיין</span>).</div></div>","alt":["חֲשׁוֹךְ II"]},"10123":{"h":"חשֶׁךְ","r":"H01850","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>darkness</i>. <span class=\"citation\">Ex. R. s. 14</span>. <span class=\"citation\">Ḥag. 12ᵃ</span>; a. v. fr.—הָרֵי ח׳ <i>Dark Mountains</i>, behind which the Amazons live (<i>Amazonici Mountes</i>, v. Sm. Class. Dict. s. v.). <span class=\"citation\">Lev. R. s. 27</span>; Pesik. Shor, p. 74ᵃ; <span class=\"citation\">Tam. 32ᵃ</span>. [The Jewish legend relating the meeting of Alexander the Great with the Amazons seems to point to Africa, v. <a href=\"#\" data-headword=\"קַרְטְגינָא\">קרטגינא</a>).</div>","alt":["חוֹשֶׁךְ"]},"10124":{"h":"חֶשְׁכָּא","r":"H01851","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ps. XVIII, 29</span> (Ms. <span dir=\"rtl\">חבריא</span>, v. <a href=\"#\" data-headword=\"הֲבִירָא\">הַבִירָא</a>); <span class=\"citation\">Targ. II Sam. XXII, 29</span> (ed. Lag. <a href=\"#\" data-headword=\"חֲשׁוֹךְ\">חֲשׁוֹכָא</a>). <span class=\"citation\">Targ. Ps. LXXXVIII, 13</span> <a href=\"#\" data-headword=\"חֲשַׁךְ\">חֲשַׁךְ</a>, constr. (Ms. <a href=\"#\" data-headword=\"חֲשׁוֹךְ\">חֲשׁוֹךְ</a>).—V. <a href=\"#\" data-headword=\"חַשְׁכּוּתָא\">חַשְׁכּוּתָא</a>.</div>","alt":[]},"10125":{"h":"חֲשֵׁכָה","r":"H01852","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשֵׁיכָה\">חֲשֵׁיכָה</a></div>","alt":[]},"10126":{"h":"חַשְׁכּוּתָא","r":"H01853","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲשֵׁכָה\">preced.</a> wds.) <i>dimness, darkness</i>. <span class=\"citation\">Targ. O. Deut. XXVIII, 65</span> (ed. Vien. <span dir=\"rtl\">חַשְׁכַּת</span>).</div>","alt":[]},"10127":{"h":"חֲשֵׁכְתָּא","r":"H01854","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חַשְׁכּוּתָא\">same</a>. <span class=\"citation\">Targ. O. Deut. XXVIII, 65</span>, v. preced.—Pl. <a href=\"#\" data-headword=\"חֲשֵׁכְתָּא\">חֲשֵׁכָתָא</a>. <span class=\"citation\">B. Mets. 30ᵇ</span> <span dir=\"rtl\">בקדמתא ובח׳</span> every early morning or every evening after dark.</div>","alt":[]},"10128":{"h":"חֲשִׁכְתָּא","r":"H01855","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשִׁיךְ ²\"><span dir=\"rtl\">חֲשִׁיךְ</span> II</a></div>","alt":[]},"10129":{"h":"חֲשַׂל","r":"H01856","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"חֲסַל\">חֲסַל</a>.</div>","alt":[]},"10130":{"h":"חָשַׁל","r":"H01857","html":"<div class=\"sense\"><i>to scrape off, polish; to reduce</i>.</div><div class=\"sense\"><b>Pi. חִישֵּׁל</b> <div class=\"sense\"><i>to crush, batter</i>. <span class=\"citation\">Koh. R. to I, 6</span> the Lord <span dir=\"rtl\">מְחַשְּׁלוֹ בהרים</span> breaks it (the vehemence of the wind) through the mountains; (<span class=\"citation\">Lev. R. 15</span>; <span class=\"citation\">Gen. R. s. 24</span> <span dir=\"rtl\">מרשלו</span>; Y. Ber. IX, 13ᶜ bot. <span dir=\"rtl\">מכשלו</span>).</div></div><div class=\"sense\"><b>Nif. נֶחְשָׁל</b> <div class=\"sense\"><i>to be crushed</i>. <span class=\"citation\">Sifré Deut. 296</span> (ref. to <span dir=\"rtl\">נחשלים</span>, <span class=\"citation\">Deut. XXV, 18</span>) <span dir=\"rtl\">שנמכו … ונֶחְשְׁלוּ מתחת וכ׳</span> who have been crushed out of the ways of the Lord and battered away from under the protection of etc.</div></div>","alt":[]},"10131":{"h":"חֲשַׁל","r":"H01858","html":"<div class=\"sense\"><b>1)</b> <i>to furbish, forge, hammer.</i> <span class=\"citation\">Dan. II, 40</span>.—<span class=\"citation\">Ab. Zar. 16ᵃ</span> דחַשְׁלֵי מינייהו וכ׳ Ms. M., v. <a href=\"#\" data-headword=\"חֲלַשׁ\">חֲלַשׁ</a>.—Trnsf. <i>to plan, design</i> (corresp. to b. h. <a href=\"#\" data-headword=\"חָרַשׁ I\">חרש</a> a. <span dir=\"rtl\">חשב</span>). <span class=\"citation\">Targ. Ps. XXXVI, 5</span>. <span class=\"citation\">Targ. Prov. XIV, 22</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to peel, pound grits</i>, v. <a href=\"#\" data-headword=\"חוּשְׁלָא\">חוּשְׁלָא</a>.—V. <a href=\"#\" data-headword=\"חֲשִׁילָא\">חֲשִׁילָא</a>.</div><div class=\"sense\"><b>Pa. חַשֵּׁיל</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָשַׁל\">same</a>, esp. <i>to plan</i>. <span class=\"citation\">Targ. Ps. XXI, 12</span>, a. fr. Ms. (ed. <i>Pe</i>.). <span class=\"citation\">Targ. Y. Deut. I, 12</span>.</div></div>","alt":["חֲשִׁיל"]},"10132":{"h":"חַשְׁלָא","r":"H01859","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲשַׁל\">preced.</a>) <i>furbisher, smith</i>.—Pl. constr. <span dir=\"rtl\">חַשְׁלֵי</span>. <span class=\"citation\">Keth. 77ᵃ</span> (expl. <span dir=\"rtl\">מצרף נחשת</span>. Mish.) <span dir=\"rtl\">ח׳ דודי</span> kettle smiths.</div>","alt":[]},"10133":{"h":"חַשְׁמוֹנַאי","r":"H01860","html":"<div class=\"sense\"> n. gent. m. <i>Asmonean, Hasmonean</i>, family name of Mattathias the priest and his descendants (Maccabean dynasty). <span class=\"citation\">Midd. I, 6</span> <span dir=\"rtl\">בני ח׳</span> the sons of the Asmonean (Judah and his brothers). <span class=\"citation\">Sabb. 21ᵇ</span> <span dir=\"rtl\">מלכות בית ח׳</span> the government of the Asmonean house. <span class=\"citation\">Midr. Till. to Ps. XCIII</span>, beg. (ed. Bub. plur.). <span class=\"citation\">Sot. 49ᵇ</span>; <span class=\"citation\">Men. 64ᵇ</span>; <span class=\"citation\">B. Kam. 82ᵇ</span> (v. Rabb. D. S. a. l.) <span dir=\"rtl\">מלכי בית</span> the kings of the Asmonean house (Hyrcan and Aristobulus).—Pl. <span dir=\"rtl\">חַשְׁמוֹנָאִים</span>. B. Kam. l. c. (some ed.).—[<i>Chald</i>. <span class=\"citation\">Targ. I Sam. II, 4</span>. <span class=\"citation\">Targ. Cant. VI, 7</span> (some ed. <span dir=\"rtl\">נָאֵי …</span>, pl.).]</div>","alt":[]},"10134":{"h":"חַשְׁמַל","r":"H01861","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"חָסַם II\"><span dir=\"rtl\">חָסַם</span> II</a>; v. Ges. H. Dict.<sup>10</sup> s. v.) <i>a glittering substance; amber</i> or <i>galena</i> (?). <span class=\"citation\">Ḥag. 13ᵃ</span> <span dir=\"rtl\">עד הח׳</span> including the verse in which <i>ḥashmal</i> appears (<span class=\"citation\">Ez. I, 27</span>). Ib. <span dir=\"rtl\">היה מבין בח׳</span> was speculating on the meaning of <i>ḥashmal</i>; <span dir=\"rtl\">ויצאה אש מח׳</span> and fire came out of the <i>ḥashmal</i>. Ib., sq. <span dir=\"rtl\">מהו ח̇ש̇מ̇ל̇ ח̇יות אש̇ מְמַ֗לְּ֗לוֹת</span> <i>Ḥayoth</i> (v. <a href=\"#\" data-headword=\"חַיָּה I\">חַיָּה</a>) speaking fire; v. <a href=\"#\" data-headword=\"חָשָׁה\">חָשָׁה</a>.</div>","alt":[]},"10135":{"h":"חַשְׁמָל","r":"H01862","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ez. I, 4</span>; a. e.—<span class=\"citation\">Ḥag. 13ᵃ</span></div>","alt":["חַשׁמָלָא"]},"10136":{"h":"חשֶׁן","r":"H01863","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוֹשֶׁן\">חוֹשֶׁן</a></div>","alt":[]},"10137":{"h":"חָשַׁק","r":"H01864","html":"<div class=\"sense\"> (b. h.) <i>to press, tie, surround</i>. <span class=\"citation\">Ab. Zar. 35ᵃ</span> (ref. to <span class=\"citation\">Cant. I, 2</span>) <span dir=\"rtl\">חֲשׁוֹק שׂפתותיך זו בזו</span> press thy lips together and be not too hasty in replying.—2) (cmp. <a href=\"#\" data-headword=\"חָפַץ\">חָפַץ</a>) <i>to be attached to, in love with; to elect</i>. <span class=\"citation\">Tosef. Yeb. VIII, 4</span> <span dir=\"rtl\">חָשְׁקָה … בתורה</span> my soul has chosen the Law (as bride); <span class=\"citation\">Yeb. 63ᵇ</span>. <span class=\"citation\">Ḥull. 89ᵃ</span> (ref. to <span class=\"citation\">Deut. VII, 7</span>) <span dir=\"rtl\">חוֹשְׁקַנִי בכם</span> I elected you.</div>","alt":[]},"10138":{"h":"חֲשַׁק","r":"H01865","html":"<div class=\"sense\">, <i>to bandage, saddle, harness</i>. <span class=\"citation\">Targ. II Sam. XIX, 27</span>.—Part. pass. <span dir=\"rtl\">חָשֵׁיק</span>, pl. <span dir=\"rtl\">חֲשִׁיקִין</span>, f. <a href=\"#\" data-headword=\"חֲשִׁיקָה\">חֲשִׁיקַן</a>. <span class=\"citation\">Targ. Jud. XIX, 10</span>. <span class=\"citation\">Ib. V, 10</span>.</div>","alt":[]},"10139":{"h":"חָשַׁר","r":"H01866","html":"<div class=\"sense\"> [(cmp. <a href=\"#\" data-headword=\"חֲשַׁךְ\">חֲשַׁךְ</a> II a. <a href=\"#\" data-headword=\"חָשַׁל\">חָשַׁל</a>) <i>to peel</i>, whence <span dir=\"rtl\">חֲשָׁרָה</span> <i>an implement for removing peels, sieve</i>, from which <a href=\"#\" data-headword=\"חָשַׁר\">חָשַׁר</a>] <i>to sift, distil drops as if through a sieve</i>. <span class=\"citation\">Midr. Till. to Ps. XVIII, 12</span>, v. <a href=\"#\" data-headword=\"חָשַׁךְ\">חָשַׁךְ</a>. Ib. <span dir=\"rtl\">אדם נוטל כברה וחוֹשֵׁר … אצבעות וכ׳</span> a man takes a sieve and lets (a liquid) down a height of two or three fingers; before it comes down to the ground, the drops will be mixed up; <span class=\"citation\">Yalk. Sam. 160</span>.—<span class=\"citation\">Gen. R. s. 13</span> <span dir=\"rtl\">וחוֹשְׁרִים אותו כמין כברה</span> and they (the clouds) distil it (the rain) as if from a sieve; <span class=\"citation\">Yalk. Gen. 20</span>; <span class=\"citation\">Yalk. Koh. 967</span>.</div><div class=\"sense\"><b>Pi. חִישֵּׁר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲשַׁק\">same</a>. <span class=\"citation\">Taan. 9ᵇ</span> <span dir=\"rtl\">מנוקבות … ומְחַשְּׁרוֹת</span> they (the clouds) are perforated like a sieve and distil water to the ground.</div></div>","alt":[]},"10140":{"h":"חֲשַׁר","r":"H01867","html":"<div class=\"sense\">, <i>to sift</i>. Y. Sabb. VII, 10ᵇ bot. <span dir=\"rtl\">הן דח׳ וכ׳</span> he who (on the Sabbath) sifts powder of gypsum &amp;c. <span class=\"citation\">Y. Meg. I, 71ᵇ</span> top <span dir=\"rtl\">מכיון שהוא מרחיק ואת ח׳ וכ׳</span> because its meshes are wide and you may sift flour through it; <span class=\"citation\">Y. Ned. IV, beg. 38ᶜ</span>, v. <a href=\"#\" data-headword=\"זוֹסְמָא\">זוֹסְמָא</a>.</div>","alt":[]},"10141":{"h":"חָשַׁשׁ","r":"H01868","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חוּשׁ\">חוּשׁ</a>) </div><div class=\"sense\"><b>1)</b> <i>to feel heavy, feel pain</i>. Y. Sabb. IV, 8ᶜ top <span dir=\"rtl\">החוֹשֵׁשׁ אזנו</span> he who has ear-ache. <span class=\"citation\">Esth. R. to I, 1</span> (play on <span dir=\"rtl\">אח̇ש̇ור̇וש</span>) who ever thinks of him <span dir=\"rtl\">ח̇וֹשֵֹׁשׁ את ר̇אש̇ו</span> gets a head-ache; a. e.—(Mostly with <a href=\"#\" data-headword=\"ב\">ב</a>). <span class=\"citation\">Cant. R. to V, 2</span> <span dir=\"rtl\">אם חושש … בראשו</span> if one of the twins has a head-ache; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to apprehend, take into consideration</i>. <span class=\"citation\">Pes. I, 2</span> <span dir=\"rtl\">אין חוֹשְׁשִׁין שמא וכ׳</span> we do not take into consideration that perhaps a weasel &amp;c. <span class=\"citation\">Tosef. Ḥull. III, 24</span> <span dir=\"rtl\">ואין ח׳ שמא של וכ׳</span> and we need not hesitate to use them for fear that they may be eggs of &amp;c.; <span class=\"citation\">Ḥull. 63ᵇ</span> <span dir=\"rtl\">אין ח׳ לא משום וכ׳</span>. <span class=\"citation\">Sabb. XVI, 7</span>; <span class=\"citation\">XXII, 3</span> חוֹשְׁשַׁנִי לו מחטאת I am afraid he has committed a sin which requires a sin-offering to atone for; a. fr.</div>","alt":[]},"10142":{"h":"חֲשַׁשׁ","r":"H01869","html":"<div class=\"sense\"><b>1)</b> <i>to suffer</i>. <span class=\"citation\">Y. M. Kat. III, 82ᵈ</span> top <span dir=\"rtl\">פומיה הוא ח׳</span> he has an ailing on his mouth (and therefore ties it up). <span class=\"citation\">Cant. R. to II, 16</span> <span dir=\"rtl\">ועבד ח׳ וכ׳</span> and continued suffering with fever for three years; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be affected, troubled; to care, apprehend</i>. <span class=\"citation\">Targ. Prov. XXVIII, 17</span> <span dir=\"rtl\">דחָשֵׁישׁ וכ׳</span> he who is troubled (feels compunction) about blood-guiltiness (h. text <span dir=\"rtl\">עשק</span>); a. e.—<span class=\"citation\">Y. M. Kat. III, 81ᵈ</span> bot. <span dir=\"rtl\">צריך את חשש על נפשך</span> thou must mind the excommunication for thy soul’s sake. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חַשׁ על נפשיה</span> he minded the excommunication. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">וחַשּׁוּן אילין על אילין</span> they minded each the other’s excommunication. <span class=\"citation\">Keth. 26ᵇ</span> <span dir=\"rtl\">במֵיחַשׁ לזילותא וכ׳</span> they differ as to providing against the disregard of the court; a. fr. (interch. with <a href=\"#\" data-headword=\"חוּשׁ\">חוּשׁ</a>)—[</div><div class=\"sense\"><b>3)</b>  (= <a href=\"#\" data-headword=\"חֲשָׁא\">חֲשָׁא</a>) <i>to whisper, hiss</i>. <span class=\"citation\">Targ. Jer. VI, 29</span> <a href=\"#\" data-headword=\"חָשׁ\">חַשׁ</a> (ed. Wil. <a href=\"#\" data-headword=\"חֲשָׁא\">חֲשָׁא</a>).]</div><div class=\"sense\"><b>Ithpa. אִיתְחֲשַׁשׁ  אִיחֲ׳</b> <div class=\"sense\"><i>to become sick</i>. Cant. R. l. c. <span dir=\"rtl\">אתח׳ ר׳ חנינא</span> (Var. <a href=\"#\" data-headword=\"חֲרַק\">אִחֲ׳</a>; ed. Wil. <span dir=\"rtl\">אתשש</span>, corr. acc.).</div></div><div class=\"sense\"><b>Palp. חַשְׁחֵשׁ</b> <div class=\"sense\"><b>1)</b> <i>to feel</i>. <span class=\"citation\">Targ. Y. Num. XI, 12</span>.</div><div class=\"sense\"><b>—2)</b> <i>to care for.</i> <span class=\"citation\">Targ. Ps. CXLI, 1</span> Regia (ed. <a href=\"#\" data-headword=\"חִישׁ\">חִישׁ</a>).</div></div>","alt":[]},"10143":{"h":"חֲשָׁשָׁא","r":"H01870","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲשַׁשׁ\">preced.</a>) <i>anxiety, fear, suspicion</i>. <span class=\"citation\">Targ. Koh. II, 25</span>.—<span class=\"citation\">Yoma 83ᵇ</span> <span dir=\"rtl\">אימר דאמרי אנא ח׳ וכ׳</span> (Ms. M. <span dir=\"rtl\">למֵיחַשׁ</span>, v. <a href=\"#\" data-headword=\"חֲשַׁשׁ\">preced.</a>) what I said (that a name was an omen) was meant only as an apprehension, but I did not mean it as a certainty. <span class=\"citation\">Bekh. 36ᵃ</span> <span dir=\"rtl\">אימר דאמר ר&quot;מ לח׳</span> what R. M. said, was meant as an apprehension (worth investigating), but not to make one legally disqualified. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ח׳ הוא</span> it is merely a suspicion, <span dir=\"rtl\">ובמקום ח׳ וכ׳</span> and against such a doubt, we may argue that he had no reason to tell a falsehood. <span class=\"citation\">Nidd. 17ᵇ</span> <span dir=\"rtl\">אי בתר ח׳ וכ׳</span> if you are guided by a doubt, opp. <a href=\"#\" data-headword=\"חֲזָקָה\">חֲזָקָה</a>; a. fr.</div>","alt":[]},"10144":{"h":"חָתָא","r":"H01871","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חתי\">חתי</a></div>","alt":["חֲתָא","חָתָה"]},"10145":{"h":"חִתּוּי","r":"H01872","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָתַת\">חָתַת</a>) <i>breaking, killing</i>. <span class=\"citation\">Ḥull. 27ᵃ</span> <span dir=\"rtl\">זב ע&quot;י ח׳ בעינן</span> the flow must have been caused by the action which kills (cutting).</div>","alt":[]},"10146":{"h":"חִתּוּךְ","r":"H01873","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִיתּוּךְ\">חִיתּ׳</a></div>","alt":["חִתּוּכָא"]},"10147":{"h":"חָתוּל","r":"H01874","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. Fl. to Levy Targ. Dict. I, p. 426<sup>1</sup>) <i>cat</i>. <span class=\"citation\">B. Kam. 80ᵇ</span>. <span class=\"citation\">Hor. 13ᵃ</span>. <span class=\"citation\">Bekh. 8ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">חֲתוּלִים</span>, … <a href=\"#\" data-headword=\"לִין\">לִין</a>; f. <span dir=\"rtl\">חֲתוּלוֹת</span>. <span class=\"citation\">B. Kam. 80ᵃ</span>, sq.; <span class=\"citation\">Tosef. ib. VIII, 17</span>. Hor. l. c. <span dir=\"rtl\">מפני מה ח׳ … בעכברים</span> Ms. M. a. Ar. (v. Rabb. D. S. a. l. note; ed. <a href=\"#\" data-headword=\"הַכֹּל\">הכל</a>) why have the cats been given power over the mice?—<span class=\"citation\">Koh. R. to VI, 11</span>. <span class=\"citation\">Cant. R. to VII, 2</span> <span dir=\"rtl\">ומצא הח׳ מקורעות לפניהם</span> and found the cats lying torn in front of the chickens; <span class=\"citation\">Y. Peah III, 17ᵈ</span> top.</div>","alt":[]},"10148":{"h":"חָתוּל ²","r":"H01875","html":"<div class=\"sense\"> <span class=\"citation\">Ḥull. 52ᵇ</span>.—Pl. <span dir=\"rtl\">חֲתוּלַיָּא</span>, <span dir=\"rtl\">חֲתוּלִין</span>. <span class=\"citation\">Targ. Is. XIII, 22</span>; <span class=\"citation\">XXXIV, 14</span> (h. text <span dir=\"rtl\">איים</span>) wild cats. [<span class=\"citation\">Hos. IX, 6</span> <span dir=\"rtl\">חתולין</span>, read: <span dir=\"rtl\">חֲרוּלִין</span>.]</div>","alt":["חֲתוּלָא"]},"10149":{"h":"חִתּוּם","r":"H01876","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִיתּוּם\">חִיתּוּם</a></div>","alt":[]},"10150":{"h":"חָתוֹמָא","r":"H01877","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲתִים\">חֲתִם</a>) <i>signer, witness</i>.—Pl. <span dir=\"rtl\">חָתוֹמַיָּיא</span>. <span class=\"citation\">Y. Gitt. IX, 50ᶜ</span> bot. <span dir=\"rtl\">יהב רשו … ולח׳ וכ׳</span> (not <span dir=\"rtl\">ולחתימייא</span>) gave permission to the scribe to write and to the witnesses to sign.</div>","alt":[]},"10151":{"h":"חִתּוּן","r":"H01878","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִיתּוּךְ\">חִיתּ׳</a></div>","alt":["חִתּוּנָא"]},"10152":{"h":"חֲתוּנָּה","r":"H01879","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>wedding</i>. <span class=\"citation\">Num. R. s. 12</span>; a. e., v. <a href=\"#\" data-headword=\"חִיתּוּן\">חִיתּוּן</a>.</div>","alt":[]},"10153":{"h":"חתות","r":"H01880","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִיתִּית\">חִיתִּית</a></div>","alt":["חִתִּית"]},"10154":{"h":"חתי","r":"H01881","html":"<div class=\"sense\">, (v. <span dir=\"rtl\">נחת</span>); <i>Hif.</i> <span dir=\"rtl\">הֶחֱתִי</span>(<a href=\"#\" data-headword=\"א\">א</a>) <i>to put down, rest</i>. <span class=\"citation\">Y. Yoma V, 42ᵇ</span> bot. <span dir=\"rtl\">יחליף … ויַחֲתִי</span> let him change hands … and set (the pan) down. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אם ה׳ מימינו וכ׳</span> if he set it down from his right towards his left side.</div>","alt":["חָתָא"]},"10155":{"h":"חֲתֵי","r":"H01882","html":"<div class=\"sense\"><i>Af.</i> <span dir=\"rtl\">אַחֲתֵי</span> <a href=\"#\" data-headword=\"חתי\">same</a>. <span class=\"citation\">Yoma 47ᵃ</span> <span dir=\"rtl\">ונַחְתְיָהּ למחתה וכ׳</span> (v. Rabb. D. S. a. l. notes 3, 4) and let him put the pan on top of it. V. <a href=\"#\" data-headword=\"נְחַת\">נְחַת</a>.</div>","alt":["חֲתָא I"]},"10156":{"h":"חתי ²","r":"H01883","html":"<div class=\"sense\"> (b. h.) <i>to dig, </i>esp<i>.</i> <i> to take coals out with a pan.</i> <span class=\"citation\">Yoma IV, 4</span> <span dir=\"rtl\">בכל יום היה חוֹתֶה וכ׳</span> every other day the priest used to take coals out in a silver pan &amp;c. <span class=\"citation\">Sabb. VIII, 7</span> <span dir=\"rtl\">כדי לַחְתּוֹת בו את האור</span> large enough to take fire out in it. <span class=\"citation\">Zeb. 64ᵃ</span>; a. fr.—<span class=\"citation\">Y. Yoma IV, 41ᶜ</span> bot. <span dir=\"rtl\">צריך לחות</span> (read <span dir=\"rtl\">לחתות</span>) he must take coals out as before.</div><div class=\"sense\"><b>Pi. חִיתָּה</b> <div class=\"sense\"><i>to stir embers, rake</i>. <span class=\"citation\">Sabb. 34ᵇ</span> <span dir=\"rtl\">שמא יְחַתֶּה בגחלים</span> he might rake the coals under the ashes. [<span class=\"citation\">Ḥull. 27ᵃ</span>, v. <a href=\"#\" data-headword=\"חָתַת\">חָתַת</a>].</div></div>","alt":["חָתָה"]},"10157":{"h":"חֲתִי","r":"H01884","html":"<div class=\"sense\"><span class=\"citation\">Targ. Is. XXX, 14</span>.—Part. <span dir=\"rtl\">חָאתֵי</span>. <span class=\"citation\">Targ. Prov. XXV, 22</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"חֲתֵי\">חָתֵי</a>).—</div><div class=\"sense\"><b>Pa. חַתֵּי</b> <div class=\"sense\"><i>to stir</i>. <span class=\"citation\">Ab. Zar. 38ᵇ</span> <span dir=\"rtl\">וחַתֵּה בה חַתּוּיֵי</span> ed. (v. Rabb. D. S. a. l. note 8), v. <a href=\"#\" data-headword=\"חֲרֵי\">חֲרֵי</a>.</div></div>","alt":["חֲתָא II"]},"10158":{"h":"חֲתִיָיה","r":"H01885","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲתִי\">preced.</a> wds.) <i>taking coals out in a pan</i>. <span class=\"citation\">Y. Yoma IV, 41ᶜ</span> bot. Bab. <span class=\"citation\">ib. 48ᵇ</span> <span dir=\"rtl\">חישב בחֲתִיַית וכ׳</span> if he entertained an undue thought on taking coals from the altar.</div>","alt":[]},"10159":{"h":"חֲתִיכָה","r":"H01886","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָתַךְ\">חָתַךְ</a>) </div><div class=\"sense\"><b>1)</b> <i>cutting</i>. <span class=\"citation\">Erub. 103ᵃ</span>, v. <a href=\"#\" data-headword=\"יַבֶּלֶת\">יַבֶּלֶת</a>. <span class=\"citation\">Ḥull. 31ᵇ</span>, v. <a href=\"#\" data-headword=\"זְבִיחָה\">זְבִיחָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>a piece</i> (<i>of meat</i>), <i>portion</i> (cmp. <a href=\"#\" data-headword=\"נָתַח\">נֵתַח</a>, <a href=\"#\" data-headword=\"מני\">מָנָה</a>). Ib. VII, 5 <span dir=\"rtl\">ח׳ של דג וכ׳</span> a portion of an unclean fish. Ib. 100ᵃ <span dir=\"rtl\">שאני ח׳ הואיל וכ׳</span> with an entire piece the case is different, because it is fit to be offered to guests; a. fr.—Pl. <span dir=\"rtl\">חֲתִיכוֹת</span>. Ib. VII, 5. <span class=\"citation\">Kerith. 17ᵇ</span> <span dir=\"rtl\">חתיכה משתי ח׳</span> a doubt as to one piece out of two (of which one was forbidden and one allowed, and it is unknown which he ate); a. fr.</div>","alt":[]},"10160":{"h":"חֲתִים","r":"H01887","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲתַם\">חֲתַם</a></div>","alt":[]},"10161":{"h":"חֲתִימָה","r":"H01888","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָתַם\">חָתַם</a>) </div><div class=\"sense\"><b>1)</b> <i>signature, stamp, mark</i>. <span class=\"citation\">Gitt. 87ᵃ</span> bot. <span dir=\"rtl\">ודידעינן בהא ח׳ וכ׳</span> when we know about that signature that it is not Jacob’s. <span class=\"citation\">Ib. II, 4</span> <span dir=\"rtl\">עד … וחֲתִימָתוֹ בתלוש</span> unless it was written and signed on a movable material (v. <a href=\"#\" data-headword=\"חָבַר\">חָבַר</a>). <span class=\"citation\">Y. Keth. II, 26ᶜ</span> top <span dir=\"rtl\">על חֲתִימַת העד וכ׳</span> to identify the signature of the second witness. <span class=\"citation\">B. Bath. 89ᵇ</span> כיון דלא חזי ח׳ Ms. M. (ed. <span dir=\"rtl\">אי לא חזי ח׳</span>, Ms. H. <span dir=\"rtl\">עד דחזי חתמא</span>) since he does not see the official stamp on the measure; a. fr.—Trnsf. <span dir=\"rtl\">חֲתִימַת זָקָן</span> <i>the mature manly expression which the beard gives, full manhood</i>. <span class=\"citation\">B. Mets. 39ᵇ</span>; <span class=\"citation\">Yeb. 88ᵃ</span>; <span class=\"citation\">Gen. R. s. 91</span>; a. e.—[<span class=\"citation\">Targ. Cant. III, 8</span> <span dir=\"rtl\">חֲתִימַת מִילָה</span> the seal of the covenant.]—Pl. <span dir=\"rtl\">חֲתִימוֹת</span>. <span class=\"citation\">Keth. 21ᵇ</span> <span dir=\"rtl\">ח׳ ידי העדים</span> the signatures (handwritings) of the witnesses; a. e.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"חִיתּוּם\">חִיתּוּם</a>) <i>the concluding clause of a prayer</i>. <span class=\"citation\">Pes. 104ᵃ</span> <span dir=\"rtl\">צריך … ח׳ סמוך לחֲתִימָתוֹ</span> he must use expressions corresponding to the closing formula immediately before the latter.</div><div class=\"sense\"><b>—3)</b> <i>locking up, obstruction</i>. <span class=\"citation\">Nidd. 43ᵇ</span>, a. fr. (with ref. to <span class=\"citation\">Lev. XV, 3</span>) <span dir=\"rtl\">חֲתִימַת פי האמה</span> the filling up of the aperture of the membrum (with mucus).</div>","alt":[]},"10162":{"h":"חֲתִימוּתָא","r":"H01889","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"חֲתִימָה\">same</a>. <span class=\"citation\">Keth. 21ᵃ</span> <span dir=\"rtl\">אסהד אחֲתִימוּת ידיה וכ׳</span> he testified to (identified) his own signature &amp;c.—<span class=\"citation\">B. Bath. 167ᵃ</span> <span dir=\"rtl\">חַתְמוּת ידא</span> (Ms. M. <a href=\"#\" data-headword=\"חֲתִימָה\">חֲתִימַת</a>). <span class=\"citation\">Gitt. 66ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲתַם\">חֲתַם</a>.—Pl. <a href=\"#\" data-headword=\"חֲמִימָתָא\">חֲתִימָתָא</a>. <span class=\"citation\">Keth. 21ᵇ</span> <span dir=\"rtl\">חֲתִימַת ידייהו</span>.</div>","alt":["חַתְמוּתָא","חֲתִימְתָּא"]},"10163":{"h":"חתימייא","r":"H01890","html":"<div class=\"sense\">, <span class=\"citation\">Y. Gitt. IX, 50ᶜ</span> bot., v. <a href=\"#\" data-headword=\"חָתוֹמָא\">חָתוֹמָא</a></div>","alt":[]},"10164":{"h":"חֲתִימְתָּא","r":"H01891","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲתִימוּתָא\">חֲתִימוּתָא</a></div>","alt":[]},"10165":{"h":"חֲתִירָא","r":"H01892","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲתִירְתָּא\">חֲתִירְתָּא</a></div>","alt":[]},"10166":{"h":"חֲתִירָה","r":"H01893","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָתַר\">חָתַר</a>) <i>breach, opening made by digging</i>. <span class=\"citation\">Gen. R. s. 76</span> <span dir=\"rtl\">וחתר לו הקב&quot;ה ח׳ וכ׳</span> and the Lord created an opening for him etc. <span class=\"citation\">Ruth R. to II, 14</span>; <span class=\"citation\">Y. Snh., X, 28ᶜ</span> bot., v. <a href=\"#\" data-headword=\"חָתַר\">חָתַר</a>. Ruth R. l. c. <span dir=\"rtl\">צווחין לח׳ עתירה</span>, v. <a href=\"#\" data-headword=\"חֲתִירְתָּא\">next w.</a></div>","alt":[]},"10167":{"h":"חֲתִירְתָּא","r":"H01894","html":"<div class=\"sense\"><span class=\"citation\">Lev. R. s. 30</span>; <span class=\"citation\">Gen. R. s. 63</span> (ref. to <span class=\"citation\">II Chr. XXXIII, 13</span>; <span class=\"citation\">Gen. XXV, 21</span>) <span dir=\"rtl\">בערביא קירין לח׳ עתירתא</span> in Arabia they say for <i>ḥăthirta</i> (breach) <i>ʿăthirta;</i> <span class=\"citation\">Y. Snh. X, 28ᶜ</span> bot. <span dir=\"rtl\">לחֲתַרְתָּה עתרתה …</span>; <span class=\"citation\">Ruth R. to II, 14</span>, v. preced.—Pl. <a href=\"#\" data-headword=\"חֲתִירָא\">חֲתִירָן</a>. <span class=\"citation\">Y. Maas. Sh. V, 55ᵈ</span> bot. <span dir=\"rtl\">אתעביד … ח׳ בתים</span> (strike out <span dir=\"rtl\">בתים</span>) three hundred robberies by breaking in were committed; <span class=\"citation\">Gen. R. s. 27</span> <a href=\"#\" data-headword=\"חוּתְרָא\">חוּתְרִין</a> m. pl.; <span class=\"citation\">Yalk. Job 909</span> (corr. acc.).</div>","alt":["(חֲתִירָא)"]},"10168":{"h":"חִתִּית","r":"H01895","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִיתִּית\">חִיתִּית</a></div>","alt":[]},"10169":{"h":"חָתַךְ","r":"H01896","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to cut, dissect; to sever</i>. <span class=\"citation\">Ḥull. 33ᵃ</span> <span dir=\"rtl\">חוֹתֵךְ כזית וכ׳</span> cuts out flesh of the size of an olive. <span class=\"citation\">Ib. 32ᵃ</span> <span dir=\"rtl\">ח׳ דלעת וכ׳</span> if in slaughtering he cut a pumpkin at the same time. <span class=\"citation\">Ib. 48ᵇ</span> a. e. <span dir=\"rtl\">חוֹתְכָהּ מכאן וכ׳</span> he amputates on one place and the animal survives &amp;c. <span class=\"citation\">Bets. 32ᵇ</span> <span dir=\"rtl\">חוֹתְכָהּ באיר</span> he may sever the wick over the light. <span class=\"citation\">Y. Meg. IV, 75ᵃ</span> <span dir=\"rtl\">חותך</span> the reader cuts one verse into two (reading <span class=\"citation\">Gen. I, 5</span>, a. <span class=\"citation\">I, 8</span> as two verses severally); a. fr.—[<span class=\"citation\">Lev. R. s. 10</span> <span dir=\"rtl\">לחתוך את אביו וכ׳</span>, v. <a href=\"#\" data-headword=\"חָתַר\">חָתַר</a>.]—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חִתּוּךְ\">חָתוּךְ</a> <i>cut into, having the incisions of limbs &amp;c., outlined</i>. <span class=\"citation\">Nidd. 24ᵇ</span> <span dir=\"rtl\">גוף שאינו ח׳</span> a shapeless body (not articulated); <span dir=\"rtl\">ראש שאינו ח׳</span> a shapeless head (without indications of the nose &amp;c.) Ib. 24ᵃ <span dir=\"rtl\">יד חֲתוּכָה</span> a well-shaped hand (of an embryo); a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"פָּסַק\">פָּסַק</a>, <a href=\"#\" data-headword=\"גָּזַר\">גָּזַר</a>) <i>to decide, sentence</i>. <span class=\"citation\">Lev. R. s. 4</span>, beg. (ref. to <span dir=\"rtl\">התוך</span>, <span class=\"citation\">Jer. XXXIX, 3</span>) <span dir=\"rtl\">ששם חוֹתְכִין את ההלכה</span> for there they decide the practice. Ib. <span dir=\"rtl\">וחוֹתֶכֶת דיניהם וכ׳</span> and decides the cases &amp;c. <span class=\"citation\">Shebu. 30ᵇ</span> bot. <span dir=\"rtl\">אֶחְתְּכֶנּוּ</span> I will decide the case (in accordance with the testimony).—Part. pass. as ab. <span class=\"citation\">Y. Snh. IV, beg. 22ᵃ</span> <span dir=\"rtl\">אילו … התורה חתוכה</span></div><div class=\"sense\"><b>Nif. נֶחְתַּךְ</b> <div class=\"sense\"><b>1)</b> <i>to be cut off, severed; to be cut into</i>. <span class=\"citation\">Ḥull. IV, 6</span> <span dir=\"rtl\">שנֶחְתְּכוּ רגליה</span> whose feet have been amputated. <span class=\"citation\">Ib. 32ᵃ</span> <span dir=\"rtl\">נֶחְתְּכָה דלעת וכ׳</span> if by accident a pumpkin has been cut simultaneously with the animal (opp. to <a href=\"#\" data-headword=\"חָתַךְ\">חָתַךְ</a>, v. supra); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be decided, decreed</i>. <span class=\"citation\">Meg. 15ᵃ</span> (play on <span dir=\"rtl\">ה̇ת̇ך̇</span>, <span class=\"citation\">Esth. IV, 5</span>) <span dir=\"rtl\">שכל … נֶחְ֗תָּ֗כִ֗ין על יפיו</span> all the government affairs were decided upon his opinion.</div></div><div class=\"sense\"><b>Pi. חִיתֵּךְ</b> <div class=\"sense\"><b>1)</b> <i>to cut</i>. <span class=\"citation\">Ḥull. IV, 2</span> <span dir=\"rtl\">מְחַתֵּךְ אבר אבר</span> he may cut off limb after limb. <span class=\"citation\">Ib. 98ᵇ</span> <span dir=\"rtl\">מחתך לה וכ׳</span> he carves the foreleg and then boils it.—<i>Part. pass</i>. <span dir=\"rtl\">מְחוּתָּךְ</span> <i>piecemeal, limbwise</i>. Y. Nidd. III, 50ᶜ <span dir=\"rtl\">יצא מח׳</span> if the embryo came out by pieces.</div><div class=\"sense\"><b>—2)</b> <i>to decide</i>. <span class=\"citation\">Snh. 7ᵇ</span> <span dir=\"rtl\">צדק … חַתְּכֵהוּ</span> make the case clear and then decide it. <span class=\"citation\">Ber. 61ᵃ</span> <span dir=\"rtl\">לשון מְחַתֵּךְ וכ׳</span> the tongue forms the sentence, the mouth closes (the case, makes it irreversible).</div><div class=\"sense\"><b>—3)</b> <i>to dig ore</i> (<i>in lumps</i>). <span class=\"citation\">Keth. 77ᵃ</span> (expl. <span dir=\"rtl\">מצרף</span>) <span dir=\"rtl\">המְחַתֵּךְ … מעיקרו</span> he who digs copper in the shaft. [<span class=\"citation\">Tosef. Ohol. IV, 3</span> <span dir=\"rtl\">וחיתכו</span>, <span dir=\"rtl\">וחתכו</span>, read: <span dir=\"rtl\">והִתִּיכוֹ</span> or <span dir=\"rtl\">והִיתְּכוֹ</span>, v. <a href=\"#\" data-headword=\"נָתַךְ\">נָתַךְ</a> a. <a href=\"#\" data-headword=\"התך\">התך</a>.]</div></div>","alt":[]},"10170":{"h":"חֲתַךְ","r":"H01897","html":"<div class=\"sense\"><i>Pa.</i> חַתֵּיךְ <i>to cut off</i>. <span class=\"citation\">Ḥull. 11ᵃ</span> <span dir=\"rtl\">ח׳ ליה לגמרי</span> he severed it entirely, v. <a href=\"#\" data-headword=\"לוּף\">לוּף</a>.—<i>Part. pass</i>. <span dir=\"rtl\">מְחַתַּךְ</span> <i>in pieces</i>. <span class=\"citation\">Targ. Y. Lev. VII, 30</span> (ed. Amst. <span dir=\"rtl\">מַחְתַּךְ</span>, incorr.). <span class=\"citation\">Targ. Y. I Num. XII, 12</span> <span dir=\"rtl\">כד מח׳</span> (not <span dir=\"rtl\">מְחַתֵּיךְ</span>).</div><div class=\"sense\"><b>Ithpa. אִתְחַתַּךְ</b> <div class=\"sense\"><i>to be cut, to be decided</i>. <span class=\"citation\">Targ. Esth. IV, 5</span> (v. <span class=\"citation\">Meg. 15ᵃ</span>, quot. in <a href=\"#\" data-headword=\"חָתַךְ\">preced.</a>).</div></div>","alt":[]},"10171":{"h":"חֲתָךְ","r":"H01898","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲתַךְ\">preced.</a>) <i>cut, wound</i>. <span class=\"citation\">Tosef. Mikv. VII</span> (<span class=\"citation\">VIII), 3</span> <span dir=\"rtl\">מפני הח׳</span> on account of the place where the handle is intended to be lopped off (v. <span class=\"citation\">Mikv. X, 5</span>).—<span class=\"citation\">Erub. 18ᵃ</span>. <span class=\"citation\">Ḥull. 32ᵇ</span> <span dir=\"rtl\">שחט במקום ח׳</span> he slaughtered by setting the knife into the wound (and continued the cut).</div>","alt":[]},"10172":{"h":"חָתַם","r":"H01899","html":"<div class=\"sense\"><b>1)</b> , <i>to tie up, close, lock</i>. Tanḥ. <span class=\"citation\">B’resh. 1</span> <span dir=\"rtl\">ח׳את הים וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>to seal</i>. <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> bot. <span dir=\"rtl\">טבעת שׂחוֹתֵם בה</span> the ring with which he seals. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אסור לַחְתּוֹם בה</span> you dare not use it for a seal; <span class=\"citation\">Tosef. ib. V</span> (<span class=\"citation\">VI), 2</span>; a. fr.—2) <i>to sign, subscribe</i> (as witness, judge &amp;c.) <span class=\"citation\">Gitt. VI, 7</span> <span dir=\"rtl\">אחד … חוֹתְמִין</span> one writes the document and two sign it as witnesses. <span class=\"citation\">Ib. 66ᵇ</span> <span dir=\"rtl\">ח׳ סופר</span> if the scribe signed as one of the witnesses. <span class=\"citation\">Ib. 67ᵃ</span> <span dir=\"rtl\">ואתם חֲתוֹמוּ</span> and sign you. <span class=\"citation\">Shebi. X, 4</span> <span dir=\"rtl\">הדיינים חותמין וכ׳</span> the judges sign under it; a. fr.—Part. pass. <a href=\"#\" data-headword=\"חִתּוּם\">חָתוּם</a>, f. <span dir=\"rtl\">חֲתוּמָה</span>; pl. <span dir=\"rtl\">חֲתוּמִים</span>, <span dir=\"rtl\">חֲתוּמִין</span>; <span dir=\"rtl\">חֲתוּמוֹת</span>. <span class=\"citation\">Yeb. 25ᵇ</span>, a. e. <span dir=\"rtl\">עדים הח׳ וכ׳</span> if witnesses are signed &amp;c.; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to close</i> a benediction (v. <a href=\"#\" data-headword=\"חֲתִימָה\">חֲתִימָה</a>). <span class=\"citation\">Pes. X, 6</span> <span dir=\"rtl\">וחותם בגאולה</span> and he closes with redemption (Blessed be the Lord who redeemed Israel). Ib. <span dir=\"rtl\">לא היה חותם</span> he did not close with a benediction. <span class=\"citation\">Ber. I, 4</span> <span dir=\"rtl\">מקום שאמרו לַחְתּוֹם</span> where the Rabbis ordained to close a benediction with Barukh &amp;c.; a. fr.—Part. pass. as ab. <span class=\"citation\">Gitt. 60ᵃ</span> <span dir=\"rtl\">תורה ח׳ ניתנה</span> the Law was given as one complete book, opp. <span dir=\"rtl\">מגילה מגילה</span> in single sheets. [<span class=\"citation\">Cant. R. to I, 11</span>, v. next w.]</div><div class=\"sense\"><b>Pi. חִיתֵּם</b> <div class=\"sense\"><i>to provide with signatures</i>. Y. Gitt. I, beg. 43ᵃ, a. e. <span dir=\"rtl\">מְחַתְּמוֹ בעדים וכ׳</span> he may have provided it with the signatures of unfit witnesses. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חִתְּמוֹ וכ׳</span>.—<i>Part. pass</i>. <span dir=\"rtl\">מְחוּתָּם</span>. Y. Keth. II, 26ᶜ; Y. Shebu. IV, 35ᶜ <span dir=\"rtl\">מח׳ בארבע וכ׳</span> provided with four signatures.</div></div><div class=\"sense\"><b>Nif. נֶחְתַּם</b> </div><div class=\"sense\"><b>Hithpa. הִתְחַתֵּם</b> <div class=\"sense\">, <i>Nithpa.</i> <a href=\"#\" data-headword=\"חָתַן\">נִתְחַתֵּם</a> </div><div class=\"sense\"><b>1)</b> <i>to be signed, sealed.</i> <span class=\"citation\">Gitt. I, 1</span> <span dir=\"rtl\">בפני נח׳</span> (Y. ed. <a href=\"#\" data-headword=\"חטי\">נתח׳</a>) in my presence has it been signed; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be finally sentenced</i> (by attaching the seal or signature). <span class=\"citation\">R. Hash. 16ᵇ</span> <span dir=\"rtl\">נכתבין ונֶחְתָּמִין וכ׳</span> their verdict is written and sealed at once; Y. ib. I, 57ᵃ <span dir=\"rtl\">מִתְחַתְּמִין</span>. <span class=\"citation\">Gen. R. s. 31</span>, beg. <span dir=\"rtl\">נתח׳ גזר דינם</span> their decree was sealed; a. e.</div></div>","alt":[]},"10173":{"h":"חֲתַם","r":"H01900","html":"<div class=\"sense\"><b>1)</b> <i>to close up</i>. <span class=\"citation\">Ber. 6ᵃ</span> <span dir=\"rtl\">ולִיחְתּוֹם פומיה</span> and let him close up its opening. Part. pass. <a href=\"#\" data-headword=\"חֲתִים\">חֲתִים</a>. <span class=\"citation\">Targ. O. Lev. XV, 3</span>.</div><div class=\"sense\"><b>—2)</b> <i>to seal, sign</i>. <span class=\"citation\">Targ. Jer. XXXII, 44</span>; a. fr.—<span class=\"citation\">Gitt. 66ᵇ</span> <span dir=\"rtl\">מִחְתַּם וכ׳</span> to draw their signatures.—<i>Part. pass</i>. as ab. Targ. l. c. 11.—<span class=\"citation\">B. Bath. 89ᵇ</span> <span dir=\"rtl\">דלא חֲתִימֵי</span> where they do not stamp measures officially.</div><div class=\"sense\"><b>—3)</b> <i>to close a benediction</i>. <span class=\"citation\">Meg. 22ᵇ</span> <span dir=\"rtl\">ח׳ ולא בריך</span> he closed his prayer without saying <i>Barukh</i> &amp;c. <span class=\"citation\">Cant. R. to I, 11</span> [read:] <span dir=\"rtl\">מלה חֲתִימָה … מסיימה</span> a closed and finished word (complete in itself).</div><div class=\"sense\"><b>Pa. חַתֵּים</b> <div class=\"sense\"><i>to lock up</i>. <span class=\"citation\">Targ. Job XXIV, 16</span> (some ed. <i>Ithpa.</i>).</div></div><div class=\"sense\"><b>Ithpa. אִתְחַתֵּים</b> <div class=\"sense\"><b>1)</b> <i>to lock one’s self up</i>. V. supra.</div><div class=\"sense\"><b>—2)</b> <i>to be sealed, stamped</i>. <span class=\"citation\">Targ. Esth. IV, 1</span>. <span class=\"citation\">Targ. Is. VIII, 21</span>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to be closed up</i>. <span class=\"citation\">Targ. Y. Lev. XV, 3</span> ed. pr. (ed. <span dir=\"rtl\">אתסתם</span>).</div></div>","alt":[]},"10174":{"h":"חַתְמָא","r":"H01901","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲתִימָה\">חֲתִימָה</a> a. <a href=\"#\" data-headword=\"חֲתִימוּתָא\"><a href=\"#\" data-headword=\"חֲתִימוּתָא\">חֲתִימוּתָא</a>.</a></div>","alt":["חַתְמוּתָא"]},"10175":{"h":"חָתַן","r":"H01902","html":"<div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"חַתְמָא\">preced.</a>) <i>to tie, connect, to covenant</i> (Assyr. <i>ḫatânu, to protect</i>. Friedr. Del. Proleg. p. 91).</div><div class=\"sense\"><b>Hithpa. הִתְחַתֵּן</b> </div><div class=\"sense\"><b>Nithpa. נִתְחַתֵּן</b> <div class=\"sense\"><i>to become connected, to enter into the family, to intermarry</i>. <span class=\"citation\">Snh. 82ᵃ</span> <span dir=\"rtl\">כאלו מִתְחַתֵּן בע&quot;א</span> as if he connected himself with idols. <span class=\"citation\">Gen. R. s. 82</span>, beg. <span dir=\"rtl\">שנ׳ ביהודית וכ׳</span> who married Judith &amp;c. <span class=\"citation\">Sifré Deut. 52</span>, a. e. <span dir=\"rtl\">שנ׳ … עם וכ׳</span> when Solomon married the daughter of Pharaoh; a. fr.</div></div>","alt":[]},"10176":{"h":"חֲתַן","r":"H01903","html":"<div class=\"sense\"><span class=\"citation\">Y. Sot. IX, end, 24ᶜ</span> [read:] <span dir=\"rtl\">הוון בעון מִחְתַּנְתֵּיה לנסיותא</span>, they desired to ally him to the Nasi family; <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> bot <span dir=\"rtl\">הוון אילין … בעון מהיתנתיה</span> (read: <span dir=\"rtl\">מִיחְתַּ׳</span>) members of the Nasi family desired to take him into the family.</div><div class=\"sense\"><b>Ithpa. אִתְחַתֵּן</b> <div class=\"sense\"><i>to become connected</i>. <span class=\"citation\">Targ. I Sam. XVIII, 22</span>, sq.; a. fr.—Y. Sabb. XII, 13ᶜ bot. <span dir=\"rtl\">אִיתְחַתְּנוּן וכ׳</span>, v. <a href=\"#\" data-headword=\"נְשִׂיאוּתָא\">נְשִׂיאוּתָא</a>.</div></div>","alt":[]},"10177":{"h":"חָתָן","r":"H01904","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חֲתַן\">preced.</a>) <i>connection, son-in-law; bridegroom;</i> (metaph., with ref. to the covenant of circumcision, v. <a href=\"#\" data-headword=\"בְּרִית\">בְּרִית</a>) <i>the infant fit for circumcision</i>. <span class=\"citation\">B. Bath. 98ᵇ</span> <span dir=\"rtl\">ח׳ הדר וכ׳</span> a son-in-law who lives in the house of his father-in-law. <span class=\"citation\">Pes. 113ᵃ</span> <span dir=\"rtl\">הוי זהיר … מחָתְנָהּ הראשון</span> guard thy wife against her former affianced. <span class=\"citation\">Y. Ned. III, end, 38ᵇ</span> (ref. to <span class=\"citation\">Ex. IV, 24</span> sq) <span dir=\"rtl\">משה קרוי ח׳</span> Moses is called the <i>ḥathan</i> … (and she said) <span dir=\"rtl\">חָ׳ דמים מתבקשין ממך</span> (ed. <span dir=\"rtl\">מתבקש</span>) husband, blood (circumcision) is asked of thee; <span dir=\"rtl\">תינוק קרוי ח׳</span> the infant is called the <i>ḥathan</i>, (and she said) <span dir=\"rtl\">חָ׳ בדמים אתה עומד לי</span> child of the covenant, a high price I pay for thee; Bab. <span class=\"citation\">Ned. 32ᵃ</span>; <span class=\"citation\">Ex. R. s. 5</span> <span dir=\"rtl\">חָתְנִי תהיה את וכ׳</span> thou shalt be my affianced by covenant, thou art given to me &amp;c. <span class=\"citation\">Nidd. V, 3</span> an infant one day old … is <span dir=\"rtl\">לאביו … כח׳ שלם</span> (as regards mourning ceremonies) like a perfect circumcised child to his parents &amp;c.—<span class=\"citation\">Ber. II, 5</span> <span dir=\"rtl\">ח׳ פטור וכ׳</span> a bride-groom in the first night is exempt &amp;c. <span class=\"citation\">Keth. 8ᵃ</span> (in wedding benedictions) <span dir=\"rtl\">משמח ח׳ עם הכלה</span> who causest the bridegroom to rejoice with the bride; a. fr.—Trnsf. (cmp. <a href=\"#\" data-headword=\"בַּעֲלָא\">בַּעֲלָא</a>) <i>the fructifying rain</i>. <span class=\"citation\">Ber. 59ᵇ</span>; <span class=\"citation\">Taan. 6ᵇ</span> <span dir=\"rtl\">משיצא ח׳ לקראת כלה</span> when the bridegroom goes forth to meet the bride, i.e. when the falling rain-drops meet the water on the ground and bubble; [oth. opin.; when the rivulets formed by the rain meet each other in gutters.].—Pl. <span dir=\"rtl\">חֲתָנִים</span>. Keth. l. c. Ib.ᵇ, v. <a href=\"#\" data-headword=\"בְּרָכָה\">בְּרָכָה</a>; a. fr.—</div>","alt":[]},"10178":{"h":"חַתְנָא","r":"H01905","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. IV, 25</span>, sq. (<span class=\"citation\">Targ. Y. II ib. 26</span> <a href=\"#\" data-headword=\"חתנת\">חתנת</a>, corr. acc.).—<span class=\"citation\">Targ. I Sam. XVIII, 18</span>.—<span class=\"citation\">Targ. Is. LXII, 5</span>; a. fr.—<span class=\"citation\">Yeb. 52ᵃ</span> <span dir=\"rtl\">ח׳ דדאיר</span> a son-in-law who resides &amp;c., v. <a href=\"#\" data-headword=\"דּוּר\">דּוּר</a>. <span class=\"citation\">Ḥull. 83ᵃ</span> <a href=\"#\" data-headword=\"חוֹזָאֵי\">בי ח׳</a> in the bridegroom’s family; a. fr.—Pl. <span dir=\"rtl\">חַתְנִין</span>. <span class=\"citation\">Targ. Jer. VII, 34</span>; a. e.—<span class=\"citation\">Sabb. 23ᵇ</span> חַתְנֵי Ms. O. sons-in-law, v. <a href=\"#\" data-headword=\"חַתְנוּתָא\">חַתְנוּתָא</a>.</div>","alt":["חֲתָנָא"]},"10179":{"h":"חֲתָנוּת","r":"H01906","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חַתְנָא\">preced.</a> wds.) <i>marital relation, intermarriage, wedlock</i> (connubium). <span class=\"citation\">Ab. Zar. 31ᵇ</span>, a. e. <span dir=\"rtl\">משום ח׳</span> as a guard against intermarriage (between Jews and gentiles). <span class=\"citation\">Ib. 36ᵇ</span>, v. <a href=\"#\" data-headword=\"אִישׁוּת\">אִישׁוּת</a>. <span class=\"citation\">Yeb. 76ᵃ</span> <span dir=\"rtl\">לית להו ח׳</span> they have no connubium (a marriage with them is not legally recognized); a. e.—בית ח׳ <i>additional rooms for the young couple</i> in the bridegroom’s paternal house. <span class=\"citation\">B. Bath. VI, 4</span> (<span class=\"citation\">98ᵇ</span>). <span class=\"citation\">Taan. 14ᵇ</span></div>","alt":[]},"10180":{"h":"חַתְנוּתָא","r":"H01907","html":"<div class=\"sense\"> Targ. G. I <span class=\"citation\">Deut. XXXII, 50</span>.—Pl. <span dir=\"rtl\">חַתְנְוָותָא</span> <i>connections through marriage, sons-in-law</i> &amp;c. <span class=\"citation\">Sabb. 23ᵇ</span> <span dir=\"rtl\">הוו ליה ח׳ רבנן</span> (Ms. O. <span dir=\"rtl\">חַתְנֵי</span>) will have scholars in the family through intermarriage.</div>","alt":[]},"10181":{"h":"חתנת","r":"H01908","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲתַן\">חֲתַן</a></div>","alt":[]},"10182":{"h":"חֲתַף","r":"H01909","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"חֲטַף\">חֲטַף</a>. <span class=\"citation\">Targ. Job. IX, 12</span> ed. Lag. (ed. <span dir=\"rtl\">חטף</span>).</div>","alt":[]},"10183":{"h":"חָתַר","r":"H01910","html":"<div class=\"sense\"><i>to dig, break in, make an opening</i>. <span class=\"citation\">Kidd. 24ᵇ</span> חֲתוֹר לי שיני Ar. (ed. <span dir=\"rtl\">לַחְתּוֹר לו שינו</span>) scrape my tooth (to clean it). <span class=\"citation\">Deut. R. s. 2</span> (ref. to <span dir=\"rtl\">וַיֵּעָתֶר</span>, <span class=\"citation\">II Chr. XXXIII, 13</span>) <span dir=\"rtl\">וַיֶּחְתַּר לו וכ׳</span> the Lord made an opening for his prayer; <span dir=\"rtl\">ח׳ את הרקיע</span> He broke through the heavens; <span class=\"citation\">Y. Snh. X, 28ᶜ</span> bot.; <span class=\"citation\">Ruth R. to II, 14</span> <span dir=\"rtl\">ח׳ לו חתירה וכ׳</span> (v. <span class=\"citation\">Snh. 103ᵃ</span>).—<span class=\"citation\">Ex. R. s. 37</span> <span dir=\"rtl\">נטל את הצפורן לַחְתּוֹר וכ׳</span> (Ar. s. v. <a href=\"#\" data-headword=\"צִפּוֹרֶן\">צפורן</a>: <span dir=\"rtl\">לחפור</span>) he took the digging tool to undermine his father’s house; <span class=\"citation\">Lev. R. s. 10</span> (<span dir=\"rtl\">לחתך</span>, <span dir=\"rtl\">אחתוך</span>, <span dir=\"rtl\">לחתוך את אביו</span>) (corr. acc.). <span class=\"citation\">Gen. R. s. 63</span> (ref. to <span dir=\"rtl\">וַיֶּעְתַּר</span>, <span class=\"citation\">Gen. XXV, 21</span>, v. supra) like a prince <span dir=\"rtl\">שהיה חוֹתֵר על אביו ליטול וכ׳</span> who undertook a siege (for military practice) against his father for a <i>litra</i> of gold (for the winner) <span dir=\"rtl\">והיה זה ח׳ מבפנים וכ׳</span> and so the one did mine from within &amp;c. (the father assisting his son’s efforts).—<span class=\"citation\">Snh. 109ᵃ</span> <span dir=\"rtl\">וחוֹתְרִים שם</span> and broke in there; <span class=\"citation\">Gen. R. s. 27</span>; a. fr.—Part. pass. <span dir=\"rtl\">חָתוּר</span>, f. <a href=\"#\" data-headword=\"חַבּוּרָה\">חֲתוּרָה</a>, pl. <span dir=\"rtl\">חֲתוּרִים</span>, <span dir=\"rtl\">חֲתוּרוֹת</span>. <span class=\"citation\">B. Kam. 114ᵇ</span> <span dir=\"rtl\">היתה מחתרת ח׳ וכ׳</span> his house was broken into. <span class=\"citation\">Ib. 23ᵃ</span> <span dir=\"rtl\">סתם דלתות ח׳ הן וכ׳</span> with reference to dogs, ordinary doors are subject to being broken in, i.e. the owner of a dog is responsible for damages done by breaking in.</div>","alt":[]},"10184":{"h":"חֲתַר","r":"H01911","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ez. VIII, 8</span>; a. e.</div><div class=\"sense\"><b>Ithpa. אִתְחַתַּר</b> </div><div class=\"sense\"><b>Ithpe. אִתְחֲתַר  אִיחֲ׳</b> <div class=\"sense\"><b>1)</b> <i>to be broken into</i>. <span class=\"citation\">M. Kat. 25ᵇ</span> אִיתְחַתְּרוּ שבעין מחתרתא וכ׳ Ms. M. (ed. <span dir=\"rtl\">אִיחְתְּרוּ</span>) seventy robberies were committed in Tiberias (ed. in N’hardea). <span class=\"citation\">Snh. 109ᵃ</span> <span dir=\"rtl\">אִחְתְּרִין … מחתרתא וכ׳</span> (Ms. O. <span dir=\"rtl\">אִיחְתְּרוּ וכ׳</span>) that night three hundred robberies were committed in S.</div><div class=\"sense\"><b>—2)</b> <i>to break in for one’s self</i>. <span class=\"citation\">Targ. Ez. XII, 7</span>.</div></div>","alt":[]},"10185":{"h":"חֲתַרְתָּא","r":"H01912","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲתִירְתָּא\">חֲתִירְתָּא</a></div>","alt":["חֲתַרְתָּה"]},"10186":{"h":"חָתַת","r":"H01913","html":"<div class=\"sense\"> (b. h.) <i>to break, shatter</i>. <span class=\"citation\">Ḥull. 27ᵃ</span> (play on <span dir=\"rtl\">וז̇ב̇ח̇ת̇</span> <span class=\"citation\">Deut. XII, 21</span>) <span dir=\"rtl\">ממקום שז̇ב̇ חָ֗תֵּ֗הוּ</span> from where the blood flows, break it (the animal’s life); <span dir=\"rtl\">ממאי דהאי חתהו לישנא דמתבר הוא</span> what proof have you, that this <i>ḥ</i><i>ottehu</i> has the meaning of breaking? (Answ. ref. to <a href=\"#\" data-headword=\"תַּחַת\">תחת</a>, <span class=\"citation\">Deut. I, 2</span>. [Ib. <a href=\"#\" data-headword=\"חִתּוּי\">חִתּוּי</a> formed fr. <a href=\"#\" data-headword=\"חָתָא\">חָתָה</a> <i>Pi.</i>, sec. r. of <a href=\"#\" data-headword=\"חָתַת\">חתת</a>.]</div>","alt":[]},"10187":{"h":"ט","r":"I00000","html":"<div class=\"sense\"><i>Teth</i>, the ninth letter of the Alphabet. It interchanges dialectically with <a href=\"#\" data-headword=\"צ\">צ</a>, as <a href=\"#\" data-headword=\"טַבְיָא\">טביא</a> a. <a href=\"#\" data-headword=\"צבי\">צבי</a>, with <a href=\"#\" data-headword=\"ת\">ת</a>, as <span dir=\"rtl\">חטף</span> a. <a href=\"#\" data-headword=\"חֲתַף\">חתף</a>; with <a href=\"#\" data-headword=\"ד\">ד</a>, as <span dir=\"rtl\">דפף</span> a. <a href=\"#\" data-headword=\"טָפַף I\">טפף</a>.</div>","alt":[]},"10188":{"h":"ט׳","r":"I00001","html":"<div class=\"sense\">, as a numeral, <i>nine</i>, v. <a href=\"#\" data-headword=\"א׳\">א׳</a>.—<span class=\"citation\">Maas. Sh. IV, 11</span>, v. <a href=\"#\" data-headword=\"טי\">טי&quot;ת</a>.</div>","alt":[]},"10189":{"h":"טא","r":"I00002","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַאטֵא\">טַאטֵא</a></div>","alt":[]},"10190":{"h":"טְאֵב","r":"I00003","html":"<div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"טוֹב\">טוֹב</a>) <i>to be bright, good, well</i>.—<span dir=\"rtl\">ט׳ על</span>, <span dir=\"rtl\">ט׳ ל־</span> <i>to feel well, be happy.</i> <span class=\"citation\">Dan. IV, 24</span>.—<span class=\"citation\">Targ. I Sam. XVI, 23</span> (ed. Wil. <a href=\"#\" data-headword=\"טַב I\">טָב</a>).</div>","alt":["טְאֵיב"]},"10191":{"h":"טָאבָא","r":"I00004","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְאֵב\">preced.</a>) <i>good</i> (<i>thing</i>).—Pl. <span dir=\"rtl\">טָאבֵי</span>. <span class=\"citation\">Targ. Prov. XIV, 22</span> (ed. Wil. <a href=\"#\" data-headword=\"טָבִי I\">טָבֵי</a>).</div>","alt":[]},"10192":{"h":"טאוי","r":"I00005","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. B. Kam. X, 2</span>, v. <a href=\"#\" data-headword=\"טֳוִי\">טְוָי</a></div>","alt":[]},"10193":{"h":"טַאטֵא","r":"I00006","html":"<div class=\"sense\"> (Palp. of <a href=\"#\" data-headword=\"טא\">טא</a>, cmp. <span dir=\"rtl\">טהר</span>) [<i>to brighten</i>,] <i>to sweep</i>. <span class=\"citation\">R. Hash. 26ᵇ</span>; <span class=\"citation\">Meg. 18ᵃ</span> <span dir=\"rtl\">שקולי טאטיתא וטַאטִי ביתא</span> (Ms. M. 2 <span dir=\"rtl\">טאטיך וכ׳</span>) take the (thy) broom and sweep the house (from which the Rabbis learned the meaning of <span class=\"citation\">Is. XIV, 23</span>).</div>","alt":[]},"10194":{"h":"טָאטָא","r":"I00007","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טַאטֵא\">preced.</a>) <i>broom</i>. <span class=\"citation\">R. Hash. 26ᵇ</span>; <span class=\"citation\">Meg. 18ᵃ</span>, v. <a href=\"#\" data-headword=\"טַאטֵא\">preced.</a></div>","alt":["טָאטִיתָא"]},"10195":{"h":"טְאֵיב","r":"I00008","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְאֵב\">טְאֵב</a></div>","alt":["טָאִיב"]},"10196":{"h":"טָאֵיס","r":"I00009","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוּס\">טוּס</a> ch.</div>","alt":[]},"10197":{"h":"טָאֵיף","r":"I00010","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוּף\">טוּף</a> ch.</div>","alt":[]},"10198":{"h":"טאירין","r":"I00011","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"טְיָארִין\">טְיָארִין</a>, v. <a href=\"#\" data-headword=\"טַיִּיר\">טְיָיר</a></div>","alt":[]},"10199":{"h":"*טאל","r":"I00012","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. VII, 9ᵃ</span> top <span dir=\"rtl\">מטאלין מילייא</span>, read: <span dir=\"rtl\">מן אילין מ׳</span>; cmp. Bab. <span class=\"citation\">Sabb. 70ᵃ</span></div>","alt":[]},"10200":{"h":"טַאֲנֵיס","r":"I00013","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Tanis</i> (<i>Zoan</i>) in Lower Egypt. <span class=\"citation\">Targ. Num. XIII, 22</span>. <span class=\"citation\">Targ. Y. Gen. XLI, 50</span> (h. text <span dir=\"rtl\">און</span>). <span class=\"citation\">Targ. Y. Ex. I, 11</span> (h. text <span dir=\"rtl\">פתם</span>); a. e.</div>","alt":["טָאנֵיס","טָנֵיס"]},"10201":{"h":"טָאֵס","r":"I00014","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוּס\">טוּס</a> ch.</div>","alt":[]},"10202":{"h":"טָאֵף","r":"I00015","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוּף\">טוּף</a> ch.</div>","alt":[]},"10203":{"h":"*טַארְגָא","r":"I00016","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. I</span> (ed. Bub. <span dir=\"rtl\">איסקוטא</span>), a gloss to <span dir=\"rtl\">תריס</span>, (Ital. <i>targa</i>) <i>buckler</i>, v. <span class=\"citation\">Yalk. Ps. 833</span>.</div>","alt":[]},"10204":{"h":"*טאריקי","r":"I00017","html":"<div class=\"sense\">, <span class=\"citation\">Ex. R. s. 11</span> <span dir=\"rtl\">בט׳</span>, read: <a href=\"#\" data-headword=\"קָטָאדִיקִי\">קַטָּאדִיקִי</a>.</div>","alt":[]},"10205":{"h":"טַב I","r":"I00018","html":"<div class=\"sense\"> (contr. of <a href=\"#\" data-headword=\"טְאֵב\">טאב</a>) = h. <a href=\"#\" data-headword=\"טוֹב\">טוֹב</a>, <i>to be good, well</i>.—טב ל־ <i>to feel well, be satisfied, fare well</i>. <span class=\"citation\">Targ. Deut. XV, 16</span>; a. e.</div><div class=\"sense\"><b>Af. אָטֵיב</b> <div class=\"sense\"><i>to do good</i>. <span class=\"citation\">Targ. Zech. XII, 4</span> <span dir=\"rtl\">לַאֲטָבָא</span> (ed. Lag. <span dir=\"rtl\">לאיט׳</span>). V. <a href=\"#\" data-headword=\"טוּב\">טוּב</a>, a. <a href=\"#\" data-headword=\"יְטַב\">יְטַב</a>.</div></div>","alt":[]},"10206":{"h":"טַב II","r":"I00019","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טַב I\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>good, precious</i>. <span class=\"citation\">Targ. Gen. II, 9</span>.—Targ. II, <span class=\"citation\">Esth. I, 19</span> <span dir=\"rtl\">דטבא</span> ed. Lag. (oth. ed. <span dir=\"rtl\">דטָבַת</span>)—<span class=\"citation\">Targ. Jud. V, 26</span> (missing in ed. Lag.); a. v. fr.—<span class=\"citation\">Gen. R. s. 22</span>; <span class=\"citation\">Lev. R. s. 22</span>, v. <a href=\"#\" data-headword=\"בִּישׁ I\">בִּישׁ</a>. <span class=\"citation\">Ber. 60ᵇ</span> <span dir=\"rtl\">כל מאי דעביד … לטב</span> (v. Rabb. D. S. a. l. note) whatever God does is for a good purpose. <span class=\"citation\">Tam. 32ᵃ</span> <span dir=\"rtl\">דידי טבא וכ׳</span> my advice is better than yours.—<span class=\"citation\">Lev. R. s. 33</span>, beg. <span dir=\"rtl\">מינה ט׳ וכ׳</span> from it (the tongue) comes what is good &amp;c.; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>worth, valued</i>. <span class=\"citation\">Y. Keth. IV, end, 29ᵇ</span> <span dir=\"rtl\">חד בית בטב וכ׳</span> (ed. Krot. <span dir=\"rtl\">בדב</span>, read: <span dir=\"rtl\">חד ביתא טב</span>) a house worth &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מכיון דלית ביתא טב וכ׳</span> as the house is not worth more than &amp;c.—<span class=\"citation\">Y. Peah I, 15ᵈ</span> bot. <span dir=\"rtl\">מילא דט׳ דכוותה</span> something of equal value; <span class=\"citation\">Gen. R. s. 35</span>, end (corr. acc.); a. fr.</div><div class=\"sense\"><b>—3)</b> <i>best man, elder, officer</i>. <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> top <span dir=\"rtl\">טב קרתא</span> an officer of the town.—Pl. <span dir=\"rtl\">טָבִין</span>, <span dir=\"rtl\">טָבַיָּיא</span>, <a href=\"#\" data-headword=\"טָבִי I\">טָבֵי</a>; fem. <span dir=\"rtl\">טָבָתָא</span>, <span dir=\"rtl\">טָבָאתָא</span>, <span dir=\"rtl\">טָבָן</span>. <span class=\"citation\">Targ. Mic. VII, 1</span>. <span class=\"citation\">Targ. Ps. CXXV, 4</span>; a. fr.—<span class=\"citation\">B. Mets. 44ᵇ</span> <span dir=\"rtl\">שלים לה ט׳ וכ׳</span> pay her in good and full-weight coin. <span class=\"citation\">Y. Snh. X, 28ᵇ</span> bot. <span dir=\"rtl\">כל טָבָן וכ׳</span>, v. <a href=\"#\" data-headword=\"נֶחֶמְתָּא\">נֶחֶמְתָּא</a>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד מאת׳ 1) <span dir=\"rtl\">טבאתא</span> the good fruits; a. fr.</div><div class=\"sense\"><b>—4)</b>  (adv.) <i>much, more</i>. <span class=\"citation\">Targ. Prov. XVII, 10</span>.—<span class=\"citation\">Gitt. 14ᵇ</span> טב טב רמו ליה Ar. (ed. only one <a href=\"#\" data-headword=\"טַב I\">טב</a>) strike him more (or, <i>it is right</i>, v. Rashi a. l.)—Y. Shek. IV, 48ᵃ top, v. <a href=\"#\" data-headword=\"טָבָאוּת\">טָבָאוּת</a>.</div>","alt":["טָבָא","טַבְתָא"]},"10207":{"h":"טַב III","r":"I00020","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>En Tab</i>, a place where the New Moon was proclaimed in the days of Rabbi (v. Neub. Géogr. p. 272). <span class=\"citation\">R. Hash. 25ᵃ</span>; Y. ib. II, 58ᵃ bot.; Y. Taan. II, 66ᵃ bot. <span dir=\"rtl\">עייני טב</span>; <span class=\"citation\">Pesik. R. s. 41</span> <a href=\"#\" data-headword=\"עֵינְטַב\">עֵינְטַב</a>.</div>","alt":["עֵין טַב"]},"10208":{"h":"טָבָא","r":"I00021","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַב II\"><span dir=\"rtl\">טַב</span> II</a></div>","alt":[]},"10209":{"h":"טִבָּא","r":"I00022","html":"<div class=\"sense\"><i>rumor</i>, v. <a href=\"#\" data-headword=\"טִיב II\"><span dir=\"rtl\">טִיב</span> II</a>.</div>","alt":["(טָבָא)"]},"10210":{"h":"טְבָא","r":"I00023","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְבַע\">טְבַע</a></div>","alt":[]},"10211":{"h":"*טַבְאָג","r":"I00024","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>tabag</i>, name of a jewel in the Highpriest’s breastplate. <span class=\"citation\">Targ. Cant. V, 14</span> (Fl., to Levy Targ. Dict. I, 426<sup>2</sup>, suggests <span dir=\"rtl\">טבאז</span> = <i>topaz</i>).</div>","alt":[]},"10212":{"h":"טָבָאוּת","r":"I00025","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טַב I\">טַב</a> a. <a href=\"#\" data-headword=\"טַבְוָא\"><a href=\"#\" data-headword=\"טַבְוָא\">טַבְוָא</a>)</a> (<i>in a</i>) <i>good manner, well, properly</i>(h. . <span class=\"citation\">Targ. Y. Deut. IX, 21</span>; a. e.—Y. Ber. V, 9ᶜ top <span dir=\"rtl\">לא עבדין ט׳</span> do not do right. <span class=\"citation\">Cant. R. to I, 1</span> מאן דקרי ט׳ וכ׳ I will go to whosoever explains the Bible well etc.—<span class=\"citation\">Y. Shebu. VII, 38ᵃ</span> bot. <span dir=\"rtl\">אין אתא הא ט׳</span> if he appears, it is well. <span class=\"citation\">Y. Shek. IV, 48ᵃ</span> top <span dir=\"rtl\">וטבות כן</span> Bab. ed. (Y. ed. <span dir=\"rtl\">וטבא</span>) and so it is right. Y. Maas. Sh. I, 52ᵈ top <span dir=\"rtl\">וטבבו כן</span> (corr. acc.)—Hebr. form: <span dir=\"rtl\">טָּבִית</span>. <span class=\"citation\">Meïl. 17ᵃ</span> <span dir=\"rtl\">ט׳ אמר</span> he spoke well (he is right).</div>","alt":["טַבָּאוּת","(טַבְוָואוּת)","טָבוּת"]},"10213":{"h":"טַבַּאי","r":"I00026","html":"<div class=\"sense\">, pr. n. m. <i>Tabbai.</i> <span class=\"citation\">Ab. I, 8</span>; a. fr.</div>","alt":[]},"10214":{"h":"טָבְאַל","r":"I00027","html":"<div class=\"sense\"> (<span class=\"citation\">Is. VII, 6</span>) pr. n. place (!) <i>Tobal</i>. <span class=\"citation\">Y. Ab. Zar. I, beg. 39ᵃ</span> <span dir=\"rtl\">חיזרנו … מקום ששמו ט׳</span> we searched the whole Bible and could not find a place by the name of Tobal.</div>","alt":[]},"10215":{"h":"טבב","r":"I00028","html":"<div class=\"sense\">, <span class=\"citation\">Y. Maas. Sh. I, 52ᵈ</span> top <span dir=\"rtl\">וטבבו</span>, read: <span dir=\"rtl\">וטָבוּת</span>.</div>","alt":[]},"10216":{"h":"טַבְהַק","r":"I00029","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">טַבְהֲקֵי</span> (Pers. tâbah, tâvah, tapak, Lag. Ges. Abh. p. 49) (<i>pieces of</i>) <i>roasted meat</i>. <span class=\"citation\">Erub. 29ᵇ</span> bot. (Ar. sing.; ed. Ven. <span dir=\"rtl\">ט׳ ט׳</span></div>","alt":[]},"10217":{"h":"טַבְוָא","r":"I00030","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> constr. <a href=\"#\" data-headword=\"טָבָאוּת\">טַבְוַת</a>, <a href=\"#\" data-headword=\"טַבְוָא\">טַבְוַות</a> (<a href=\"#\" data-headword=\"טָבִי I\">טבי</a>, sec. r. of <a href=\"#\" data-headword=\"טַב I\">טב</a>) <i>beneficence, good deed</i>. <span class=\"citation\">Targ. Mic. VII, 20</span> (perh. pl.).—Pl. <span dir=\"rtl\">טַבְוָן</span>, <a href=\"#\" data-headword=\"טַבְוָא\">טַבְוָון</a>, <span dir=\"rtl\">טַבְוָותָא</span>. Ib. (ed. Lag. <span dir=\"rtl\">טָבָן</span>). <span class=\"citation\">Targ. Gen. XXXII, 11</span>; a. e.</div>","alt":["טַבְוָוא"]},"10218":{"h":"טַבְוָאוּת","r":"I00031","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טָבָאוּת\">טַבָּאוּת</a></div>","alt":["טַבְוָו׳"]},"10219":{"h":"טָבוֹחַ","r":"I00032","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (infin. of <a href=\"#\" data-headword=\"טָבַח\">טָבַח</a>) </div><div class=\"sense\"><b>1)</b> <i>slaughtering and preparing the pilgrim’s offering</i>. <span class=\"citation\">Ḥag. II, 4</span> (<span class=\"citation\">17ᵃ</span>) <span dir=\"rtl\">יום ט׳ וכ׳</span> the slaughtering day is observed after the Sabbath. Y. ib. 78ᵃ bot. <span dir=\"rtl\">יומה הוא טְבוֹחָהּ</span> its day (the festive day itself) is its slaughtering day.</div><div class=\"sense\"><b>—2)</b> <i>Taboaḥ</i>, name of a windstorm (demon). <span class=\"citation\">Sabb. 129ᵇ</span></div>","alt":[]},"10220":{"h":"טִבּוּל","r":"I00033","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְבַרְיָא\">טִיבּ׳</a></div>","alt":["טִבּוּלָא"]},"10221":{"h":"טבוסה","r":"I00034","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. VI, 7ᵈ</span> (P’né Mosh. <span dir=\"rtl\">סכוסה</span>), read <a href=\"#\" data-headword=\"סְבָכָה\">סְבָכָה</a> or <a href=\"#\" data-headword=\"שְׂבָכָה\">שְׂבָכָה</a>, v. <a href=\"#\" data-headword=\"כָּבוּל I\">כָּבוּל</a>; cmp. Bab. <span class=\"citation\">Sabb. 57ᵇ</span></div>","alt":[]},"10222":{"h":"טִבּוּעִין","r":"I00035","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טִיבּוּעִין\">טִיבּוּעִין</a></div>","alt":[]},"10223":{"h":"טַבּוּר","r":"I00036","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טִיבּוּר\">טִיבּוּר</a></div>","alt":["טִבּוּר"]},"10224":{"h":"טָבוּת I","r":"I00037","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טָבָאוּת\">טַבָּאוּת</a></div>","alt":[]},"10225":{"h":"טָבוּת II","r":"I00038","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Tabuth</i>. <span class=\"citation\">Snh. 97ᵃ</span>, v. <a href=\"#\" data-headword=\"טַבְיוֹמִי\">טַבְיוֹמִי</a>; <span class=\"citation\">B. Mets. 49ᵃ</span> (Ms. Alf. <a href=\"#\" data-headword=\"טָבָאוּת\">טָאבוּת</a>, v. Rabb. D. S. a. l. note 6).</div>","alt":[]},"10226":{"h":"טֵבוּתָא","r":"I00039","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טִיבוּ\">טִיבוּ</a></div>","alt":[]},"10227":{"h":"טַבְזָא","r":"I00040","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַפְזָא\">טַפְזָא</a></div>","alt":[]},"10228":{"h":"טָבַח","r":"I00041","html":"<div class=\"sense\">, (b. h.) <i>to prepare a feast</i>, esp. <i>to slaughter and dress meat, to cook</i>. <span class=\"citation\">Keth. 4ᵃ</span> <span dir=\"rtl\">טִבְחוֹ טָבוּחַ</span> his meat for the feast is ready (for cooking).—<span class=\"citation\">Bets. 25ᵃ</span> (expl. <span dir=\"rtl\">בית טביחה</span>) <span dir=\"rtl\">מקום שטוֹבַחַת וכ׳</span> the place where the animal cooks (digests) its food.</div>","alt":[]},"10229":{"h":"טְבַח","r":"I00042","html":"<div class=\"sense\"><span class=\"citation\">Ber. 56ᵃ</span> <span dir=\"rtl\">טַבְחַת ולא אכלת</span> thou shalt prepare and not eat. <span class=\"citation\">Sabb. 129ᵇ</span> <span dir=\"rtl\">הוה ט׳ להו וכ׳</span> it (the wind or demon <a href=\"#\" data-headword=\"טָבוֹחַ\">טָבוֹחַ</a>) would have feasted on them (the Israelites), on their flesh and their blood; a. e.—V. <a href=\"#\" data-headword=\"מַטְבָּחַיָּיא\">מַטְבְּחַיָּיא</a></div><div class=\"sense\"><b>Pa. טַבַּח</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"טָבַח\">same</a>. <span class=\"citation\">Gen. R. s. 57</span>, end <span dir=\"rtl\">טבח טַבְּחוֹן</span> Tabaḥ (<span class=\"citation\">Gen. XXII, 24</span>) means, ‘Slaughter them’ v. <a href=\"#\" data-headword=\"*גַּחֲמוּן\">גַּחֲמוֹן</a></div></div>","alt":[]},"10230":{"h":"טֶבַח","r":"I00043","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"טְבַח\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>the meat for a feast</i>. <span class=\"citation\">Keth. 4ᵃ</span>, v. <a href=\"#\" data-headword=\"טָבַח\">טָבַח</a>.</div><div class=\"sense\"><b>—2)</b> <i>feast</i>, trnsf. <i>onslaught</i>. <span class=\"citation\">Gen. R. s. 83</span> (ref. to <span class=\"citation\">Is. XXXIV, 6</span>) <span dir=\"rtl\">אעפ&quot;כ ט׳ גדול וכ׳</span> nevertheless the main onslaught will be in the land of Edom (Rome); <span class=\"citation\">Pesik. R. s. 14</span>, end; s. 15; <span class=\"citation\">Yalk. Num. 759</span>.</div>","alt":[]},"10231":{"h":"טַבָּח","r":"I00044","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טֶבַח\">preced.</a>) <i>meat-dresser, butcher, cook</i>. <span class=\"citation\">Bets. 28ᵃ</span> <span dir=\"rtl\">ט׳ אומן</span> a professional butcher; a. fr.—Pl. <span dir=\"rtl\">טַבָּחִים</span>. <span class=\"citation\">Kidd. IV, 14</span>; a. e.</div>","alt":[]},"10232":{"h":"טַבָּחָא","r":"I00045","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Lev. I, 5</span>.—<span class=\"citation\">Targ. I Sam. IX, 23</span>, sq.—<span class=\"citation\">Ḥull. 18ᵃ</span>; a. e.—Pl. fem. <a href=\"#\" data-headword=\"טַבָּחָא\">טַבָּחָן</a>. <span class=\"citation\">Targ. I Sam. VIII, 13</span>.</div>","alt":[]},"10233":{"h":"טבָחָא","r":"I00046","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"טֶבַח\">טֶבַח</a>. <span class=\"citation\">Targ. Prov. VII, 22</span>.—<span class=\"citation\">Gen. R. s. 65</span> <span dir=\"rtl\">לקבל תורא ט׳</span> according to the size of the ox is the feast (as you call Esau (Rome) great, so will his punishment be great, ref. to <span class=\"citation\">Is. XXXIV, 6</span>); Pesik. Haḥod. p. 56ᵇ; <span class=\"citation\">Pesik. R. s. 15</span> (read <a href=\"#\" data-headword=\"לְפוּם\">לפום</a> for <span dir=\"rtl\">נפיל</span>); <span class=\"citation\">Cant. R. to II, 15</span> <span dir=\"rtl\">טבחיא</span> (corr. acc.).</div>","alt":["טִבְחָא"]},"10234":{"h":"*טַבְּחוֹן","r":"I00047","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְבַח\">טְבַח</a></div>","alt":[]},"10235":{"h":"טָבִי I","r":"I00048","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"טַבְיָא\">טַבְיָא</a>) <i>Tabi</i>. </div><div class=\"sense\"><b>1)</b>  a slave. <span class=\"citation\">Ber. II, 7</span>; a fr.—2) name of several Amoraim. <span class=\"citation\">R. Hash. 22ᵃ</span>. <span class=\"citation\">Meg. 6ᵇ</span>; a. e.—3) <i>T. Rishba</i> (<i>the hunter</i>, Rashi). <span class=\"citation\">Sabb. 17ᵇ</span> top.</div>","alt":[]},"10236":{"h":"טָבִי II","r":"I00049","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>K’far Tabi</i>, near Lydda. <span class=\"citation\">Bets. 5ᵃ</span>; <span class=\"citation\">R. Hash. 31ᵇ</span>. <span class=\"citation\">Tosef. Ohol. IV, 2</span> <span dir=\"rtl\">כ׳ טַבְיָא</span> (Var. <a href=\"#\" data-headword=\"טָמֵא I\">טמא</a>).</div>","alt":["כְּפַר ט׳"]},"10237":{"h":"טַבְיָא","r":"I00050","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"צְבִי\">צְבִי</a>) <i>deer, gazelle</i>. <span class=\"citation\">Targ. Deut. XII, 15</span>; a. fr.—<span class=\"citation\">Snh. 95ᵃ</span>. <span class=\"citation\">Ḥull. 59ᵇ</span>, v. <a href=\"#\" data-headword=\"קֶרֶשׁ II\"><span dir=\"rtl\">קֶרֶשׁ</span> II</a>; a. e.—<span class=\"citation\">Ib. 59ᵃ</span> <span dir=\"rtl\">בר ט׳</span> a young deer.—Pl. <a href=\"#\" data-headword=\"טַבְיָא\">טָבַיָּא</a>, <span dir=\"rtl\">טַבְיֵי</span>. <span class=\"citation\">Targ. II Sam. II, 18</span>; a. e.—<span class=\"citation\">Keth. 103ᵇ</span> <span dir=\"rtl\">וצידנא טביא</span> (Rashi: <span dir=\"rtl\">וצדיינא טביי</span>) and I caught deer.—Fem. pl. <span dir=\"rtl\">טָבְיָן</span>, <span dir=\"rtl\">טַבְיַן</span>. <span class=\"citation\">Targ. I Kings V, 3</span>. <span class=\"citation\">Targ. Y. Deut. XIV, 5</span>.—Y. Snh. VII, end, 25ᵈ.—[Y. Ter. IX, end, 48ᵇ <span dir=\"rtl\">מה טבייה</span>, v. <a href=\"#\" data-headword=\"טִיב\">טִיב</a> I ch.]</div>","alt":[]},"10238":{"h":"טַבְיוֹמִי","r":"I00051","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Tabyomi</i>. <span class=\"citation\">Snh. 97ᵃ</span> <span dir=\"rtl\">רב טבות … וא&quot;ל רב ט׳</span> his name was R. Tabuth, some say, R. Tabyomi. <span class=\"citation\">Kidd. 14ᵇ</span>. <span class=\"citation\">Men. 70ᵃ</span> <span dir=\"rtl\">ט׳ בר קיסנא</span> (Ms. M. <a href=\"#\" data-headword=\"טוֹבִי\">טובי</a>, v. Rabb. D. S. a. l. note).—<span class=\"citation\">Gen. R. s. 4</span>. Ex. R. s. 93, end.</div>","alt":[]},"10239":{"h":"טְבִיחָה","r":"I00052","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טָבַח\">טָבַח</a>) </div><div class=\"sense\"><b>1)</b> <i>slaughtering;</i></div><div class=\"sense\"><b>2)</b> <i>digestion</i>. <span class=\"citation\">Bets. III, 3</span> <span dir=\"rtl\">בית טְבִיחָתָחּ</span> the place where it is cut (neck); <span class=\"citation\">ib. 25ᵃ</span> <span dir=\"rtl\">מאי לאו מבית ט׳ ממש וכ׳</span> does this not mean actually from the place etc.? No, <span dir=\"rtl\">ממקום שטובחת וכ׳</span> v. <a href=\"#\" data-headword=\"טָבַח\">טָבַח</a>.</div>","alt":[]},"10240":{"h":"טְבִילָה","r":"I00053","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (טָבַל I) </div><div class=\"sense\"><b>1)</b> <i>dipping</i>. Mekh. Bo, Pisḥa, s. 11 (ref. to <span class=\"citation\">Ex. XII, 22</span>) <span dir=\"rtl\">על בל הגעה ט׳</span> you must dip the hyssop into the blood for each time you strike. Sifra Vayikra, Ḥobah, ch. III, Par. 3.—<span class=\"citation\">Zeb. 93ᵇ</span>; a. fr.—2) <i>immersion, purification</i>. <span class=\"citation\">Yoma 88ᵃ</span>, a. fr. <span dir=\"rtl\">ט׳ בזמנה מצוה</span> the immersion in due time is obligatory (must not be postponed). <span class=\"citation\">Kerith. 9ᵃ</span>; a. v. fr.—Pl. <span dir=\"rtl\">טְבִילוֹת</span>. <span class=\"citation\">Men. 7ᵇ</span> <span dir=\"rtl\">שיעור ט׳</span> enough for all dippings.—Yoma l. c.; a. fr. <span dir=\"rtl\">חייבי ט׳</span> those bound to take an immersion. <span class=\"citation\">Nidd. 29ᵇ</span> <span dir=\"rtl\">ומטבילין אותה … ט׳</span> and we make her take immersions at intervals during ninety five days; a. fr.</div>","alt":[]},"10241":{"h":"טְבִילוּתָא","r":"I00054","html":"<div class=\"sense\"><span class=\"citation\">Snh. 39ᵃ</span> <span dir=\"rtl\">ומי סלקא ט׳ בנורא</span> is the law requiring immersion (for levitical purification) complied with by putting the object in fire? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עיקר ט׳ וכ׳</span> the true purification is by fire (ref. to <span class=\"citation\">Num. XXXI, 23</span>).</div>","alt":[]},"10242":{"h":"טְבִילְתָּא","r":"I00055","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"טְבִילוּתָא\">same</a>. <span class=\"citation\">Nidd. 30ᵃ</span> <span dir=\"rtl\">ט׳ יתירתא</span> (Rashi <a href=\"#\" data-headword=\"טְבִילָה\">טבילה</a>) an additional immersion.</div>","alt":[]},"10243":{"h":"טְבִיעה I","r":"I00056","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (טָבַע I) <i>being drowned</i>. <span class=\"citation\">Num. R. s. 14</span>, beg. <span dir=\"rtl\">שהסרתי אותו מן הט׳ וכ׳</span> whom I saved from drowning through the intervention of &amp;c. [<span class=\"citation\">Y. Ber. V, 9ᵇ</span> <span dir=\"rtl\">תשנו מטביעה</span>, v. <a href=\"#\" data-headword=\"מַטְבֵּיעַ\">מַטְבֵּעַ</a>.]</div>","alt":[]},"10244":{"h":"טְבִיעָה II","r":"I00057","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְבִיעוּת\">next w.</a></div>","alt":[]},"10245":{"h":"טְבִיעוּת","r":"I00058","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (טָבַע II) <i>impression;</i> ט׳ עַיִן <i>identification of an object from a general impression of its form</i> without stating particular marks. <span class=\"citation\">Sabb. 114ᵃ</span> <span dir=\"rtl\">שמחזירין … בט׳ העין</span> to whom a lost object is restored on his identification etc. [Some ed. <span dir=\"rtl\">טְבִיעַת</span>.]</div>","alt":[]},"10246":{"h":"טְבִיעוּתָא","r":"I00059","html":"<div class=\"sense\"> ch., <span dir=\"rtl\">טְבִיעוּת עֵינָא</span> same. <span class=\"citation\">Gitt. 27ᵇ</span>; <span class=\"citation\">B. Mets. 19ᵃ</span> <span dir=\"rtl\">אי סימנא … או ט׳ע׳ וכ</span> if you require a special mark, I have one on it, if you require identification on general impression, I have it (I recognize it). <span class=\"citation\">Ib. 23ᵇ</span> <span dir=\"rtl\">להדורי … מרבנן בט׳ ע׳</span> as to restoring it to a scholar on his identification &amp;c., v. preced.—<span class=\"citation\">Ḥull. 96ᵃ</span> <span dir=\"rtl\">אית לן ט׳ ע׳ בגויה</span> we know him by his general impression (not by special marks). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ט׳ ע׳ דקלא</span> identification by one’s voice; a. fr.</div>","alt":[]},"10247":{"h":"טְבִירְיָא","r":"I00060","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">טבר׳</span>.</div>","alt":["טְבִירְיוֹס"]},"10248":{"h":"טָבִיתָה","r":"I00061","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טָבִי I\"><span dir=\"rtl\">טָבִי</span> I</a>) <i>Tabitha</i>, name of a handmaid. <span class=\"citation\">Y. Nidd. II, beg. 49ᵈ</span></div>","alt":[]},"10249":{"h":"טָבַל I","r":"I00062","html":"<div class=\"sense\"><b>1)</b> <i>to dip</i>. <span class=\"citation\">Zeb. 93ᵇ</span>, a. e. <span dir=\"rtl\">וט׳ ולא מספג</span>, v. <a href=\"#\" data-headword=\"סָפַג\">סָפַג</a>.</div><div class=\"sense\"><b>—2)</b> <i>to immerse, to bathe for purification.</i> <span class=\"citation\">Yoma VII, 4</span> <span dir=\"rtl\">ירד וט׳</span> went down to the bath and took an immersion. <span class=\"citation\">Ber. 2ᵇ</span> <span dir=\"rtl\">שהכהנים טוֹבְלִין וכ׳</span> when the priests (that have been unclean) bathe in order to be permitted to partake of their priestly share; a. v. fr.—<span class=\"citation\">Ib. 22ᵃ</span> <span dir=\"rtl\">טוֹבְלֵי שחרין</span> those taking a bath in the morning (after emission of semen virile); Y. ib. III, 6ᶜ top <span dir=\"rtl\">ט׳ שחרית</span>.—<span class=\"citation\">Tosef. Yad. II, 20</span> <span dir=\"rtl\">טובלי שחרין</span> (Var. <span dir=\"rtl\">טוֹבְלָנֵי</span>) morning bathers (Essenes, v. Graetz Gesch. d. Jud. III<sup>2</sup>, p. 468, a. for correct vers. R. S. to <span class=\"citation\">Yad. IV, 8</span>).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"טִבּוּל\">טָבוּל</a>.—<span dir=\"rtl\">טְבוּל יום</span> (one who has bathed in day-time,) <i>one who has bathed but must wait for sunset to be perfectly clean</i> (<span class=\"citation\">Lev. XXII, 7</span>). <span class=\"citation\">T’bul Yom I, 1</span>; a. fr.—<span class=\"citation\">Nidd. 30ᵃ</span> <span dir=\"rtl\">טְבוּלַת יום ארוך</span> a woman after bathing whose day is adjourned (having to wait a long time for perfect levitical purity).—טְבוּל יוֹם <i>T’bul Yom</i>, name of a treatise of Mishnah and Tosefta of the order of <i>Tahăroth</i></div><div class=\"sense\"><b>Pi. טִיבֵּל</b> <div class=\"sense\"><b>1)</b> <i>to dip into vinegar, salt &amp;c., to make tasty;</i> esp. <i>to take a luncheon, to take the first course of a meal consisting of relishes; to take the antepast.</i> <span class=\"citation\">Maasr. IV, 1</span> <span dir=\"rtl\">המְטַבֵּל בשדה</span> he who makes a luncheon (of fruits) in the field. <span class=\"citation\">Pes. X, 3</span> <span dir=\"rtl\">מטבל בחזרת</span> he takes lettuce as antepast. <span class=\"citation\">Tosef. ib. X, 9</span> <span dir=\"rtl\">לא טי׳ וכ׳</span> if he has eaten as antepast only &amp;c. <span class=\"citation\">Pes. 107ᵇ</span> אבל מטבל וכ׳ Ms. M. a. comment. (ed. <span dir=\"rtl\">מטביל</span>) but he may make a luncheon of &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">השמש מטבל בבני וכ׳</span> comment. (ed. <span dir=\"rtl\">מטביל</span>; <span class=\"citation\">Tosef. ib. X, 5</span> <a href=\"#\" data-headword=\"מַכְבֵּישׁ\">מכביש</a>, v. <a href=\"#\" data-headword=\"כָּבַשׁ\">כָּבַשׁ</a>); a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">תבל</span>) <i>to season with spices.</i> <i> Part. pass</i>. <a href=\"#\" data-headword=\"טָפַל\">מְטוּבָּל</a>. Y. Shek. III, 47ᶜ top <span dir=\"rtl\">מבושל כמ׳</span> boiled (wine) is (in ritual law) like spiced wine; v. infra.</div></div><div class=\"sense\"><b>Hif. הִטְבִּיל</b> <div class=\"sense\"><b>1)</b> <i>to immerse</i> vessels for purification, <i>to order immersion.</i> <span class=\"citation\">Ter. II, 3</span> <span dir=\"rtl\">המַטְבִּיל כלים וכ׳</span> he who immerses vessels on the Sabbath. <span class=\"citation\">Bets. II, 2</span> <span dir=\"rtl\">מַטְבִּילִין את הכל וכ׳</span> you must immerse whatever needs immersion (both persons and vessels) before &amp;c.—<span class=\"citation\">Ib. 3</span> (<span class=\"citation\">17ᵇ</span>), v. <a href=\"#\" data-headword=\"גַּב\">גַּב</a>.—<span class=\"citation\">Nidd. 29ᵇ</span>, v. <a href=\"#\" data-headword=\"טְבִילָה\">טְבִילָה</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to take luncheon</i>, v. supra.</div><div class=\"sense\"><b>—3)</b> <i>to season</i>. <span class=\"citation\">Erub. 28ᵇ</span> <span dir=\"rtl\">מטבילין בו וכ׳</span> they used to season the roast with it (in place of pepper).</div></div><div class=\"sense\"><b>Hof. הוּטְבָּל</b> <div class=\"sense\"><i>to be immersed, to be made clean.</i> <span class=\"citation\">Mikv. V, 6</span> <span dir=\"rtl\">לא הוּטְבָּלוּ</span> are not considered as clean through immersion; <span class=\"citation\">Tosef. ib. IV, 10</span>.</div></div>","alt":[]},"10250":{"h":"טְבַל","r":"I00063","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. IX, 9</span>; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"טְבַל\">טְבִיל</a>, f. <a href=\"#\" data-headword=\"טְבִילָה\">טְבִילָא</a>. <span class=\"citation\">Targ. Josh. III, 15</span> (טְבִילָן?).—<span class=\"citation\">Snh. 39ᵃ</span> <span dir=\"rtl\">במאי טביל</span> wherewith did he purify himself (after contact with a corpse)?; <span dir=\"rtl\">בנורא טביל</span> he did it by means of fire, v. <a href=\"#\" data-headword=\"טְבִילָה\">טְבִילָה</a>. <span class=\"citation\">Nidd. 30ᵃ</span> <span dir=\"rtl\">לִיטְבְּלָהּ</span> let her bathe; a. fr.—</div><div class=\"sense\"><b>Af. אַטְבֵּיל</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"טָבַל I\">preced.</a> <i>Hif.</i></div><div class=\"sense\"><b>1)</b> <i>to immerse, order immersion</i>. Nidd. l. c. <span dir=\"rtl\">אַטְבְּלִינָן לה</span> we make her bathe. <span class=\"citation\">Bets. 19ᵃ</span> <span dir=\"rtl\">לאַטְבּוּלֵיה</span> to immerse it; a. fr.</div><div class=\"sense\"><b>—2)</b>  as <a href=\"#\" data-headword=\"טָבַל I\">preced.</a> <i>Pi</i>. 1, <i>to take an antepast</i>. <span class=\"citation\">Pes. 114ᵇ</span> <span dir=\"rtl\">למיהדר לאַטְבּוּלֵי</span> must take the bitter herb a second time; a. e.</div></div>","alt":["(טְבִיל)"]},"10251":{"h":"טָבַל II","r":"I00064","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"טֶבֶל\">טֶבֶל</a>) <i>to create Tebel, to make obligatory the setting aside of tithes&amp;c</i>. <span class=\"citation\">Y. Maasr. IV, beg. 51ᵃ</span> <span dir=\"rtl\">אור טוֹבֵל</span> fire (roasting) makes subject to sacred gifts; <span dir=\"rtl\">מלח טוֹבֶלֶת</span> salting makes subject &amp;c.; a. fr.—<i>Part. part.</i> טָבוּל <i>that which is subject to sacred gifts, forbidden as Tebel</i>. <span class=\"citation\">Ber. 47ᵇ</span> טבל ט׳ מדרבנן <i>Tebel</i> declared to be such by rabbinical enactment; a. e.—Pl. <span dir=\"rtl\">טְבוּלִים</span>, <span dir=\"rtl\">טְבוּלִין</span>. Y. Dem. VI, 25ᶜ bot., opp. <span dir=\"rtl\">מתוקנים</span>. Ib. VII, 26ᵇ top <span dir=\"rtl\">פירות ט׳</span> fruits of which the sacred gifts have not been set aside.</div><div class=\"sense\"><b>Nif. נִטְבָּל</b> <div class=\"sense\"><i>to become</i>, or <i>to be declared Tebel</i>. Y. Maasr. I, end, 49ᵇ טבל שנ׳ מדבריהן <i>Tebel</i> which is declared to be such by rabbinical law, v. supra. Ib. IV, beg. 51ᵃ <span dir=\"rtl\">נִטְבְּלוּ</span> the roasted ears became subject to tithes; a. fr.</div></div>","alt":[]},"10252":{"h":"טְבַל ²","r":"I00065","html":"<div class=\"sense\"> <span class=\"citation\">Men. 70ᵃ</span> <span dir=\"rtl\">טַבְלָהּ לה</span> (not <a href=\"#\" data-headword=\"טִבְלָא\">טבלא</a>) he made it subject to tithes. <span class=\"citation\">Bets. 13ᵃ</span> טַבְלָן ביומיה Ms. M. (ed. <a href=\"#\" data-headword=\"טִבְלָא\">טבלא</a>, corr. acc.) he made them <i>Tebel</i> on that day (by designating them for immediate use); a. e.</div>","alt":[]},"10253":{"h":"טֶבֶל","r":"I00066","html":"<div class=\"sense\">, v. <i>Pi</i>. a. <i>Hif.</i>) <i>fruits of which you are permitted to make a luncheon or improvised meal in the field without separating the priestly or levitical shares</i>. <span class=\"citation\">Ber. 35ᵇ</span> <span dir=\"rtl\">איו הט׳ טתחייב וכ׳</span> the <i>tebel</i> is not subject to tithes, until it is brought home (for consumption or storage).—Esp. <i>Tebel, produces inthat stage in which the separation of levitical and priestly shares respectively is required, before you may partake of them; eatables forbidden pending the separation of sacred gifts.</i> <span class=\"citation\">Ter. X, 6</span> <span dir=\"rtl\">חבילי תלתן של ט׳</span> bundles of fenugrec subject to T’rumah; expl. <span class=\"citation\">Bets. 13ᵃ</span> <span dir=\"rtl\">ט׳ טבול של תרומה</span> (Rashi: <span dir=\"rtl\">לתרומה</span>) <i>Tebel</i> considered as such, because it is subject to T’rumah (<span class=\"citation\">Deut. XVIII, 4</span>; Ms. M. <span dir=\"rtl\">של ת׳ גדולה</span> to the general gifts of T’rumah and tithes); <span dir=\"rtl\">ט׳ טבול של תרומת מעשר</span> <i>Tebel</i> (in the possession of a Levite who received it for tithes, and) considered <i>Tebel</i>, because it is subject to the T’rumah from tithes (<span class=\"citation\">Num. XVIII, 26</span>). <span class=\"citation\">Ter. IX, 6</span> <span dir=\"rtl\">הט׳ גדוליו וכ׳</span> the growth of seeds that had been subject to sacred gifts the separation of which had been omitted &amp;c. <span class=\"citation\">Ib. 7</span> <span dir=\"rtl\">אע&quot;פ שפירותיו ט׳</span> although its growth is considered <i>Tebel</i> (because the seeds were not tithed) &amp;c. <span class=\"citation\">Kidd. 58ᵇ</span> <span dir=\"rtl\">טִיבְלוֹ של וכ׳</span> his neighbor’s <i>Tebel; </i>a. fr.—[<span class=\"citation\">Erub. 86ᵃ</span> <span dir=\"rtl\">יש לו ט׳</span>, read: <a href=\"#\" data-headword=\"טַבְלָא I\"><span dir=\"rtl\">טַבְלָא</span> I</a>.].—Pl. <span dir=\"rtl\">טְבָלִים</span>. Ib.—<span class=\"citation\">Ned. 20ᵃ</span> <span dir=\"rtl\">סיפך להאכילך ט׳</span> he will finally give thee to eat things from which the tithes have not been given. <span class=\"citation\">Ḥull. 132ᵇ</span>; a. e.</div>","alt":["טָבַל I"]},"10254":{"h":"טִבְלָא","r":"I00067","html":"<div class=\"sense\"> <span class=\"citation\">Nidd. 46ᵇ</span> ט׳ דאורייתא <i>Tebel</i> by Biblical law (lacking the separation of T’rumah). <span class=\"citation\">Bets. 13ᵃ</span> <span dir=\"rtl\">אסורייתא טובלא</span> (some ed., corr. acc.), v. <a href=\"#\" data-headword=\"אֲסוּרְיָיתָא\">אֲסוּרְיָיתָא</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">התם לא ט׳ וכ׳</span> there (in the case of ears, ib.) it was not subject to T’rumah &amp;c.; a. e.</div>","alt":[]},"10255":{"h":"טַבְלָא I","r":"I00068","html":"<div class=\"sense\"> (<span dir=\"rtl\">טבל</span>, cmp. Aeth. <span dir=\"rtl\">טבלל</span> <i>to tie around</i>, v. Ges. H. Dict.<sup>10</sup> s. v. <span dir=\"rtl\">טְבוּלִים</span>; cmp. <a href=\"#\" data-headword=\"טַבַּעַת\">טבעת</a>, <span dir=\"rtl\">טבור</span>) a <i>bell</i> or <i>collection of bells</i>, an instrument especially used at public processions (in Arab. <i>drum</i>, Gr. ταβαλά; v. Sm. Ant. s. v. Tintinnabulum as to forms and uses of bells). <span class=\"citation\">Targ. Koh. VII, 5</span> <span dir=\"rtl\">קל ט׳ וכ׳</span> the music of the fools. <span class=\"citation\">Targ. Cant. I, 1</span>.—<span class=\"citation\">Sot. 49ᵇ</span> (expl. <a href=\"#\" data-headword=\"אֵירוּס I\">אֵירוּס</a>) <span dir=\"rtl\">ט׳ דחד פומא</span> a <i>tabla</i> with one mouth (a single bell). <span class=\"citation\">Ber. 57ᵃ</span> <span dir=\"rtl\">תלאי ט׳ וכ׳</span> (I dreamt) I suspended a <i>tabla</i> and shouted into it (differ. in Rashi). <span class=\"citation\">Sabb. 110ᵃ</span> <span dir=\"rtl\">בט׳</span> to the sound of a <i>tabla</i> (at a wedding). <span class=\"citation\">M. Kat. 9ᵇ</span> (prov.) <span dir=\"rtl\">בת שיתין … לקל ט׳ רהטא</span> a woman of sixty years, like one of six, runs at the sound of the <i>tabla</i> (to see the procession). Y. Erub. VIII, 25ᵃ bot. <span dir=\"rtl\">אפי׳ ט׳</span> if even he has there a <i>t</i>. (which he dare not move on the Sabbath); Bab. <span class=\"citation\">Erub. 86ᵃ</span> <span dir=\"rtl\">יש לו טבל</span>.—In gen. <i>musical instrument</i>. <span class=\"citation\">Arakh. 10ᵇ</span>, v. <a href=\"#\" data-headword=\"*גּוּרְגָּנָא\">גּוּרְגָּנָא</a>.</div>","alt":[]},"10256":{"h":"טַבְלָא II","r":"I00069","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (tabula, tabella, τάβλα) <i>plank, board, tablet for writing; book of accounts, list; will</i>. <span class=\"citation\">Erub. IV, 8</span> (<span class=\"citation\">49ᵇ</span>) <span dir=\"rtl\">כטבלה מרובעת</span> (Talm. ed. <span dir=\"rtl\">כטבלא</span>) like a square tablet. <span class=\"citation\">R. Hash. II, 8</span> (<span class=\"citation\">24ᵃ</span>) <span dir=\"rtl\">על הט׳ בכותל</span> Ms. M. (ed. <span dir=\"rtl\">בט׳ ובכותל</span>, v. Rabb. D. S. a. l. note) (drawings of the phases of the moon) on a tablet on the wall. <span class=\"citation\">Gitt. 20ᵃ</span> <span dir=\"rtl\">כתב שע&quot;ג ט׳ ופינקס</span> writing (of manumission) on a tablet or on a board (account book or will, v. Treat. ‘Ăbadim, ed. Kirchh. ch. III, Rev. des Etudes Juives 1883, p. 150). Y. Snh. I, 18ᵈ bot. <span dir=\"rtl\">ט׳של רפואות</span> list of (superstitious) remedies (<span class=\"citation\">Pes. 56ᵃ</span> <span dir=\"rtl\">ספר וכ׳</span>); a. fr.—[<span class=\"citation\">Y. Bets. I, 60ᶜ</span> bot. <span dir=\"rtl\">טבלה ברייתא וכ׳</span> (read <span dir=\"rtl\">טַבְלָתָה</span> <i>pl.</i>) the outside stone plates of the colonnade of Asi.]—<i>Pl.</i> <span dir=\"rtl\">טַבְלָאוֹת</span>, <span dir=\"rtl\">טַבְלָיוֹת</span>. Y. B. Bath. VI, 14ᶜ bot. <span dir=\"rtl\">ט׳ של שיש וכ׳</span> polished marble plates for walls. <span class=\"citation\">Yalk. Ex. 426</span> <span dir=\"rtl\">ונראין ט׳ ט׳ וכ׳</span> and they appeared like marked off squares surrounding &amp;c. <span class=\"citation\">Pes. 57ᵃ</span> <span dir=\"rtl\">ט׳ של זהב</span> gold plates.—Chald. pl. <span dir=\"rtl\">טַבְלָתָה</span>, v. supra.</div>","alt":["טַבְלָה"]},"10257":{"h":"טַבְלָא III","r":"I00070","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Tabla</i>, an Amora. <span class=\"citation\">Ḥull. 132ᵇ</span> <span class=\"citation\">Y. Gitt. IV, 46ᵃ</span>; a. e; v. <a href=\"#\" data-headword=\"טַבְלַאי\">next w.</a></div>","alt":[]},"10258":{"h":"טַבְלַאי","r":"I00071","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Tablai</i>, an Amora. Y. Erub. V, 25ᵃ bot.; (<span class=\"citation\">Sabb. 101ᵃ</span> <a href=\"#\" data-headword=\"טַבְלָא I\">טַבְלָא</a>).—<span class=\"citation\">Y. Sabb. VI, 8ᵃ</span> bot.; a. e.</div>","alt":["טַבְלַיי"]},"10259":{"h":"טַבְלָה","r":"I00072","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַבְלָא II\"><span dir=\"rtl\">טַבְלָא</span> II</a></div>","alt":[]},"10260":{"h":"טַבְלַיי","r":"I00073","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַבְלַאי\">טַבְלַאי</a></div>","alt":[]},"10261":{"h":"*טַבְלָר","r":"I00074","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (tabellarius) <i>courier</i>.—Pl. <span dir=\"rtl\">טַבְלָרִין</span>. <span class=\"citation\">Pesik. R. s. 21</span> [read:] <span dir=\"rtl\">ט׳ שלו ושמו חקוק על לבם כהדין איספרגיס</span> the angels are His couriers, and His name is engraven upon their hearts like a seal (v. Pesik. Baḥod, p. 108ᵇ, note 16</div>","alt":[]},"10262":{"h":"טַבְלָרָא","r":"I00075","html":"<div class=\"sense\"><span class=\"citation\">Targ. Prov. XXIV, 34</span> (h. text <span dir=\"rtl\">איש מגן</span>).</div>","alt":[]},"10263":{"h":"טָבַע I","r":"I00076","html":"<div class=\"sense\"><b>1)</b>  (act. verb) <i>to sink, drown</i>. <span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">לטוֹבְעוֹ</span> to drown him (sink his ship). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">טְבָעוֹ</span> He drowned him; a. fr.</div><div class=\"sense\"><b>—2)</b>  (neut. verb) <i>to sink, be drowned</i>. <span class=\"citation\">Ber. 16ᵇ</span> <span dir=\"rtl\">טָבְעָה ספינתו וכ׳</span> if his ship went down &amp;c. <span class=\"citation\">Meg. 10ᵇ</span>; <span class=\"citation\">Snh. 39ᵇ</span> <span dir=\"rtl\">מעשה ידי טוֹבְעִין וכ׳</span> my creatures (Egyptians) are perishing in the sea, and you want to sing?; a. e.</div><div class=\"sense\"><b>Hif. הִטְבִּיעַ</b> <div class=\"sense\"><i>to sink</i>. <span class=\"citation\">Yalk. Gen. 120</span> ה׳ האבן He made the stone sink down to the depth &amp;c.; (<span class=\"citation\">Pirké d’R. El. ch. XXXV</span>, <span dir=\"rtl\">וטָבְעָה האבן</span>; <span class=\"citation\">Midr. Till. to Ps. XCI</span>, end <span dir=\"rtl\">וטבע אותה</span>). <span class=\"citation\">Yalk. Ex. 241</span> <span dir=\"rtl\">להַטְבִּיעַ את מצרים</span> to drown the Egyptians; a. e.</div></div>","alt":[]},"10264":{"h":"טְבַע","r":"I00077","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Gen. IV, 8</span>.—<span class=\"citation\">Targ. I Sam. XVII, 49</span>; a. e.—<span class=\"citation\">Pes. 40ᵇ</span> <span dir=\"rtl\">ארבא … דטָבְעָא וכ׳</span> a ship with wheat sank &amp;c. <span class=\"citation\">Sabb. 108ᵇ</span> <span dir=\"rtl\">מעולם לא ט׳ וכ׳</span> never was yet a man drowned in the Lake of Sodom. <span class=\"citation\">B. Bath. 153ᵃ</span> <span dir=\"rtl\">אמרה לִיטְבַּע ארביה</span> (Ms. H. <span dir=\"rtl\">אמרה ליה טבאי וכ׳</span>, Ar. <span dir=\"rtl\">אמרה לו טבאי</span>) said she, May his (thy) ship go under; a. e.—[<span class=\"citation\">Targ. Y. Deut. XXVIII, 29</span> <span dir=\"rtl\">טביעין</span> some ed., read. <span dir=\"rtl\">תב׳</span>, v. <a href=\"#\" data-headword=\"תְּבַע\">תְּבַע</a>.]</div><div class=\"sense\"><b>Pa. טבַּע</b> <div class=\"sense\"><i>to sink</i>. <span class=\"citation\">B. Bath. 73ᵃ</span> <span dir=\"rtl\">גלא דמְטַבַּע וכ׳</span> the wave which threatens to sink the ship. <span class=\"citation\">Ḥull. 60ᵃ</span> <span dir=\"rtl\">אתא מיטרא טַבְּעֵיה בימא</span> there came a rain and sank the provision into the sea.</div></div><div class=\"sense\"><b>Ithpa. אִיטַּבַּע</b> <div class=\"sense\"><i>to be sunk</i>. <span class=\"citation\">Targ. O. Ex. XV, 4</span>.</div></div>","alt":[]},"10265":{"h":"טָבַע II","r":"I00078","html":"<div class=\"sense\"> [<i>to round, shape</i>, denom. <a href=\"#\" data-headword=\"טֶבַע\">טֶבַע</a>, fr. which <a href=\"#\" data-headword=\"טָבַע I\">טָבַע</a>] </div><div class=\"sense\"><b>1)</b> <i>to coin</i>. <span class=\"citation\">Snh. IV, 5</span> (<span class=\"citation\">37ᵃ</span>) <span dir=\"rtl\">אדם טוֹבֵעַ כמה מטבעות וכ׳</span>, v. <a href=\"#\" data-headword=\"חוֹתָם\">חוֹתָם</a>; Y. ib. VI, 22ᵇ bot.; a. e.—Trnsf. <i>to formulate</i>. <span class=\"citation\">Gitt. 5ᵇ</span>, a. e. <span dir=\"rtl\">כל המשנה ממטבע שטָבְעוּ וכ׳</span> he who deviates from the formula of the deed of divorce which the scholars have fixed. <span class=\"citation\">Ber. 40ᵇ</span> <span dir=\"rtl\">כל המשנה … שט׳ … בברכות</span> he who changes the formula of benedictions which &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to specify, mention explicitly</i>. <span class=\"citation\">Num. R. s. 20</span> (ref. to <span class=\"citation\">Deut. XXVII, 12</span>, sq.) <span dir=\"rtl\">בברכות היה מזכירן … לא היה טוֹבְעָן</span> in ordering blessings He mentioned them (the people) …, but in ordering curses He did not mention them explicitly; (Tanḥ. Balak 12 <span dir=\"rtl\">לא היה מזכירם</span>; ed. Bub. 18 <span dir=\"rtl\">תובען</span>, <span class=\"citation\">Yalk. Num. 766</span> <span dir=\"rtl\">תובעין</span>, incorr.)</div>","alt":[]},"10266":{"h":"טְבַע ²","r":"I00079","html":"<div class=\"sense\">, <i>to assume shape</i>. <span class=\"citation\">Targ. Prov. VIII, 25</span> <span dir=\"rtl\">נִטְבְּעוּן</span>.</div>","alt":[]},"10267":{"h":"טֶבַע","r":"I00080","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טָבַע II\"><span dir=\"rtl\">טָבַע</span> II</a>) </div><div class=\"sense\"><b>1)</b> <i>coin, medal</i>. <span dir=\"rtl\">טִבְעוֹ של פ׳ יצא</span> one’s coin passes, i.e. one’s authority is recognized. <span class=\"citation\">Shebu. 6ᵇ</span> זו רומי חייבת שטִיבְעָהּ וכ׳ Ms. M. (ed. <span dir=\"rtl\">פרס</span>) that is wicked Rome whose government is recognized all over the world. <span class=\"citation\">Meg. 14ᵇ</span> <span dir=\"rtl\">לא יצא טִבְעֲךָ בעולם</span> thou art not yet the legitimate king; cmp. <a href=\"#\" data-headword=\"מוֹנִיטָא\">מוֹנִיטָא</a>. [<span class=\"citation\">Y. Ber. V, 9ᵇ</span> <span dir=\"rtl\">מטבעה של תפלה</span> ed. Lehm., oth. ed. <span dir=\"rtl\">מטביעה</span>, v. <a href=\"#\" data-headword=\"מַטְבֵּיעַ\">מַטְבֵּעַ</a>.]</div><div class=\"sense\"><b>—2)</b> <i>Tebʿa</i>, a coin equal to half a Sela. <span class=\"citation\">Y. Shek. II, 46ᵈ</span> top (the ten brothers) sold Rachel’s first-born for twenty silver pieces (denars) <span dir=\"rtl\">ונפל לכל א׳ וא׳ מהם ט׳</span> so that a Tebʿa came upon each (Bab. ed. <span dir=\"rtl\">טבעה</span>, <span dir=\"rtl\">טיבעה</span>, Ms. M. <span dir=\"rtl\">טובע</span>).—Pl. <span dir=\"rtl\">טְבָעִים</span>, <span dir=\"rtl\">טְבָעִין</span> (<a href=\"#\" data-headword=\"טוֹבְעִין\">טוֹבְעִין</a>, fr. <span dir=\"rtl\">טוֹבַע</span>). <span class=\"citation\">Shek. II, 4</span>. Y. l. c. <span dir=\"rtl\">טו׳ פלגי סלעין</span> (Bab. <span dir=\"rtl\">טבעין</span>) <i>tibʿin</i> i.e. half-Shekels.</div><div class=\"sense\"><b>—3)</b> <i>that which is to be shaped, substance, element</i>.—Pl. as ab. <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">כנגד ארבעה ט׳ וכ׳</span> corresponding to the four elements of which the Lord created &amp;c. [In later Hebr.: <i>nature, character; Nature</i>.]</div>","alt":[]},"10268":{"h":"טְבַע II","r":"I00081","html":"<div class=\"sense\">, <i>coin;Tebʿa</i>. <span class=\"citation\">Targ. Y. Gen. XXIV, 22</span> Levita (ed. <span dir=\"rtl\">דרכמונא</span>; v. Y. Shek. II, 46ᵈ top, quot. in <a href=\"#\" data-headword=\"טֶבַע\">preced.</a>). <span class=\"citation\">Targ. Y. Ex. XXX, 13</span> (ed. Amst. <a href=\"#\" data-headword=\"טִבְעָא\">טַבְעָא</a>). Targ. II Esth. VI, 10 <span dir=\"rtl\">טִבְעִי וטִבְעָךְ אזיל וכ׳</span>, v. preced.—<span class=\"citation\">B. Mets. 46ᵃ</span> <span dir=\"rtl\">דליכא עלייהו ט׳</span> which have no stamp. <span class=\"citation\">Ib. 44ᵇ</span> <span dir=\"rtl\">הוי ט׳</span> is considered as coin (money), opp. to <a href=\"#\" data-headword=\"פֵּירָא I\">פירא</a> merchandise. <span class=\"citation\">Shebu. 6ᵇ</span> <span dir=\"rtl\">ט׳ דמאן וכ׳</span> the coin of which goes farther (whose power is greater)?—<span class=\"citation\">Nidd. 20ᵇ</span> <span dir=\"rtl\">ט׳ דבבל וכ׳</span> the Babylonian coin (which I could not understand) was the cause &amp;c.; a. fr.—Pl. <span dir=\"rtl\">טִבְעֵי</span>. <span class=\"citation\">B. Mets. 25ᵃ</span> ט׳ מכריז Ms. H. a. R. (ed. sing.). he publishes that he has found ‘coins’.</div>","alt":["טִבְעָא","טִיבְ׳ I"]},"10269":{"h":"טִבְעָא","r":"I00082","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"טְבִיעה I\">טְבִיעָה</a>, <i>shipwreck</i>. <span class=\"citation\">B. Bath. 153ᵃ</span> <span dir=\"rtl\">לא איפרק מט׳</span> (Ms. M. <span dir=\"rtl\">מעונשיה</span>) did not escape the loss through shipwreck (which the woman had wished him.)</div>","alt":["טִיבְעָא II"]},"10270":{"h":"טִבְעוֹן","r":"I00083","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Tibon</i> or <i>Tibin</i> (prob. <i>Tubun</i>, west of Sepphoris, Neub. Géogr. p. 196). <span class=\"citation\">Makhsh. I, 3</span>, v. <a href=\"#\" data-headword=\"חֲלִיקוּפְרִי\">חֲלִיקוּפְרִי</a>.—<span class=\"citation\">Tosef. Meg. II, 5</span>; Y. ib. IV, beg. 74ᶜ <span dir=\"rtl\">בה&quot;כ של טיבעין</span> the synagogue of T.—<span class=\"citation\">Sifré Deut. 323</span> <span dir=\"rtl\">איש טיבעים</span>; <span class=\"citation\">Yalk. Deut. 946</span> <span dir=\"rtl\">כפר טיבעין</span>.—[<span class=\"citation\">Erub. 29ᵃ</span> bot. <span dir=\"rtl\">לטיבעין</span> (Var. <span dir=\"rtl\">טביעים</span>, v. Rabb. D. S. a. l. note 6), missing in Tosef. ib. IX (VI), 4, v. <a href=\"#\" data-headword=\"עַרְדִּיסְקָא\">עַרְדִּיסְקוֹס</a>.]</div>","alt":["טִבְעִין","טִי׳","(טִבְעִים)"]},"10271":{"h":"טִבְעוֹנִי","r":"I00084","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טִבְעוֹן\">preced.</a>) <i>of Tibon, Tibonite</i>.—Pl. <a href=\"#\" data-headword=\"טִבְעוֹנִי\">טִבְעוֹנִין</a>, <a href=\"#\" data-headword=\"טִבְעוֹן\">טִי׳</a>. <span class=\"citation\">Y. Ber. II, 4ᵈ</span> bot.; <span class=\"citation\">Meg. 24ᵇ</span> <span dir=\"rtl\">אנשי טבעונין</span> (prob. to be read: <a href=\"#\" data-headword=\"טִבְעוֹן\">טִבְעוֹן</a>).</div>","alt":[]},"10272":{"h":"טִבְעִים","r":"I00085","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טִבְעוֹן\">טִבְעוֹן</a></div>","alt":["טִבְעִין"]},"10273":{"h":"טַבַּעַת","r":"I00086","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>round band, ring</i>. <span class=\"citation\">Tosef. Kel. B. Mets. II, 1</span> <span dir=\"rtl\">ט׳ שהוא חוגר וכ׳</span> a ring which one puts around his loins; <span dir=\"rtl\">ט׳ של אצבע</span> finger ring; <span class=\"citation\">Sabb. 52ᵇ</span>. Ib.; <span class=\"citation\">Kel. XII, 1</span> <span dir=\"rtl\">ט׳ אדם</span> ornamental ring; <span dir=\"rtl\">ט׳ בהמה והכלים</span> a ring used for beasts or for garments (for fastening); a. fr.—Esp. <i>seal-ring</i>. <span class=\"citation\">Sabb. 59ᵇ</span>. <span class=\"citation\">Deut. R. s. 2</span>; a. fr.—<span dir=\"rtl\">הֲסָרַת ט׳</span> the authority given by transfer of the ring. <span class=\"citation\">Meg. 14ᵃ</span>; <span class=\"citation\">Lam. R. to IV, 22</span>.—Pl. <span dir=\"rtl\">טַבָּעוֹת</span>. Sabb. l. c.; a. fr.—<span class=\"citation\">Ab. d’R. N. ch. XVIII</span> <span dir=\"rtl\">ט׳ ט׳</span>, v. <a href=\"#\" data-headword=\"מַטְבֵּיעַ\">מַטְבֵּעַ</a>.—Trnsf. (<span dir=\"rtl\">פי הט׳</span>) <i>anus, end of the rectum</i>. <span class=\"citation\">B. Kam. 92ᵃ</span>. <span class=\"citation\">Sabb. 108ᵇ</span> bot.; a. fr.—Y. ib. VIII, end, 11ᶜ <span dir=\"rtl\">לטבעות</span>, read <span dir=\"rtl\">לטבעת</span>, v. <a href=\"#\" data-headword=\"אַמְבְּטִיתָא\">אַמְבְּטִיתָא</a>.</div>","alt":[]},"10274":{"h":"טברטי","r":"I00087","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טבריטי\">טבריטי</a></div>","alt":[]},"10275":{"h":"טְבַרְיָא","r":"I00088","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Tiberias</i> in Galilee. <span class=\"citation\">Targ. Y. I Num. XXXIV, 8</span>, v. <a href=\"#\" data-headword=\"חֲמָת\">חֲמָת</a>. <span class=\"citation\">Targ. Y. I Deut. III, 17</span> (?). <span class=\"citation\">Ib. XXXIII, 23</span>.—<span class=\"citation\">Gen. R. s. 23</span>, beg. <span dir=\"rtl\">ט׳ ע&quot;ש טיביריאוס</span> Tiberias is named after Tiberius; <span class=\"citation\">Yalk. Ps. 758</span> (corr. acc.). <span class=\"citation\">Gen. R. s. 31</span>, v. <a href=\"#\" data-headword=\"בְּטִיטָא\">בְּטִיטָא</a>. <span class=\"citation\">Meg. 6ᵃ</span>; a. fr.—<span class=\"citation\">Y. Taan. IV, 69ᵇ</span> bot. <span dir=\"rtl\">טיברי</span> (corr. acc.).—Denom. <a href=\"#\" data-headword=\"טִיבְרָנִי\">טִיבְרָנִי</a>, f. <a href=\"#\" data-headword=\"טִיבְרָנִי\">טִיבְרָנִית</a>. <span class=\"citation\">Y. Ḥall. II, 58ᶜ</span> bot. Y. Pes. X, 37ᶜ bot. <span dir=\"rtl\">ט׳ ישנה</span> old Tiberian measure.—Pl. <span dir=\"rtl\">טִיבְרָנִיּוֹת</span>. Y. Keth. I, 25ᵇ top <a href=\"#\" data-headword=\"סביריניות\">סביריניות</a> (corr. acc.), v. <a href=\"#\" data-headword=\"הָגַן\">הָגַן</a>.—<i>Ch.</i> <a href=\"#\" data-headword=\"טִיבַרְיָאָה\">טִיבַרְיָאָה</a>, pl. <a href=\"#\" data-headword=\"טִיבַרְיָאָה\">טִיבַרְיָאֵי</a>. Y. Taan. l. c. Y. Bets. II, 61ᵇ top <span dir=\"rtl\">טיבראי</span> (corr. acc.)</div>","alt":["טְבַרְיָה","טִיבַ׳","(טְבִירְיָא)"]},"10276":{"h":"טְבִרְיוֹס","r":"I00089","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Tiberius</i>, the Roman emperor. <span class=\"citation\">Yalk. Ps. 758</span> (not … <a href=\"#\" data-headword=\"ת\">ת</a>); <span class=\"citation\">Gen. R. s. 23</span> <a href=\"#\" data-headword=\"טִיבִירְיָא\">טיביריאוס</a>, <a href=\"#\" data-headword=\"טִיבַרְיָאָה\">טיבריאוס</a>, v. <a href=\"#\" data-headword=\"טְבַרְיָא\">preced.</a></div>","alt":["טְבִירְ׳"]},"10277":{"h":"טבריטי","r":"I00090","html":"<div class=\"sense\">, Pesik. Hashsh’mini, p. 191ᵇ Ms. O. (ed. <span dir=\"rtl\">נוב בעי</span>); Pesik. R., addit. (ed. Fr., p. 201, v. Var. lect. notes a. l.),—a corruption, prob. to be read: <span dir=\"rtl\">טְיָיטְרוֹן</span> or <a href=\"#\" data-headword=\"תִּיאַטְרוֹן\">תִּיאַטְרוֹן</a> (q. v.) <i>theatre, spectators</i>, opp. <span dir=\"rtl\">קנגיא</span> (κυνήγιον) the participants in the fights of the arena; cmp. <a href=\"#\" data-headword=\"בלטוורא\">בלטוורא</a>.</div>","alt":["טברטי","טברירי"]},"10278":{"h":"טִבְרֵר","r":"I00091","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"טִיבּוּר\">טיבור</a>) [<i>to measure the length from shoulder to belly</i>, v. <span class=\"citation\">Macc. III, 13</span>, a. Bart. a. l.; Tosef. ib. V (IV), 15,] <i>to lash a transgressor</i> with a strap commensurate to his size (v. <a href=\"#\" data-headword=\"מַלְקוּת\">מַלְקוּת</a>). Y. Yoma V, 42ᶜ (expl. <a href=\"#\" data-headword=\"מַצְלִיף\">מצליף</a>, Mish. <span class=\"citation\">ib. V, 5</span>) <span dir=\"rtl\">כמְטַבְרֵיר</span> Ar. s. v. <span dir=\"rtl\">צלף</span> (ed. <span dir=\"rtl\">כמטוורד</span>, read <span dir=\"rtl\">כמְטַוְורֵר</span>, cmp. <a href=\"#\" data-headword=\"טוּר II\">טַוְורָא</a>) like the movement of the lasher in court; (cmp. Bab. ib. 55ᵃ top <span dir=\"rtl\">כמנגדנא</span>).</div>","alt":[]},"10279":{"h":"טֵבֵת","r":"I00092","html":"<div class=\"sense\"> (b. h.); <i>Tebeth</i>, the tenth month of the Hebrew calendar, containing twenty nine days, varying between the second of December and the twenty ninth of January. <span class=\"citation\">Targ. Esth. II, 16</span>. Targ. II Esth. III, 7. Ib. 8 <span dir=\"rtl\">מלקטין פשרי דט׳</span> store up the melting snows of Tebeth (in their cisterns).—<span class=\"citation\">Taan. 6ᵇ</span> <span dir=\"rtl\">טבא … דט׳ מנוולתא</span> auspicious is the year whose Tebeth is ugly (muddy from heavy rains); <span dir=\"rtl\">דט׳ ארמלתא</span> whose Tebeth is a widow (without rain, v. <a href=\"#\" data-headword=\"בַּעֲלָא\">בַּעֲלָא</a>).</div>","alt":[]},"10280":{"h":"*טַבָּת","r":"I00093","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טָבָאוּת\">טָבָאוּת</a>) (<i>in a</i>) <i>good condition, right</i>. <span class=\"citation\">Gen. R. s. 26</span> (ref. to <span dir=\"rtl\">טֹבֹת</span>, <span class=\"citation\">Gen. VI, 2</span>) <span dir=\"rtl\">טבת כתיב משהיו מטיבין וכ׳</span> you may read <i>tabbath</i></div>","alt":[]},"10281":{"h":"טַבְתָא","r":"I00094","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַב I\">טַב</a></div>","alt":[]},"10282":{"h":"טגיות","r":"I00095","html":"<div class=\"sense\">, <span class=\"citation\">Sifré Deut. 234</span> quot. in Ar. (ed. <a href=\"#\" data-headword=\"יגא\">יגא</a>), v. <a href=\"#\" data-headword=\"*טוֹגָא\">טוֹגָא</a></div>","alt":[]},"10283":{"h":"טגים","r":"I00096","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 43</span>, v. <a href=\"#\" data-headword=\"טִיגָּן\">טִיגֵּן</a>, s. v. <a href=\"#\" data-headword=\"טִיגָּן\">טִיגָּן</a>.</div>","alt":[]},"10284":{"h":"טָגַן","r":"I00097","html":"<div class=\"sense\">, <i>Pi</i>. <a href=\"#\" data-headword=\"טִיגָּן\">טִיגֵּן</a>, v. <a href=\"#\" data-headword=\"טִיגָּן\">טִיגָּן</a>.</div>","alt":[]},"10285":{"h":"טִגְרוֹס","r":"I00098","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (tigris, v. Sm. Ant. s. v.) <i>tiger</i>. <span class=\"citation\">Ḥull. 59ᵇ</span> <span dir=\"rtl\">ט׳ אריה וכ׳</span> the tiger is the lion of Be-Ilai (the mountains of interior Asia), i.e. what the lion is in other regions.</div>","alt":["טִגְרֵס"]},"10286":{"h":"טָדִי","r":"I00099","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Tadi</i>, <span dir=\"rtl\">(<a href=\"#\" data-headword=\"שְׁעַר\">שְׁעַר</a>) <a href=\"#\" data-headword=\"ט׳\">ט׳</a></span>, name of a northern gate of the Temple. <span class=\"citation\">Midd. I, 3</span>; <span class=\"citation\">9</span>; <span class=\"citation\">II, 3</span> (Var. <a href=\"#\" data-headword=\"טרי\">טרי</a>).</div>","alt":[]},"10287":{"h":"טָהוֹר","r":"I00100","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"טָהֵר\">next w.</a>) </div><div class=\"sense\"><b>1)</b> <i>clean, pure; not subject to levitical uncleanness</i>. <span class=\"citation\">B. Mets. 86ᵃ</span> <span dir=\"rtl\">שגופך ט׳ … נשמתך בט׳</span> (Ms. <span dir=\"rtl\">בטהרה</span>) thy body is pure, and thy soul expired with (the word) ‘pure’; <span class=\"citation\">Snh. 68ᵃ</span>.—<span class=\"citation\">Kidd. 70ᵇ</span> <span dir=\"rtl\">וסימניך טמא טמא ט׳ ט׳</span> and the sign (by which to remember which of the two families is of unblemished descent) is, that with the name of an unclean animal (raven) is unclean, that with the name of a clean animal (dove) is clean; <span class=\"citation\">B. Bath. 91ᵃ</span>. <span class=\"citation\">Kel. III, 7</span> <span dir=\"rtl\">ובחרסית ט׳</span> and the person that touches the clay is clean (not affected by levitical uncleanness). <span class=\"citation\">Ib. IV, 1</span> <a href=\"#\" data-headword=\"ט׳\">ט׳</a> is not subject to levitical uncleanness; a. v. fr.—<span dir=\"rtl\">דג ט׳</span>, <a href=\"#\" data-headword=\"עוּף I\">עוף</a>; <span dir=\"rtl\">בהמה טהורה</span> a fish, a bird, a domestic animal <i>permitted to eat</i>. <span class=\"citation\">Ḥull. XII, 2</span>. <span class=\"citation\">Ib. IV, 3</span> <span dir=\"rtl\">בטהורה טהור</span> if it occurs with an animal of the clean class, the person is levitically clean; a. v. fr.—Pl. <span dir=\"rtl\">טְהוֹרִים</span>, <span dir=\"rtl\">טְהוֹרִין</span>; <span dir=\"rtl\">טְהוֹרוֹת</span>. <span class=\"citation\">Kel. II, 1</span> <span dir=\"rtl\">פשוטיהן ט׳</span> the flat-surfaced among them are not subject to uncleanness.—<span class=\"citation\">Ber. 2ᵇ</span> שהכהנים ט׳ וכ׳ Ms. M. (ed. <span dir=\"rtl\">מטוהרים</span>) when the purified priests enter &amp;c. <span class=\"citation\">B. Mets. 61ᵇ</span>; a. v. fr.</div>","alt":["טְהוֹרָה"]},"10288":{"h":"טָהֵר","r":"I00101","html":"<div class=\"sense\"> [<i>to be bright, to glitter</i>,] </div><div class=\"sense\"><b>1)</b> <i>to be clean, pure</i>, esp. <i>to be levitically clean; to be unsusceptible of levitical uncleanness.</i> <span class=\"citation\">Neg. X, 8</span> <span dir=\"rtl\">שט׳ שעה אחת</span> which has been declared clean once. <span class=\"citation\">Mikv. II, 2</span> <span dir=\"rtl\">עד שיודע שט׳</span> until it is ascertained that it has become clean. <span class=\"citation\">Ib. III, 2</span> <span dir=\"rtl\">ויִטְהֲרוּ העליונים מן וכ׳</span> so that the waters coming from above become cleansed from the impurity of the lower waters. <span class=\"citation\">Neg. VII, 4</span> <span dir=\"rtl\">ויִטְהַר ממנו</span> and is declared clean from it (the last scall); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be cleared, removed</i>. <span class=\"citation\">Ber. 2ᵇ</span>, v. <a href=\"#\" data-headword=\"טְהֵר\">next w.</a></div><div class=\"sense\"><b>Pi. טִיהֵר</b> <div class=\"sense\"><b>1)</b> <i>to purify, make</i> (<i>levitically</i>) <i>clean; to absolve from sin.</i> <span class=\"citation\">Yoma VIII, 9</span> <span dir=\"rtl\">מי מְטַהֵר וכ׳</span> who is it that absolves you? Ib. (ref. to <span class=\"citation\">Jer. XVII, 13</span>) <span dir=\"rtl\">מה מקוה מט׳ וכ׳</span> as the ritual bath (v. <a href=\"#\" data-headword=\"מִקְוֶה\">מִקְוֶה</a>) cleanses the unclean, so does the Lord &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to keep clean, guard against contact with unclean things</i>. <span class=\"citation\">R. Hash. 16ᵇ</span> <span dir=\"rtl\">חייב … לטַהֵר את עצמו וכ׳</span> one is bound to keep one’s self clean for the festive days.</div><div class=\"sense\"><b>—3)</b> <i>to declare</i> <a href=\"#\" data-headword=\"טָהוֹר\">טָהוֹר</a>, <i>to decide in favor of cleanness</i>. <span class=\"citation\">Snh. 17ᵃ</span> bot. <span dir=\"rtl\">מי שיודע לטַ׳ וכ׳</span> one who knows how to prove a creeping thing to be clean. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אני אדון ואֲטַהֲרֶנוּ</span> I will argue and prove it to be clean. <span class=\"citation\">Eduy. VIII, 7</span> <span dir=\"rtl\">לטמא ולטַ׳</span> to decide on unclean and clean; a. v. fr.—<i>Part. pass</i>. <span dir=\"rtl\">מְטוֹהָר</span>, pl. <span dir=\"rtl\">מְטוֹהָרִים</span>. <span class=\"citation\">Ber. 2ᵇ</span>, v. <a href=\"#\" data-headword=\"טָהוֹר\">preced.</a></div><div class=\"sense\"><b>—4)</b> <i>to become clean</i>. <span class=\"citation\">Snh. 94ᵇ</span> <span dir=\"rtl\">מיד ט׳</span> it becomes clean at once. <span class=\"citation\">Ḥull. 60ᵇ</span> <span dir=\"rtl\">טִיהֲרוּ</span>; <span class=\"citation\">Gitt. 38ᵃ</span> <span dir=\"rtl\">טהרו</span>, v. <a href=\"#\" data-headword=\"סִיחוֹן\">סִיחוֹן</a>.</div></div><div class=\"sense\"><b>Nif. נִטְהַר</b> <div class=\"sense\"><i>to become clean</i>. Tanḥ. Metsora 7 <span dir=\"rtl\">נִטְהֲרָה וכ׳</span> she became clean on the eighth day. Ib. <span dir=\"rtl\">ונִטְהֶרֶת</span> and becomes clean; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִטָּהֵר</b> <div class=\"sense\"><i>to be cleansed, to cleanse one’s self; to amend</i>. <span class=\"citation\">Yoma 38ᵇ</span> <span dir=\"rtl\">בא לִטָּהֵר מסייעים אותו</span> (Ms. M. 2 <span dir=\"rtl\">להִטָּהֵר</span>) if one is willing to do good, he will be assisted; <span class=\"citation\">Sabb. 104ᵃ</span>; <span class=\"citation\">Yalk. Prov. 935</span> <span dir=\"rtl\">לִיטָּהֵר</span>; a. e.—<span class=\"citation\">Yoma VIII, 9</span> (<span class=\"citation\">85ᵇ</span>) <span dir=\"rtl\">לפני מי אתם מִיטַּהֲרִים</span> Mish. a. Y. ed. (Bab. ed. <a href=\"#\" data-headword=\"מַטַּטְרוֹן\">מִטַּ׳</a>) before whom do you cleanse yourselves (from sin)?; a. e.</div></div>","alt":["טָהַר"]},"10289":{"h":"טְהֵר","r":"I00102","html":"<div class=\"sense\"><b>1)</b> <i>to be clean</i> (usually <a href=\"#\" data-headword=\"דכי\">דכי</a>). <span class=\"citation\">Ber. 2ᵇ</span> <span dir=\"rtl\">וט׳ גברא</span>, v. infra.</div><div class=\"sense\"><b>—2)</b> <i>to be cleared away, be gone</i>. Ib. 2ᵃ, sq. (ref. to <span class=\"citation\">Lev. XXII, 7</span> <span dir=\"rtl\">ובא השמש וטהר</span>) <span dir=\"rtl\">ממאי דהאי … והאי וטהר ט׳ יומא דלמא … ט׳ גברא</span> how do you know that this <i>uba hash-shemesh</i> means his sunset (the finished sunset of the seventh day, v. Ms. M. in Rabb. D. S. a. l.), and <i>v’taher</i> means, the day is gone; may be <i>uba</i> &amp;c. means the approach of his evening (beginning sunset. Tosaf. a. l.; Rashi: the arrival of his (eighth) morning), and <i>v’taher</i> (referring to the man) means, the man becomes clean (by means of his sacrifice, Rashi).</div><div class=\"sense\"><b>—3)</b>  (denom. of <a href=\"#\" data-headword=\"טִיהֲרָא\">טִיהֲרָא</a>) <i>to be noon-time</i>. <span class=\"citation\">Yoma 59ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"טִיהֲרָא\">טִיהֲרָא</a> a. <a href=\"#\" data-headword=\"טֹהַר\">next w.</a></div><div class=\"sense\"><b>Pa. טַהֵר</b> <div class=\"sense\"><i>to declare clean</i>. <span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">טַהֲרִינְהוּ</span> he declared them clean.</div></div>","alt":["טְהַר"]},"10290":{"h":"טֹהַר","r":"I00103","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"טְהֵר\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>the pure, real surface</i> (of gold). <span class=\"citation\">Yoma V, 6</span> <span dir=\"rtl\">על טָהֳרוֹ של מזבח</span> (or <span dir=\"rtl\">טְהָרוֹ</span>) immediately on the top of the golden altar (free from coals or ashes, v. <a href=\"#\" data-headword=\"גִּילּוּיָיא\">גִּילּוּיָא</a>). <span class=\"citation\">Men. 97ᵃ</span> <span dir=\"rtl\">על טהרו של שולחן</span> (Ms. M. <span dir=\"rtl\">על השל׳</span>) immediately on the golden table.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"חזי\">חָזֶה</a>) <i>the centre of the front</i>. <span class=\"citation\">Yoma 59ᵃ</span> (one opinion explain. <span dir=\"rtl\">טהרו של מזבח</span>, v. supra) <span dir=\"rtl\">פלגיה דמזבח</span> the centre of the altar front, as people say, <span dir=\"rtl\">טהר טיהרא והוי פלגא דיומא</span> ‘the noon-light shines’ meaning by <i>tihara</i> the middle of the day; <span class=\"citation\">ib. 15ᵃ</span>; <span class=\"citation\">Zeb. 38ᵇ</span></div>","alt":["טְהָר"]},"10291":{"h":"טִהָר","r":"I00104","html":"<div class=\"sense\"> v. sub. <span dir=\"rtl\">טִיה׳</span>.</div>","alt":["טִהֲרָא","טִהֲרֵי","טִהֲרִירֵי","טִהַרְרֵי"]},"10292":{"h":"טָהֳרָה","r":"I00105","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> ; <a href=\"#\" data-headword=\"טִהָר\">preced.</a> wds.; <a href=\"#\" data-headword=\"טִהָר\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>clearness</i> of the sky after the rainy season. <span class=\"citation\">Ber. 59ᵃ</span> <span dir=\"rtl\">הרואה רקיע בטָהֳרָתָהּ</span> (or <span dir=\"rtl\">בטַהֲ׳</span>) he who sees the sky in its restored brightness (Ms. F. <span dir=\"rtl\">בטיהרו</span>, v. <a href=\"#\" data-headword=\"טִיהָר\">טִיהָר</a>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נראית רקיע בטהרתה</span> (Ms. M. <span dir=\"rtl\">נראו שמים בטהרה</span>; <span class=\"citation\">Yalk. Is. 335</span> <span dir=\"rtl\">נראה שמים בטִהֲרוֹ</span>, corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>pureness, condition of levitical cleanness; purification</i>. <span class=\"citation\">Sabb. 152ᵇ</span> תנה לו כמו שנתנה לך מה הוא בט׳ אף אתה בט׳ Ms. M. (v. Rabb. D. S. a. l. note) give her (the soul) to Him as He has given her to thee, as He (has given her) in pureness, so give thou &amp;c. <span class=\"citation\">Snh. 68ᵃ</span>, v. <a href=\"#\" data-headword=\"טָהוֹר\">טָהוֹר</a>.—<span class=\"citation\">Ber. 16ᵃ</span> (ref. to <span class=\"citation\">Num. XXIV, 6</span>) <span dir=\"rtl\">מה נחלים … מטומאה לט׳ וכ׳</span> as the rivers raise man from a condition of uncleanness to one of cleanness, so do the tents (schools) &amp;c. <span class=\"citation\">Ab. Zar. 8ᵃ</span> <span dir=\"rtl\">עובדי ע&quot;ז בט׳</span> encouraging idolatry, though from no impure motives. <span class=\"citation\">Yoma 72ᵇ</span>; <span class=\"citation\">Men. 110ᵃ</span> <span dir=\"rtl\">הלומד תורה בט׳</span> he who studies the Law in (sexual) purity.—Snh. l. c. <span dir=\"rtl\">וטַהֲרָתָן במה שהן</span> and their purification (immersion) is performed in whatever condition they are (whole or torn); a. v. fr.—Esp. <a href=\"#\" data-headword=\"ט׳\">ט׳</a> or <span dir=\"rtl\">טַהֲרַת הקודש</span> <i>observance of levitical rules originally prescribed for the handling of sacred food;</i> also (mostly in pl.) <i>secular food so prepared</i> or <i>pretended to be so prepared;</i> v. <a href=\"#\" data-headword=\"חָבֵר\">חָבֵר</a>.—<span class=\"citation\">Gitt. 62ᵃ</span> <span dir=\"rtl\">אין עושין חלת ע&quot;ה בט׳</span> you must not separate the priest’s share under levitical precautions for a non-observant (because it might mislead the priest); <span class=\"citation\">Tosef. Dem. III, 1</span>. <span class=\"citation\">Sabb. 13ᵃ</span> <span dir=\"rtl\">עד היכן פרצה ט׳ וכ׳</span> how far the custom of observing the rules of levitical cleanness for secular food has spread &amp;c. <span class=\"citation\">Ḥag. II, 7</span> <span dir=\"rtl\">היה אוכל על ט׳ הקודש</span> used to eat his ordinary meals with the observance required for sacred food; a. fr.—Pl. <span dir=\"rtl\">טָהֳרוֹת</span>, <span dir=\"rtl\">טַהֲרוֹת</span>. Tosef. Dem. l. c. <span dir=\"rtl\">אין עושין ט׳ לע&quot;ה</span> one must not prepare food with observance of levitical precautions for &amp;c., v. supra. <span class=\"citation\">Ber. 19ᵃ</span>; <span class=\"citation\">B. Mets. 59ᵇ</span> <span dir=\"rtl\">כל ט׳ שטיהר וכ׳</span> all objects which R. … had declared clean. <span class=\"citation\">Tosef. Dem. II, 20</span> <span dir=\"rtl\">אין משלחין ט׳ וכ׳</span> you must not send food levitically prepared through a non-observant; a. v. fr.—<i>Tohŏroth</i>, or <i>Tahăroth</i>, (euphem. for <span dir=\"rtl\">טומאות</span>), name of the sixth order of the Mishnah and Tosefta <span dir=\"rtl\">(סדר ט׳</span>), and of one treatise of that order.</div>","alt":["טַהֲרָה"]},"10293":{"h":"טְוָא","r":"I00106","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוי\">טוי</a></div>","alt":[]},"10294":{"h":"טוֹב I","r":"I00107","html":"<div class=\"sense\"> (b. h.) <i>to be good, fit, handsome, valuable</i>.</div><div class=\"sense\"><b>Hif. הֵטִיב</b> <div class=\"sense\"><b>1)</b> <i>to prepare, outfit, dress, adorn</i>. <span class=\"citation\">Gen. R. s. 26</span>, v. <a href=\"#\" data-headword=\"*טַבָּת\">טַבָּת</a>. <span class=\"citation\">Gen. R. s. 83</span> (play on <span dir=\"rtl\">מהיטבאל</span>, <span class=\"citation\">Gen. XXXVI, 39</span>) <span dir=\"rtl\">מְטִיבֵי אלוהות היו</span> they were dressers of idols; <span dir=\"rtl\">שהיו מֵטִיבִין עצמן וכ׳</span> they adorned themselves in honor of the idols. Ib. <span dir=\"rtl\">מטיבי נשים וכ׳</span> they dressed women for their wedding; a. e.—Esp. (<span dir=\"rtl\">את הנרות</span>) <a href=\"#\" data-headword=\"ה׳\">ה׳</a> <i>to trim, cleanse the lamps.</i> <span class=\"citation\">Yoma III, 4</span> <span dir=\"rtl\">ולהֵטֵיב</span>. <span class=\"citation\">Ib. I, 2</span>. <span class=\"citation\">Ib. 14ᵇ</span> <span dir=\"rtl\">יֵיטִיב</span>; a. fr.—V. <a href=\"#\" data-headword=\"הֲטָבָה\">הֲטָבָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>to turn a dream unto good</i> (saying, ‘I have dreamt a good dream’). <span class=\"citation\">Ber. 55ᵇ</span> <span dir=\"rtl\">יְטִיבֶנּוּ בפני וכ׳</span></div><div class=\"sense\"><b>—3)</b> <i>to do good, be beneficent</i>. Ib. IX, 2 <span dir=\"rtl\">הטוב והמטיב</span> who is good and beneficent. <span class=\"citation\">Taan. 31ᵃ</span> <span dir=\"rtl\">תקנו … הטוב והמ׳</span> they introduced in Jabneh the benediction ‘who is good &amp;c.’ (in the grace after meal).—<span class=\"citation\">Kidd. I, 10</span> <span dir=\"rtl\">מטיבין לו</span> good will be done to him; a. fr.—<i>Part. Hof</i>. <a href=\"#\" data-headword=\"מוּטָב\">מוּטָב</a>, q. v.</div></div><div class=\"sense\"><b>Pi. טִיֵּיב</b> <div class=\"sense\"><i>to improve a field, to till oftener than usual</i>. Y. Shebi. IV, 35ᵇ top <span dir=\"rtl\">טִיְּיבָהּ וכ׳</span></div></div><div class=\"sense\"><b>Nithpa. נִיטַּיֵּיב</b> <div class=\"sense\"><i>to be improved.</i> <span class=\"citation\">Shebi. IV, 2</span>; <span class=\"citation\">Tosef. ib. III, 10</span>; a. e.—Denom. <a href=\"#\" data-headword=\"טִיּיוּב\">טִיּיוּב</a>.</div></div>","alt":[]},"10295":{"h":"טוֹב","r":"I00108","html":"<div class=\"sense\"><i>Pa.</i> <a href=\"#\" data-headword=\"טוֹב I\">טַיֵּיב</a>, <i>Af.</i> אָטֵיב <i>to do good, to favor</i>. <span class=\"citation\">Targ. Y. I Ex. XXIII, 2</span> <span dir=\"rtl\">למְטַיְּיבָא</span>; Y. II <span dir=\"rtl\">למֵיטְבָא</span>. V. <a href=\"#\" data-headword=\"יְטַב\">יְטַב</a>.</div>","alt":["טוּב"]},"10296":{"h":"טוֹב II","r":"I00109","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>good; a good thing</i>. <span class=\"citation\">Ber. 5ᵃ</span> (ref. to <span class=\"citation\">Ps. XXXIX, 3</span>) <span dir=\"rtl\">אין ט׳ אלא וכ׳</span> under <i>good</i> the Torah is meant. Ib. 60ᵇ <span dir=\"rtl\">זו מדה ט׳</span> this refers to a good dispensation; a. v. fr.—<span dir=\"rtl\">יום טוב</span> (abbr. <span dir=\"rtl\">י&quot;ט</span>) <i>festival</i>. <span class=\"citation\">Bets. I, 1</span>; a. fr.—<span dir=\"rtl\">כי טוב</span> (ref. to <span class=\"citation\">Gen. I, 4</span>) <i>day-time</i>. <span class=\"citation\">Pes. 2ᵃ</span>.—<span class=\"citation\">Ber. V, 3</span> (<span class=\"citation\">33ᵇ</span>) <span dir=\"rtl\">על טוב וכ׳</span> thy name be praised for the good (thou doest).—<span dir=\"rtl\">זכור לַטּוֹב</span>, v. <span dir=\"rtl\">עין טובה</span>—.<a href=\"#\" data-headword=\"זָכַר\">זָכַר</a>, v. <a href=\"#\" data-headword=\"עַיִן\">עַיִן</a>.—Pl. <span dir=\"rtl\">טוֹבְים</span>, f. <span dir=\"rtl\">טוֹבוֹת</span>. Ber. l. c. (34ᵃ, omitt. in Mish.) <span dir=\"rtl\">האומר יברכוך ט׳</span> he who says in prayer, The good praise thee. Ib. IX, 2 <span dir=\"rtl\">בשורות ט׳</span>, v. <a href=\"#\" data-headword=\"בְּשׂוֹרָה\">בְּשוֹרָה</a>; a. v. fr.—V. <a href=\"#\" data-headword=\"טוֹבָה\">טוֹבָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>noble, elder</i>.—Pl. <a href=\"#\" data-headword=\"טוֹבִי\">טוֹבִים</a>. <span class=\"citation\">Tosef. Shek. II, 16</span> <span dir=\"rtl\">בני ט׳</span> of noble descent; a. fr.—טוֹבֵי העיר <i>representatives</i> of the town. <span class=\"citation\">Meg. 27ᵃ</span></div>","alt":["טוֹבָה"]},"10297":{"h":"טוּב","r":"I00110","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"טוֹב II\">preced.</a>) <i>goodness, good</i>. <span class=\"citation\">Ber. 44ᵃ</span> <span dir=\"rtl\">לשבוע מטוּבָהּ</span> to be satisfied out of its (the land’s) riches; a. e.</div>","alt":[]},"10298":{"h":"טוּבָא","r":"I00111","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <i>good, goodness, mercy</i>. <span class=\"citation\">Targ. Is. I, 19</span>. <span class=\"citation\">Targ. Ps. XXXIII, 22</span>; a. fr.—2) (mostly in pl. constr. <a href=\"#\" data-headword=\"טוֹבִי\">טוּבֵי</a>) <i>happines</i>, used like <a href=\"#\" data-headword=\"שְׁרֵי\">אַשְׁרֵי</a>, <i>happy!, blessed!</i> <span class=\"citation\">Targ. I Kings X, 8</span>. <span class=\"citation\">Targ. II Kings V, 3</span> (h. text <span dir=\"rtl\">אחלי</span>). With personal suffix <span dir=\"rtl\">טוּבוֹהִי</span>, <span dir=\"rtl\">טוּבוֹי</span>, <a href=\"#\" data-headword=\"טוֹבִיָּה\">טוּבֵיה</a>. <span class=\"citation\">Targ. Prov. XXVIII, 14</span>. <span class=\"citation\">Targ. Ps. I, 1</span>; a. fr.—<span class=\"citation\">Snh. 7ᵃ</span> v. <a href=\"#\" data-headword=\"דּוּשׁ\">דּוּשׁ</a> ch.—<span class=\"citation\">Y. Yoma IV, 41ᵈ</span> top <span dir=\"rtl\">טיבוי … טובוי</span>, v. <a href=\"#\" data-headword=\"לְוָיְיתָא\">לְוָיְיתָא</a>; a. fr.—3) <i>much; many; very</i>. <span class=\"citation\">Snh. 41ᵇ</span> <span dir=\"rtl\">ט׳ אמריתו בה</span> you said much (had many reasons to offer). <span class=\"citation\">Ber. 30ᵇ</span> <span dir=\"rtl\">מרירת ליבא ט׳</span> very bitter at heart.—<span class=\"citation\">Ib. 18ᵇ</span> <span dir=\"rtl\">אבא ט׳</span> many by the name of Abba. <span class=\"citation\">Ib. 52ᵇ</span> <span dir=\"rtl\">ט׳ נהורי</span> many lights (colors); a. fr.—Pl. fem. <span dir=\"rtl\">טוּבָן</span> <i>more</i>. <span class=\"citation\">Y. Peah I, 15ᶜ</span>; <span class=\"citation\">Y. Kidd. I, 61ᵇ</span> top <span dir=\"rtl\">פריטין ט׳</span> a higher price.</div>","alt":[]},"10299":{"h":"טוֹבָה","r":"I00112","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"טוֹב\">טוֹב</a>) </div><div class=\"sense\"><b>1)</b> <i>good, goodness</i>. <span class=\"citation\">Y. Shek. I, beg. 45ᵈ</span> <span dir=\"rtl\">לט׳ כל נדיב לב</span> for a good purpose—every liberal-hearted &amp;c. <span class=\"citation\">Sot. 47ᵇ</span> <span dir=\"rtl\">ופסקה ט׳</span> and blessing (plenty) has departed. <span class=\"citation\">Yeb. 47ᵃ</span>, sq. <span dir=\"rtl\">אינם … לא רוב ט׳ וכ׳</span> they cannot stand either too much prosperity or &amp;c.; a. fr.—Pl. <span dir=\"rtl\">טוֹבוֹת</span>. <span class=\"citation\">Kidd. 40ᵇ</span> <span dir=\"rtl\">ט׳ הרבה</span> the effect of many good deeds; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>favor</i>. <span class=\"citation\">Sot. 47ᵇ</span> <span dir=\"rtl\">משרבו מקבלני טוֹבָתְךָ ומחזקני טוֹבוֹתֶיךָ</span> (read: <span dir=\"rtl\">ומחזיקני</span>) when those became numerous who say, ‘I accept thy favor’ and ‘I shall appreciate thy favors’ (in official life); <span class=\"citation\">Tosef. ib. XIV, 7</span> <span dir=\"rtl\">טוֹבֹתֶיךָ ומחזיקני טוֹבָתְךָ …</span>; a. fr.—בַּטּ׳ <i>as a favor</i>, i.e. <i>expected to be reciprocated</i>, <span dir=\"rtl\">שלא בט׳</span> <i>not expected</i> &amp;c. <span class=\"citation\">Shebi. IV, 1</span>; <span class=\"citation\">2</span>; a. e.—<span dir=\"rtl\">טוֹבַת הֲנָאָה</span> the benefit of a pleasure, i.e. <i>the satisfaction which one feels in obliging somebody</i>. <span class=\"citation\">Pes. 46ᵇ</span>, a. e. <span dir=\"rtl\">ט׳ ה׳ ממון</span> the benefit of putting a person under obligation is equal to a consideration in money; a. fr.—4) <i>inclination, good will</i>. <span class=\"citation\">Gen. R. s. 86</span> <span dir=\"rtl\">בעל כרחה שלא בטוֹבָתָהּ</span> by force, against her will; Tanḥ. Vayesh. 4. <span class=\"citation\">Y. Ab. Zar. I, 40ᵃ</span> bot <span dir=\"rtl\">הביט בה שלא בטובתו</span> he looked at her involuntarily; a. fr.—<span dir=\"rtl\">טוֹבַת עַיִן</span> (v. <a href=\"#\" data-headword=\"עַיִן\">עַיִן</a>) <i>liberality</i>. <span class=\"citation\">Ned. 38ᵃ</span> <span dir=\"rtl\">נהג בה ט׳ ע׳ וכ׳</span> was liberal with the Law (that had been given to him), and he gave it to Israel.</div>","alt":[]},"10300":{"h":"טוֹבִי","r":"I00113","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טוֹבִיָּה\">next w.</a>) pr. n. m. <i>Tobi</i>. <span class=\"citation\">M. Kat. 16ᵃ</span> <span dir=\"rtl\">רב ט׳ בר מתנה</span>.</div>","alt":[]},"10301":{"h":"טוֹבִיָּה","r":"I00114","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Tobijah, Tobias</i>. <span class=\"citation\">Kidd. 70ᵇ</span> <span dir=\"rtl\">בטי בר ט׳</span>, a slave. <span class=\"citation\">Keth. 85ᵇ</span> <span dir=\"rtl\">שני ט׳</span> two by the name of T.—<span class=\"citation\">Pes. 113ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"זִיגָּד\">זִיגָּד</a>.—<span class=\"citation\">Lev. R. s. 1</span>, beg.; <span class=\"citation\">Sot. 12ᵃ</span> (one of the names of Moses).</div>","alt":[]},"10302":{"h":"טוֹבְיָנָא","r":"I00115","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוֹבַנְיָא\">טוֹבַנְיָא</a></div>","alt":[]},"10303":{"h":"טוֹבִינָא","r":"I00116","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טוּבָא\">טוּבָא</a>) <i>happy, blessed</i>. <span class=\"citation\">Gitt. 26ᵇ</span>; <span class=\"citation\">Keth. 40ᵃ</span>; <span class=\"citation\">Kerith. 13ᵇ</span> <span dir=\"rtl\">ט׳ דחכימי</span> happiest of all scholars.</div>","alt":[]},"10304":{"h":"טובלא","r":"I00117","html":"<div class=\"sense\">, <span class=\"citation\">Bets. 13ᵃ</span>, read: <a href=\"#\" data-headword=\"טִבְלָא\">טִבְלָא</a>.</div>","alt":[]},"10305":{"h":"טוֹבְלָן","r":"I00118","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טָבַל I) <i>bather</i>.—Pl. <span dir=\"rtl\">טוֹבְלָנִים</span>, constr. <span dir=\"rtl\">טוֹבְלָנֵי</span>. <span class=\"citation\">Tosef. Yad. I, 20</span> Var., v. <a href=\"#\" data-headword=\"טָבַל I\"><span dir=\"rtl\">טָבל</span> I</a>.</div>","alt":[]},"10306":{"h":"טוֹבַנְיָא","r":"I00119","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Tobanya</i> (<i>Tobyana</i>). <span class=\"citation\">Tosef. Shebi. VII, 14</span> <span class=\"citation\">Pes. 53ᵃ</span>; <span class=\"citation\">Erub. 28ᵇ</span> <span dir=\"rtl\">טובי׳</span>.</div>","alt":["(טוֹבְיָנָא)"]},"10307":{"h":"טוֹבְעִין","r":"I00120","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טָבַע I\">טֶבֵע</a> 2.</div>","alt":[]},"10308":{"h":"טוֹבְעָנָא","r":"I00121","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טְבַע I) <i>flood</i>. <span class=\"citation\">Targ. Y. Gen. VI, 17</span>; a. fr. (O. <a href=\"#\" data-headword=\"טוֹפָנָא\">טוֹפָנָ א</a>).</div>","alt":[]},"10309":{"h":"טוֹבְעָנִי I","r":"I00122","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טוֹבְעָנָא\">preced.</a>) <i>land submerged by a flood</i>. <span class=\"citation\">Taan. 10ᵃ</span> <span dir=\"rtl\">ט׳ ולא יובשני</span> better flooded land than rainless land.</div>","alt":[]},"10310":{"h":"טוֹבְעָנִי II","r":"I00123","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"טִבְעוֹנִי\">טִבְעוֹנִי</a>.</div>","alt":[]},"10311":{"h":"טוּבְתָא","r":"I00124","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>blessing</i>. <span class=\"citation\">Targ. Y. I Deut. XXXII, 50</span>. [<span class=\"citation\">Targ. Jud. V, 26</span> some ed., read <a href=\"#\" data-headword=\"טַבְתָא\">טַבְתָא</a>.]</div>","alt":[]},"10312":{"h":"*טוֹגָא","r":"I00125","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<i>toga</i>) <i>toga, Roman gown</i>. <span class=\"citation\">Sifré Deut. 234</span> <span dir=\"rtl\">פרט ליגא</span>; <span class=\"citation\">Yalk. Deut. 933</span> <a href=\"#\" data-headword=\"ליגא\">ליגא</a>; Treat. Tsitsith (ed. Kirchheim p. 22) <span dir=\"rtl\">הטריגון</span> (corr. acc.).—Pl. <span dir=\"rtl\">טוֹגִיּוֹת</span>. Sifré l. c. quot. in Ar., s. v. <span dir=\"rtl\">טג</span>: <span dir=\"rtl\">טגיות אינן וֹכ׳</span> (read: <span dir=\"rtl\">טוג׳</span>) <i>togae</i> are exempt from <i>tsitsith</i></div>","alt":[]},"10313":{"h":"טוֹהַר","r":"I00126","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טֹהַר\">טֹהַר</a></div>","alt":[]},"10314":{"h":"טְוָוא","r":"I00127","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוי\">טוי</a></div>","alt":["טָוָוה"]},"10315":{"h":"טַוְוזָא","r":"I00128","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַפְזָא\">טַפְזָא</a> (a. <a href=\"#\" data-headword=\"*טַוְוזִיג\">next w.</a>)</div>","alt":[]},"10316":{"h":"*טַוְוזִיג","r":"I00129","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">טַב זִיג</span>, v. <a href=\"#\" data-headword=\"זוֹגָא\">זוֹגָא</a>) <i>merry company, picnic of young men</i>. <span class=\"citation\">Ab. Zar. 14ᵃ</span> <span dir=\"rtl\">בט׳</span> (Ms. M. <span dir=\"rtl\">בטווזא</span>) ‘the son’s feast’ of which R. Judah speaks (<span class=\"citation\">Tosef. ib. I, 21</span>) means a picnic (not a wedding). [Perles Et. St. p. 11 refers to Pers. <i>ṭ</i><i>ûz</i><i>͗</i><i>i.ṭuśi</i>, Arab. <span dir=\"rtl\">תוזיע̇</span>.]</div>","alt":["טַּוְזִ׳"]},"10317":{"h":"טְוָוח","r":"I00130","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טוּחַ II) <i>pressing the bow, shot, shooting distance</i>.—Pl. <span dir=\"rtl\">טְוָוחִים</span>, <span dir=\"rtl\">טְיָחִ׳</span>. <span class=\"citation\">Gen. R. s. 53</span> (ref. to <span dir=\"rtl\">כמטחוי</span>, <span class=\"citation\">Gen. XXI, 16</span>) <span dir=\"rtl\">שני ט׳ בקשת מיל</span> (‘Rashi’ a. l. <span dir=\"rtl\">טִיחוֹת</span>) two shooting distances with the bow are a mile <a href=\"#\" data-headword=\"מִיל\">(מִיל</a>); <span class=\"citation\">Yalk. Gen. 94</span>.</div>","alt":["טְוָח"]},"10318":{"h":"טָווּי","r":"I00131","html":"<div class=\"sense\">, part. pass. of <a href=\"#\" data-headword=\"טוי\">טָוָה</a>.</div>","alt":[]},"10319":{"h":"טְוָוי","r":"I00132","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">טוי׳</span>.</div>","alt":["טַוְויָא","טַוְויָה"]},"10320":{"h":"טַוָּוס","r":"I00133","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טוּס\">טוּס</a>; cmp. ταώς, Pers. tavus, v. Lydd. Gr. Dict. s. v.) <i>peacock</i>. <span class=\"citation\">Gen. R. s. 7</span>, end. <span class=\"citation\">Tosef. Kil. I, 8</span> תרנגול ט׳ וכ׳ Var. (ed. Zuck. <a href=\"#\" data-headword=\"טוות\">טוות</a>, corr. acc.) the cock, the peacock and the pheasant, although resembling each other, &amp;c.; Y. ib. I, 27ᵃ bot.; <span class=\"citation\">B. Kam. 55ᵃ</span> (Ms. H. <span dir=\"rtl\">טָאוָס</span>); Y. ib. V, end, 5ᵃ <span dir=\"rtl\">טַוֶּוסֶת</span>(?).—Pl. <span dir=\"rtl\">טַוָּוסִים</span>, <span dir=\"rtl\">טַוָּוסִין</span>. Pesik. R. addit. s. 1 (ed. Fr. p. 193ᵇ). Yalk. Esth. 104ᵇ <span dir=\"rtl\">ט׳ של שן</span> peacocks made of ivory.</div>","alt":[]},"10321":{"h":"טַוָּוסָא","r":"I00134","html":"<div class=\"sense\"> Targ. II Esth. I, 2.—<span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> top (expl. Adrammelech and Anammelech, <span class=\"citation\">II Kings XVII, 31</span>) <span dir=\"rtl\">ט׳ וכ׳</span> peacock and pheasant. <span class=\"citation\">Sabb. 130ᵃ</span> רישא דט׳ וכ׳ Ms. M. (Ms. O. <span dir=\"rtl\">טָאוָסָא</span>, ed. incorr. <a href=\"#\" data-headword=\"טוות\">טוותא</a>) the head of a peacock cooked in milk.—Pl. <span dir=\"rtl\">טַוָּוסִין</span>, <span dir=\"rtl\">טַוְוסִין</span>, <span dir=\"rtl\">טַוְסִ׳</span>. <span class=\"citation\">Targ. Ez. XXVII, 15</span> (h. text <span dir=\"rtl\">הובנים</span>). <span class=\"citation\">Targ. I Kings X, 22</span> (h. text <span dir=\"rtl\">תכיים</span>).</div>","alt":["טַוְוסָא"]},"10322":{"h":"טַוְופָא","r":"I00135","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טְיָפָא\">טְיָפָא</a></div>","alt":[]},"10323":{"h":"טַוַּור","r":"I00136","html":"<div class=\"sense\">, v. <span dir=\"rtl\">טיְּרָא</span></div>","alt":["טַוְּורָא"]},"10324":{"h":"טַוְורוֹס","r":"I00137","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (Ταῦρος) <i>Taurus Amanus</i> (v. <a href=\"#\" data-headword=\"אֲמָנָה II\"><span dir=\"rtl\">אֲמָנָה</span> II</a>, </div><div class=\"sense\"><b>2)</b>  corresp. to <i>Hor-Hahar</i>. <span class=\"citation\">Targ. Y. Num. XXXIV, 7</span>, sq. (O. <span dir=\"rtl\">הר טורא</span>).—<span class=\"citation\">Targ. Y. ib. XX, 22</span>; <span class=\"citation\">25</span>; <span class=\"citation\">Targ. Y. I Deut. XXXII, 50</span> (!) (Y. II a. O. <span dir=\"rtl\">הור טורא</span>).</div>","alt":["ט׳ אוּמָנוֹס","(אוּמָנִיס","מָנוֹס)"]},"10325":{"h":"טְוָות","r":"I00138","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (stem <span dir=\"rtl\">טה</span>, <span dir=\"rtl\">טו</span>, cmp. <span dir=\"rtl\">טהר</span>; cmp. Arab.<i>ṭavi</i>) [<i>clearness, emptiness</i>,] (adv.) <i>with an empty stomach, without meal, fasting.</i> <span class=\"citation\">Dan. VI, 19</span>.—<span class=\"citation\">Pes. 107ᵃ</span>, v. <a href=\"#\" data-headword=\"בִּית\">בִּית</a>—<span class=\"citation\">Ber. 55ᵃ</span> כל חלום בלא ט׳ Ms. M. (ed. <a href=\"#\" data-headword=\"וָלָא\">ולא</a>) no dream is to be feared in which fasting plays no part; [Ar.: every dream has some reality, except that which one dreams while fasting].</div>","alt":["טְוָת"]},"10326":{"h":"טוות","r":"I00139","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַוָּוס\">טַוָּוס</a>, <a href=\"#\" data-headword=\"טַוָּוסָא\"><a href=\"#\" data-headword=\"טַוָּוסָא\">טַוָּוסָא</a>.</a></div>","alt":["טוותא"]},"10327":{"h":"טוּחַ I","r":"I00140","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to cover with a cohesive substance, to plaster</i>. Part. <span dir=\"rtl\">טָח</span>. <span class=\"citation\">M. Kat. 7ᵃ</span> <span dir=\"rtl\">ואינו טָח בטיט</span> but puts no clay on. <span class=\"citation\">Cant. R. to VIII, 6</span> <span dir=\"rtl\">טָחֵי גגות</span> roof-plasterers. <span class=\"citation\">Neg. XIII, 1</span> <span dir=\"rtl\">וטח</span> and plasters the spot over; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"טוּחַ\">טוּחַ</a> <i>coated, covered with viscid or glittering matter</i>.—<span class=\"citation\">Midd. IV, 1</span> <span dir=\"rtl\">ט׳ בזהב</span> coated with gold; (<span class=\"citation\">Num. R. s. 12</span> <a href=\"#\" data-headword=\"טוּחַ I\">נִטּוֹחַ</a>).—<span class=\"citation\">Nidd. 24ᵃ</span> <span dir=\"rtl\">בפניו טוּחוֹת</span> (Rashi <span dir=\"rtl\">טָחוֹת</span>) when the face of the embryo is covered over (no features distinguishable).</div><div class=\"sense\"><b>Nif. נִיטּוֹחַ</b> <div class=\"sense\"><i>to be pasted on, to stick</i>. Y. Kil. VI, 30ᶜ top <span dir=\"rtl\">והיא נִיטּוֹחָה</span> and it (the fig) stuck (against the wall); Y. Sabb. XI, 13ᵃ bot. <span dir=\"rtl\">והיה נ׳</span> (corr. acc.). <span class=\"citation\">Tosef. Kel. B. Mets. II, 17</span> <span dir=\"rtl\">לִיטּוֹחַ</span> some ed. (ed. Zuck. <span dir=\"rtl\">ליטול</span>, corr. acc.), v. infra.</div></div><div class=\"sense\"><b>Hif. הֵטִיחַ</b> <div class=\"sense\"><b>1)</b> <i>to plaster, to polish</i>. <span class=\"citation\">Ḥull. 25ᵃ</span> … <span dir=\"rtl\">עתיד</span> (<span dir=\"rtl\">לַהֲטִיחוֹ</span>) <span dir=\"rtl\">להָטִיחַ וכ׳</span> (Tosef. Kel. l. c. <span dir=\"rtl\">ליטוח</span>, v. supra) which wants polishing, v. <a href=\"#\" data-headword=\"אֲטוּנָס\">אֲטוּנָס</a>. <span class=\"citation\">Bets. 9ᵃ</span> <span dir=\"rtl\">להָטִיחַ גגו וכ׳</span> he needs the ladder for plastering his roof. [<span class=\"citation\">Tosef. Kel. B. Kam. IV, 19</span>, sq. [read:] <span dir=\"rtl\">אם יכול הטיח</span>, v. <a href=\"#\" data-headword=\"טִיחַ\">טִיחַ</a>.]</div><div class=\"sense\"><b>—2)</b> <i>to cast mud</i>, trnsf. (with or without <span dir=\"rtl\">דברים</span>) <i>to speak rebelliously, to reproach</i> (with <a href=\"#\" data-headword=\"אִינְגַּד\">נגד</a> or <a href=\"#\" data-headword=\"כְּלַפֵּי\">כלפי</a>). <span class=\"citation\">Taan. 25ᵃ</span>; <span class=\"citation\">Meg. 22ᵇ</span>, a. e. <span dir=\"rtl\">לעולם אל יָטִיחַ וכ׳</span> one must, in his prayer, never reproach the Lord. <span class=\"citation\">Ber. 31ᵇ</span>, sq.—<span class=\"citation\">Gen. R. s. 53</span> (ref. to <span dir=\"rtl\">כמטחוי</span>, <span class=\"citation\">Gen. XXI, 16</span>) <span dir=\"rtl\">כמֵטַחַת וכ׳</span> as if thrusting reproaches against the Lord; Tanḥ. Vayetse 5. <span class=\"citation\">Ex. R. s. 3</span>. <span class=\"citation\">B. Bath. 134ᵃ</span> ה׳ עלי וכ׳ Ben U. insulted me.</div></div>","alt":[]},"10328":{"h":"טוּחַ","r":"I00141","html":"<div class=\"sense\">, <i>to plaster, smear</i>. <span class=\"citation\">Pes. 30ᵃ</span>, v. <a href=\"#\" data-headword=\"טִיחְיָא\">טִיחְיָא</a>.</div><div class=\"sense\"><b>Af. אֲטַח</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"טוּחַ I\">same</a>. <span class=\"citation\">Zeb. 95ᵇ</span> <span dir=\"rtl\">אַטְחוּ</span> (Ms. R. 2 <span dir=\"rtl\">דטחו</span>), v. <a href=\"#\" data-headword=\"טִיחְיָא\">טִיחְיָא</a>.</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">מִלִּין</span>) <i>to talk rebelliously</i>. <span class=\"citation\">Targ. Y. Gen. XV, 6</span>.</div></div>","alt":[]},"10329":{"h":"טוּחַ II","r":"I00142","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טְחִי\">טחי</a>) <i>to press, squeeze</i>. <span class=\"citation\">Ḥull. 109ᵇ</span> <span dir=\"rtl\">טָחוֹ בכותל</span> presses it against the wall (to make the milk flow out).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"טוּחַ\">טוּחַ</a> <i>squeezed in</i>. <span class=\"citation\">Num. R. s. 10</span> (ref. to <span class=\"citation\">Job XXXVIII, 36</span>) <span dir=\"rtl\">אלו הכליות שהן טוּחוֹת וכ׳</span> that means the kidneys which are wedged into the body.</div><div class=\"sense\"><b>Hif. הֵטִיחַ</b> <div class=\"sense\"><b>1)</b> <i>to press, squeeze, knock against</i>. <span class=\"citation\">Ber. 34ᵇ</span> <span dir=\"rtl\">אלמלי ה׳ וכ׳</span> (Ms. M. <a href=\"#\" data-headword=\"נוּחַ\">הניח</a>, v. Rabb. D. S. a. l. note) if Ben. Z. (myself) had squeezed his head between his (the son’s) knees (praying for his recovery). <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">התחיל מֵטִיחַ וכ׳</span> he knocked his head against the wall; <span class=\"citation\">Yalk. ib. 30</span> <span dir=\"rtl\">להָטִיחַ</span>. Ohol. XVII, 2 <span dir=\"rtl\">ה׳ בסלע</span> struck (with the plough) against a rock. <span class=\"citation\">B. Kam. 28ᵇ</span> <span dir=\"rtl\">ה׳ צלוחיתו וכ׳</span> he struck (with) his bottle against the stone; Y. ib. III, 3ᶜ top, v. <a href=\"#\" data-headword=\"הֲטָחָה\">הֲטָחָה</a>.—Tanḥ. P’kudé 11 <span dir=\"rtl\">כיון שהֵטִיחוּ פניהם וכ׳</span> when they had squeezed their faces from all sides (had in vain tried in all directions).</div><div class=\"sense\"><b>—2)</b> <i>to press the bow-string, to shoot;</i> (euphem.) <i>to emit semen virile</i>. <span class=\"citation\">Yeb. 54ᵃ</span>. <span class=\"citation\">Snh. 46ᵃ</span> ה׳ באשתו Ms. M. (ed. <span dir=\"rtl\">את אשתו</span>).</div></div>","alt":[]},"10330":{"h":"טוֹחֵן","r":"I00143","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טָחַן\">טָחַן</a>) <i>miller</i>.—Pl. <span dir=\"rtl\">טוֹחֲנִים</span>. Tanḥ. <span class=\"citation\">Mishp. 19</span> <span dir=\"rtl\">כגון חמורים של ט׳</span> like the mask over the faces of the millers’ asses.</div>","alt":[]},"10331":{"h":"טוֹחֲנוֹת","r":"I00144","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טוֹחֵן\">preced.</a>) <i>millstones</i>, v. <a href=\"#\" data-headword=\"טַחֲנָה\">טַחֲנָה</a>.</div>","alt":[]},"10332":{"h":"טוֹט","r":"I00145","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (onomatop.) <i>blow on the horn</i>. <span class=\"citation\">M. Kat. 16ᵃ</span> <span dir=\"rtl\">ט׳ אסר וכ׳</span> a blow binds (proclaiming excommunication), and a blow unbinds.</div>","alt":[]},"10333":{"h":"טוֹטַלְוָותָא","r":"I00146","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">טלטל׳</span>; <a href=\"#\" data-headword=\"טְלַל I\">טְלַל</a>) <i>branches of the vine, arbor</i>. <span class=\"citation\">Targ. Y. Lev. XIX, 10</span>; <span class=\"citation\">Targ. Y. II, Deut. XXIV, 21</span> <span dir=\"rtl\">טוֹטְלָוַותְ׳</span>.</div>","alt":[]},"10334":{"h":"טוֹטְפָא","r":"I00147","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוֹטֶפְתָּא\">טוֹטֶפְתָּא</a></div>","alt":["טוֹטְפָן"]},"10335":{"h":"טוֹטַפְרָאוֹת","r":"I00148","html":"<div class=\"sense\">, v. <span dir=\"rtl\">טֹטַפְרָ׳</span></div>","alt":[]},"10336":{"h":"טוֹטָפֶת","r":"I00149","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> in pl.; = <span dir=\"rtl\">טפטפ׳</span>, v. <a href=\"#\" data-headword=\"טִיפְטֵף\">טִיפְטֵף</a></div><div class=\"sense\"><b>2)</b>  [<i>something glistening</i>,] <i>beads</i> used as <i>charms, ornament</i> worn on the forehead, <i>frontlet</i>. <span class=\"citation\">Sabb. VI, 1</span>, expl. <span class=\"citation\">ib. 57ᵇ</span>, v. <a href=\"#\" data-headword=\"חוּמַרְתָּא\">חוּמַרְתָּא</a> a. <a href=\"#\" data-headword=\"*אֲפוּזְיָינֵי\">אֲפוּזְיָינֵי</a>; Y. ib. VI, 7ᵈ <span dir=\"rtl\">דבר שהוא נותן במקום הט׳</span> (read <span dir=\"rtl\">נָתוּן</span>) something which is put on by women in the place of the <i>totafoth</i> (by men, v. infra).—Pl. <span dir=\"rtl\">טוֹטָפוֹת</span>. <span class=\"citation\">Tosef. ib. IV</span> (<span class=\"citation\">V), 6</span>.—Esp. pl. <span dir=\"rtl\">טוֹטָפוֹת</span> <i>phylacteries</i>, (corresp. to <a href=\"#\" data-headword=\"אוֹת I\">אות</a>, <span class=\"citation\">Deut. VI, 8</span>, a. e.) slips of parchment containing inscriptions and put in the casings of the T’fillin (v. <a href=\"#\" data-headword=\"תְּפִלִּין\">תְּפִלִּין</a>). Mekh. Bo. s. 17 <span dir=\"rtl\">מה בראש ארבע ט׳ אף ביד ארבע ט׳</span> as the T’fillin on the head contain four inscriptions, so those on the hand. <span class=\"citation\">Snh. XI, 3</span> (<span class=\"citation\">88ᵇ</span>); a. e.</div>","alt":[]},"10337":{"h":"טוֹטֶפְתָּא","r":"I00150","html":"<div class=\"sense\">, <i>charm, ornament</i>. <span class=\"citation\">Targ. II Sam. I, 10</span> ט׳ דעל ידא <i>bracelet</i> (h. text <a href=\"#\" data-headword=\"אֶצְעָדָה\">אצעדה</a>).—Pl. <a href=\"#\" data-headword=\"טוֹטֶפְתָּא\">טוֹטְפָתָא</a>, <a href=\"#\" data-headword=\"טוֹטְפָא\">טוֹטְפָן</a> <i>phylacteries</i>, v. <a href=\"#\" data-headword=\"טוֹטָפֶת\">preced.</a> <span class=\"citation\">Targ. Esth. VIII, 15</span> (cmp. <span class=\"citation\">Men. 35ᵇ</span>). <span class=\"citation\">Targ. Ez. XXIV, 17</span>; <span class=\"citation\">23</span> (h. text <span dir=\"rtl\">פאר</span>, cmp. <span class=\"citation\">M. Kat. 15ᵃ</span>; <span class=\"citation\">Keth. 6ᵇ</span>).</div>","alt":[]},"10338":{"h":"טוטרפליות","r":"I00151","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טִיטְרַפְלִיּוֹת\">טִיטְרַפְלִיּוֹת</a></div>","alt":[]},"10339":{"h":"טוי","r":"I00152","html":"<div class=\"sense\"> (b. h.) [<i>to go to and back</i>, cmp. <a href=\"#\" data-headword=\"זוּל\">זוּל</a>, <a href=\"#\" data-headword=\"אֲזַל I\">אֲזַל</a>,] <i>to spin</i>. <span class=\"citation\">Keth. VII, 6</span> <span dir=\"rtl\">טווָֹה בשוק</span> she spins in the street. <span class=\"citation\">Ib. 72ᵇ</span>, v. <a href=\"#\" data-headword=\"וֶרֶד II\"><span dir=\"rtl\">וֶרֶד</span> II</a>.—<span class=\"citation\">Tosef. Toh. IV, 11</span>; <span class=\"citation\">Zeb. 79ᵇ</span> <span dir=\"rtl\">פשתן שטְוָואֲתוֹ וכ׳</span> linen which a menstruant spun.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"טָווּי\">טָווּי</a>. <span class=\"citation\">Kil. IX, 8</span> <span dir=\"rtl\">ט׳ או ארוג</span> spun or woven, v. <a href=\"#\" data-headword=\"שַׁעַטְנֵז\">שַׁעַטְנֵז</a>. <span class=\"citation\">Sabb. 79ᵃ</span>; a. e.—V. <a href=\"#\" data-headword=\"טֳוִי\">טֳוִי</a>.</div>","alt":["טָוָה","טָוָוה"]},"10340":{"h":"טְוִי I","r":"I00153","html":"<div class=\"sense\">Denom. <a href=\"#\" data-headword=\"מַטְוֵויאֲתָא\">מַטְוִויאֲתָא</a>.</div>","alt":[]},"10341":{"h":"טְוִי II","r":"I00154","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טְוִי I\">preced.</a> wds.) [<i>to turn</i>,] <i>to roast</i>. <span class=\"citation\">Targ. Is. XLIV, 16</span> (ed. Wil. <a href=\"#\" data-headword=\"טוי\">טְוָה</a>); a. fr.—Part. pass. <a href=\"#\" data-headword=\"טְוִי I\">טָוֵי</a>, constr. <a href=\"#\" data-headword=\"טְוִי I\">טְוֵי</a>. <span class=\"citation\">Targ. Ex. XII, 8</span>, sq.—<span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">נִיטַוְויֵיה וכ׳</span> let him roast it in a smithy; a. fr.</div><div class=\"sense\"><b>Af. אַטְוֵי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"טְוִי I\">same</a>. <span class=\"citation\">Bets. 4ᵃ</span> <span dir=\"rtl\">מהו לאַטְוִוינְהוּ וכ׳</span></div></div><div class=\"sense\"><b>Ithpe. אִיטְּוִי</b> <div class=\"sense\"><i>to be roasted</i>. <span class=\"citation\">Pes. 76ᵇ</span> <span dir=\"rtl\">דאִיטְּוָוא וכ׳</span> which was roasted together with meat. <span class=\"citation\">B. Kam. 19ᵇ</span> <span dir=\"rtl\">דמִטְּוֵוי</span> (Ar. <span dir=\"rtl\">בטָוִוי</span>) it means that it was roasted. <span class=\"citation\">Ber. 44ᵇ</span> <span dir=\"rtl\">משיתא מִטְּוָויָתָא</span> than six (eggs) roasted.</div></div>","alt":["טְוָא"]},"10342":{"h":"טֳוִי","r":"I00155","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טוי\">טָוָה</a>) <i>spinning, that which is spun</i>. <span class=\"citation\">Meg. 26ᵇ</span>; <span class=\"citation\">Snh. 48ᵃ</span>, v. <a href=\"#\" data-headword=\"אָרִיג\">אָרִיג</a>. <span class=\"citation\">Tosef. B. Kam. X, 2</span> <a href=\"#\" data-headword=\"טאוי\">טאוי</a> (read <a href=\"#\" data-headword=\"טְוָא\">טְוָאי</a>, Var. <a href=\"#\" data-headword=\"טְוָוי\">טְוָוי</a>).</div>","alt":["טְוָי","טְוָוי"]},"10343":{"h":"טָוִי","r":"I00156","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טְוִי II) <i>roast, roasted meat.</i> <span class=\"citation\">B. Kam. 19ᵃ</span> Ar. (v. <a href=\"#\" data-headword=\"טְוִי II\"><span dir=\"rtl\">טְוִי</span> II</a>).—<span class=\"citation\">Sabb. 109ᵃ</span> <span dir=\"rtl\">שריקא ט׳</span> a roast glaired, Rashi (differ. in Tosaf.) Y. Ter. X, 47ᵇ top <a href=\"#\" data-headword=\"טְוָוי\">טַוְויָה</a>.</div>","alt":["טָיִוי","טַוְיָא","טַוְו׳"]},"10344":{"h":"*טָוַיָּא","r":"I00157","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְוִי I\">טְוִי</a>) <i>spinning animals, spiders</i>. <span class=\"citation\">Lev. R. s. 25</span> (expl. <span dir=\"rtl\">בטחות</span>, <span class=\"citation\">Job XXXVIII, 36</span>) <span dir=\"rtl\">בט׳</span> (Ar. <span dir=\"rtl\">בטיטויא</span>; cmp. LXX Job. l. c.); v., however, <a href=\"#\" data-headword=\"*בִּטְוַיָּא\">בִּטְוַיָּא</a>.</div>","alt":[]},"10345":{"h":"טְוִיָּיה טְוִיָּה","r":"I00158","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טוי\">טָוָה</a>) <i>spinning</i>. <span class=\"citation\">Sabb. 74ᵇ</span>. <span class=\"citation\">Ib. 79ᵃ</span>; a. fr.</div>","alt":["טְוִויָּה"]},"10346":{"h":"טַוְיָה","r":"I00159","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טָוִי\">טַוְיָא</a></div>","alt":[]},"10347":{"h":"טויסין","r":"I00160","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*טִיוְסִין\">טיוסין</a></div>","alt":[]},"10348":{"h":"טוֹל","r":"I00161","html":"<div class=\"sense\">, imperat. of <a href=\"#\" data-headword=\"נָטַל\">נָטַל</a>, <a href=\"#\" data-headword=\"נְטַל\">נְטַל</a>.</div>","alt":["טוּל"]},"10349":{"h":"טוּל I","r":"I00162","html":"<div class=\"sense\"><i>Pi</i>. <a href=\"#\" data-headword=\"טִיֵּיל\">טִיֵּיל</a> </div><div class=\"sense\"><b>1)</b> <i>to walk about, to be at leisure, to enjoy one’s self</i>. <span class=\"citation\">Snh. 102ᵃ</span> <span dir=\"rtl\">נְטַיֵּיל בג&quot;ע</span> we shall walk about in paradise. <span class=\"citation\">Succ. 28ᵇ</span> <span dir=\"rtl\">ומְטַיֵּיל בסוכה</span> and enjoys himself &amp;c. <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 18</span>; <span class=\"citation\">Tosef. Bets. II, 10</span>, v. <a href=\"#\" data-headword=\"טְרִיקְלִין\">טְרִיקְלִין</a>. Tanḥ. Ki Thissa 3; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to make walk</i>. Ib. <span dir=\"rtl\">טִיַּילְתַּנִי עמך</span> thou madest me walk by thy side.</div>","alt":[]},"10350":{"h":"טוּל","r":"I00163","html":"<div class=\"sense\">, <i>to walk about, stride</i>. <span class=\"citation\">Targ. Jer. L, 11</span> (h. text <span dir=\"rtl\">צהל</span>; cmp. Targ. ib. VIII, 16).</div><div class=\"sense\"><b>Pa. טַיֵּיל</b> <div class=\"sense\"><b>1)</b> <i>to walk, travel</i>. <span class=\"citation\">Targ. Y. Gen. XXIV, 61</span>. <span class=\"citation\">Targ. Y. Num. XXII, 20</span>. <span class=\"citation\">Targ. Ps. LXVIII, 8</span> <a href=\"#\" data-headword=\"טַיַּיעְתָּא\">טַיַּילְתָּא</a> (ed. Wil. <span dir=\"rtl\">טְיַלְ׳</span>; h. text <span dir=\"rtl\">צעד</span>); a. fr.</div><div class=\"sense\"><b>—2)</b>  as <a href=\"#\" data-headword=\"טוּל I\">preced.</a> <i>Pi.</i>—<span class=\"citation\">Targ. Y. Gen. III, 8</span> (h. text <span dir=\"rtl\">מתהלך</span>).—Y. Ber. III, 6ᵃ, a. fr. <span dir=\"rtl\">הוו מְטַיְּילִין וכ׳</span> were walking about &amp;c. <span class=\"citation\">B. Bath. 91ᵇ</span> <span dir=\"rtl\">כד הוו מְטַיְּילָן וכ׳</span> when boys and girls used to play &amp;c. <span class=\"citation\">Succ. 53ᵃ</span> <span dir=\"rtl\">הוה מט׳ קמיה וכ׳</span> (Ar. <span dir=\"rtl\">מטלל</span>) was sporting before &amp;c., v. <a href=\"#\" data-headword=\"טְלַל I\">טְלַל</a>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to drive off, send away</i>. <span class=\"citation\">Targ. Y. Deut. XXIV, 1</span>; <span class=\"citation\">3</span> (ed. pr. <span dir=\"rtl\">ישיל</span>, corr. acc.).</div></div><div class=\"sense\"><b>Af. אָטֵיל</b> <div class=\"sense\"><i>to cause to travel</i>. <span class=\"citation\">Targ. Ps. LXXVIII, 52</span> Ms. (ed. <a href=\"#\" data-headword=\"טְלַל I\">אַטֵּיל</a>).</div></div>","alt":[]},"10351":{"h":"טוּל II","r":"I00164","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְלַל I\">טלל</a>) = h. <a href=\"#\" data-headword=\"צֵל\">צֵל</a>, <i>shade, shadow</i>. <span class=\"citation\">Targ. Jud. IX, 36</span>; a. fr.—<span class=\"citation\">Yoma 74ᵇ</span> <span dir=\"rtl\">תוב בט׳</span> sit in the shade.—<span class=\"citation\">Gitt. 17ᵃ</span> <span dir=\"rtl\">או בטוּלָּךְ וכ׳</span> either let us live in thy shadow (protection) or in the shadow of the son of Esau (Rome). <span class=\"citation\">Snh. 18ᵇ</span> <span dir=\"rtl\">בט׳ תאינה</span> in the shade of a fig-tree; <span class=\"citation\">Y. R. Hash. II, 58ᵇ</span> top <span dir=\"rtl\">בטֻל תינתא</span>; <span class=\"citation\">Y. Snh. I, 18ᶜ</span> bot. <span dir=\"rtl\">בטיל הינתא</span> (corr. acc.); a. fr.—Pl. <span dir=\"rtl\">טוּלַּיָּא</span>, <span dir=\"rtl\">טוּלֵּי</span>. <span class=\"citation\">Targ. Jer. VI, 4</span>; a. e.—<span class=\"citation\">Targ. Is. IX, 1</span> <span dir=\"rtl\">בארע טולי מותא</span> ed. Lag (oth. ed. <a href=\"#\" data-headword=\"טוּלִימוֹתָא\">טוּלֵימוֹתָא</a> in one word, h. text <span dir=\"rtl\">צלמית</span>).—<span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">חמשה ט׳ וכ׳</span> there are five shades (where demons dwell); a. e.—V. <a href=\"#\" data-headword=\"טְלַל III\">טְלָלָא</a>.</div>","alt":["טוּלָּא"]},"10352":{"h":"טוֹלָא","r":"I00165","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"טְלָאי\">טְלָאי</a>) <i>rag</i> tied around the finger. <span class=\"citation\">Meïl. 18ᵃ</span> עומד לט׳ Ar. (ed. <span dir=\"rtl\">לנוולה</span>; v. R. S. to <span class=\"citation\">Kel. XXVII, 4</span></div>","alt":[]},"10353":{"h":"טוּלִימוֹתָא","r":"I00166","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוּל II\">טוּלָּא</a></div>","alt":[]},"10354":{"h":"טוּלְמָא I","r":"I00167","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, constr. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"טְלַם\">טְלַם</a>) <span dir=\"rtl\">טוּלְמת</span></span> [<i>panis aqueus ac mollis</i>, P. Sm. 1477] <i>cake, loaf</i>. <span class=\"citation\">Targ. Job. XXXI, 17</span> ט׳ דלחמי Ms. (ed. only <span dir=\"rtl\">טולמי</span>); a. e.—<span class=\"citation\">Targ. Esth. III, 2</span> <span dir=\"rtl\">ט׳ דלחם</span> ed. Lag.; Yalk. ib. 105ᵇ <span dir=\"rtl\">ט׳ דנהמא</span>.—[Y. Snh. II, 20ᶜ bot. <span dir=\"rtl\">מנהם טלמא</span>, v. <a href=\"#\" data-headword=\"*טַלְמָיָא\">טַלְמָיָא</a>.]—Pl. <span dir=\"rtl\">טוּלְמִין</span>, <span dir=\"rtl\">טוּלְמֵי</span>. <span class=\"citation\">Targ. I Kings XIV, 3</span>; a. e.—<span class=\"citation\">Meg. 15ᵇ</span> בטולמי דנהמא Ms. M. 2 (ed. only <span dir=\"rtl\">בטַלְמֵי</span>) for loaves of bread. [Ar. s. v. <a href=\"#\" data-headword=\"זִיף I\">זיף</a> quotes, in Hebr. diction, (play on <span class=\"citation\">Josh. XV, 24</span>) <span dir=\"rtl\">כל המוזיף טולמיין וכ׳</span> ed. Koh. (oth. ed. <span dir=\"rtl\">טולמין</span>, <span dir=\"rtl\">טולמון</span>) he who lends bread to the poor, will be raised.]</div>","alt":["טוּלְמְתָא"]},"10355":{"h":"טוּלְמָא II","r":"I00168","html":"<div class=\"sense\"><i>oppression</i>, v. <a href=\"#\" data-headword=\"טְלוּמָא\">טְלוּמָא</a>.</div>","alt":[]},"10356":{"h":"טולמוסין","r":"I00169","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוֹלְמִיסִין\">next w.</a></div>","alt":[]},"10357":{"h":"טוֹלְמִיסִין","r":"I00170","html":"<div class=\"sense\"> (ἐτόλμησεν, fr. τολμάω) <i>he dared</i>. <span class=\"citation\">Gen. R. s. 41</span>, beg.; s. 52 (ref. to <span class=\"citation\">Gen. XII, 17</span>) [read:] <span dir=\"rtl\">על דו ט׳ למקרב למסנא וכ׳</span> because he dared to come near the shoe of that matron; <span class=\"citation\">Y. Keth. VII, end, 31ᵈ</span> <span dir=\"rtl\">על דטלמסן למגע בסמה</span> (corr. acc.); <span class=\"citation\">Yalk. Gen. 69</span>.</div>","alt":[]},"10358":{"h":"טולר","r":"I00171","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Josh. 31</span>, read <a href=\"#\" data-headword=\"פּוֹלָר\">פּוֹלָר</a>.</div>","alt":[]},"10359":{"h":"טוּלְשׁא","r":"I00172","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>crab-apple</i> (cmp. Syr. <span dir=\"rtl\">טלש</span>, P. Sm. 1482).—Pl. <span dir=\"rtl\">טוּלְשֵׁי</span>. <span class=\"citation\">Ber. 40ᵇ</span> (expl. <span dir=\"rtl\">עוזרדין</span> of <span class=\"citation\">Dem. I, 1</span>).</div>","alt":[]},"10360":{"h":"טוּם","r":"I00173","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טָמַם\">טָמַם</a>) <i>to fill up</i>. <span class=\"citation\">B. Kam. 51ᵇ</span> <span dir=\"rtl\">טָם טפח</span> if one filled up again one hand-breadth (of the depth of the pit).</div>","alt":[]},"10361":{"h":"טוּם ²","r":"I00174","html":"<div class=\"sense\"> <span class=\"citation\">Targ. II Kings III, 19</span>, v. <a href=\"#\" data-headword=\"טְמַם\">טְמַם</a>.—<span class=\"citation\">B. Kam. 50ᵃ</span> <span dir=\"rtl\">עד דטָאִים ליה</span> (Ms. M. <span dir=\"rtl\">אָטֵים</span> <i>Af.</i>, v. Rabb. D. S. a. l. note) until he fills it up.</div><div class=\"sense\"><b>Ithpa. אִיטַּיִּים</b> <div class=\"sense\"><i>to be filled up</i>. <span class=\"citation\">Erub. 79ᵃ</span> <span dir=\"rtl\">למִיטַּיְּימֵיה קאי</span> the intention is that it be filled up (with the pebbles).</div></div>","alt":[]},"10362":{"h":"טוּמְאָה","r":"I00175","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>uncleanness</i>, esp. <i>levitical uncleanness</i>, v. <a href=\"#\" data-headword=\"טָהֳרָה\">טַהֲרָה</a>. <span class=\"citation\">Pes. 19ᵃ</span> <span dir=\"rtl\">טוּמְאַת ידים</span> uncleanness of hands by touch. <span class=\"citation\">Eduy. II, 1</span>, v. <a href=\"#\" data-headword=\"אַבָּא I\">אָב</a>. <span class=\"citation\">M. Kat. 5ᵃ</span> <span dir=\"rtl\">ט׳ קוראה וכ׳</span> the uncleanness (the unclean spot being marked) calls unto him warning &amp;c.; a. v. fr.—Pl. <span dir=\"rtl\">טוּמְאוֹת</span> <span class=\"citation\">Kel. I, 1</span>; a. v. fr.</div>","alt":[]},"10363":{"h":"טוּמְאָה ²","r":"I00176","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(hebraism; <a href=\"#\" data-headword=\"טוּמְאָה\">preced.</a>) <i>unclean woman, menstruant</i>. <span class=\"citation\">Targ. Ez. XXII, 10</span>.—Pl. <span dir=\"rtl\">טוּמְאָתָא</span>. <span class=\"citation\">Targ. Is. XXX, 22</span>.</div>","alt":[]},"10364":{"h":"טוֹמוֹס","r":"I00177","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (τόμος) </div><div class=\"sense\"><b>1)</b> <i>scroll, roll, tome</i>. <span class=\"citation\">Tosef. B. Kam. IX, 31</span> <span dir=\"rtl\">בט׳ של וכ׳</span> with a roll of papers in his hand; Y. ib. VIII, beg. 6ᵇ; Sifra Emor Par. 14, ch. XX <a href=\"#\" data-headword=\"טימס\">טימסמירות</a>, <span dir=\"rtl\">טימיסמ׳</span> (read: <span dir=\"rtl\">ט׳ של ניירות</span> or <span dir=\"rtl\">שטרות</span>); <span class=\"citation\">Yalk. Lev. 658</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>document, record</i>. <span class=\"citation\">Y. Hor. III, 48ᵃ</span> bot. <span dir=\"rtl\">ראש טי׳</span> at the head of the list; <span class=\"citation\">Lev. R. s. 5</span> בראש ט׳ Ar. (ed. only <span dir=\"rtl\">בראש</span>). <span class=\"citation\">Gen. R. s. 25</span> beg. <span dir=\"rtl\">בתוך טִימוֹסָן וכ׳</span> in the record of the righteous; <span class=\"citation\">Yalk. ib. 42</span>; Yalk. Chr. 1072 <span dir=\"rtl\">טִימוֹסִין</span> pl.—Pl. <span dir=\"rtl\">טוֹמוֹסִין</span>, <span dir=\"rtl\">טוֹמוֹסוֹת</span>, <a href=\"#\" data-headword=\"טִבְעוֹן\">טִי׳</a>. Pesik. Zakh. p. 27ᵃ [read:] <span dir=\"rtl\">ונטל ט׳ וכ׳</span> (or <span dir=\"rtl\">טִימוֹסָן</span>) he took the lists of the tribes &amp;c.; Tanḥ. Ki Thetse 9. <span class=\"citation\">Y. Snh. X, 28ᵃ</span> top <span dir=\"rtl\">אף שמותיהם … טֹמְסוֹתֵיהֶם</span> even their names disappeared from their books of records. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">הוציא הנמוסין וכ׳</span> (corr. acc.; Tanḥ. Vaëra 5 <a href=\"#\" data-headword=\"דִּפְתִּי\">דִּפְתְּרָא</a>) he brought out the lists of the deities.</div><div class=\"sense\"><b>—3)</b> <i>census</i>. <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">היה טימס … בעגלה</span> their census had to be carried to Jerusalem on a wagon; [<span class=\"citation\">Y. Taan. IV, 69ᵃ</span> bot. <span dir=\"rtl\">קטמו׳</span> read <span dir=\"rtl\">הטומוס</span> or <span dir=\"rtl\">קִינְסוֹס</span>].</div>","alt":["(טִימוֹס)"]},"10365":{"h":"טוּמְטוּם","r":"I00178","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (redupl. of <a href=\"#\" data-headword=\"טָמַם\">טָמַם</a>) <i>a person whose genitals are hidden, or undevelopped; one whose sex is unknown</i>. <span class=\"citation\">B. Bath. 126ᵇ</span> <span dir=\"rtl\">ט׳ שנקרע וכ׳</span> a <i>tumtum</i> who was operated upon and was found to be a male. <span class=\"citation\">Bicc. IV, 5</span> (Talm. ed.); a. e.—[<span class=\"citation\">Midr. Till. to Ps. I</span>; <span class=\"citation\">Yalk. Prov. 953</span> <span dir=\"rtl\">ט׳ הוא העולם</span>, v. <a href=\"#\" data-headword=\"אַבְטוֹמְטוֹס\">אַבְטוֹמְטוֹס</a>.]—Pl. <span dir=\"rtl\">טוּמְטוּמִין</span>. <span class=\"citation\">Yeb. 64ᵃ</span> bot. (not <span dir=\"rtl\">טומטמין</span>).</div>","alt":[]},"10366":{"h":"*טוּמַיָּיא","r":"I00179","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טוּם\">טוּם</a>; cmp. <a href=\"#\" data-headword=\"סָתַם\">סָתַם</a>, <a href=\"#\" data-headword=\"סָתַר I\">סָתַר</a>) <i>secret, hidden place</i>. <span class=\"citation\">Targ. Y. II, Deut. XXVII, 15</span> (later ed. <span dir=\"rtl\">טוּמְרַיָּא</span>).</div>","alt":[]},"10367":{"h":"טומיות","r":"I00180","html":"<div class=\"sense\">, v. <span dir=\"rtl\">טוּרְמִיּוֹת</span></div>","alt":[]},"10368":{"h":"טומיקון","r":"I00181","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַמְיָקוֹן\">טַמְיָקוֹן</a></div>","alt":[]},"10369":{"h":"טוּמְעָא","r":"I00182","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְמַע\">טְמַע</a>) </div><div class=\"sense\"><b>1)</b> <i>secret place</i>. <span class=\"citation\">Targ. Job. XL, 13</span>.</div><div class=\"sense\"><b>—2)</b> <i>hidden treasure</i>.—Pl. <span dir=\"rtl\">טוּמְעַיָּא</span>. Ib. III, 20.</div>","alt":[]},"10370":{"h":"טוּמְרָא","r":"I00183","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְמַר\">טְמַר</a>, cmp. <a href=\"#\" data-headword=\"טוּמְעָא\">preced.</a>) <i>secret, hiding place</i>. <span class=\"citation\">Targ. Y. Deut. XIII, 9</span>. <span class=\"citation\">Targ. Y. I ib. XXVII, 15</span>; a. fr.—Pl. <span dir=\"rtl\">טוּמְרַיָּא</span>. <span class=\"citation\">Targ. Ps. X, 8</span>; a. e.; v. <a href=\"#\" data-headword=\"*טוּמַיָּיא\">טוּמַיָּא</a>.</div>","alt":[]},"10371":{"h":"טוּן","r":"I00184","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טָנַן\">טָנַן</a></div>","alt":[]},"10372":{"h":"טוּנָא I","r":"I00185","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"טְעוּנָא\">טְעוּנָא</a>; <a href=\"#\" data-headword=\"טְעַן\">טְעַן</a>) </div><div class=\"sense\"><b>1)</b> <i>burden, load; bag</i>. <span class=\"citation\">Targ. Y. Gen. XLIV, 1</span>, sq. (h. text <span dir=\"rtl\">אמתחת</span>). <span class=\"citation\">Targ. Y. Ex. XXIII, 5</span>; a. e.—<span class=\"citation\">Ber. 61ᵃ</span> דלא דרי ט׳ Ms. M. (ed. <span dir=\"rtl\">טידי</span>) when he is not carrying a load. <span class=\"citation\">Sabb. 92ᵃ</span> <span dir=\"rtl\">דכל ט׳ דמידלי וכ׳</span> every load which is lifted on poles &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"טַעֲנָה\">טַעֲנָה</a>) <i>argument</i>. <span class=\"citation\">Zeb. 32ᵇ</span> מטוּנָךְ I borrow thine own argument; <span class=\"citation\">R. Hash. 4ᵃ</span>; <span class=\"citation\">Ḥull. 132ᵃ</span> top (Rashi derives fr. <a href=\"#\" data-headword=\"מְטֵי\">מְטֵי</a>: ‘we have reached thee’).—Pl. <span dir=\"rtl\">טוּנִין</span>. <span class=\"citation\">Targ. Y. Gen. XLIII, 23</span>.</div>","alt":[]},"10373":{"h":"*טוּנָא II","r":"I00186","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"טוּל II\">טוּלָא</a> (?), <i>shade, shadow</i>. <span class=\"citation\">Ber. 56ᵇ</span> (v. vers. in Rabb. D. S. a. l. Ms. M. a. note).</div>","alt":[]},"10374":{"h":"טונוס","r":"I00187","html":"<div class=\"sense\">, Y. Ber. IX, 14ᵇ bot. <a href=\"#\" data-headword=\"טוּרְנוֹס\">ט׳ רופוס</a>, v. <a href=\"#\" data-headword=\"טוּרְנוֹס\">טוּרְנוֹס</a></div>","alt":[]},"10375":{"h":"טוּנֵס","r":"I00188","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Tunes) <i>Tunis</i> in Northern Africa. <span class=\"citation\">Sifré Deut. 320</span>, v. <a href=\"#\" data-headword=\"בַּרְבַּרְיָא\">בַּרְבַּרְיָא</a>.—*<span class=\"citation\">Targ. Y. Ex. II, 3</span> <span dir=\"rtl\">תיבותא דט׳</span> (prob. meaning <a href=\"#\" data-headword=\"טָנֵיס\">טָנֵיס</a>; some ed. <span dir=\"rtl\">נַס …</span>) a Tunesian box (h. text <a href=\"#\" data-headword=\"גַּם II\">גמא</a>).</div>","alt":[]},"10376":{"h":"טוּס","r":"I00189","html":"<div class=\"sense\"> [</div><div class=\"sense\"><b>1)</b> <i>to glisten</i>. Denom. <a href=\"#\" data-headword=\"טַוָּוס\">טַוָּוס</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"חָלַף\">חָלַף</a>)] <i>to fly swiftly</i>.—<span class=\"citation\">Y. Taan. IV, 69ᵇ</span> <span dir=\"rtl\">לא נראה עיף טָס וכ׳</span> no bird has been seen flying in all Palestine; Lam. R. introd. end.—<span class=\"citation\">Deut. R. s. 6</span> <span dir=\"rtl\">קושט … וטס כעוף</span> goes straight like an arrow, and swift like a bird. <span class=\"citation\">Midr. Till. to Ps. XC, 10</span> <span dir=\"rtl\">גזין חשין וטָסִין</span> they pass, hasten and fly; a. fr.</div><div class=\"sense\"><b>Pi. טִיֵּיס</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"טוּנֵס\">same</a>. <span class=\"citation\">Koh. R. to IX, 7</span> <span dir=\"rtl\">ט׳ וחזר וט׳</span> he flew to and back.</div></div><div class=\"sense\"><b>Hif. הֵטִיס</b> <div class=\"sense\"><i>to cause to fly, to bring on by flight</i>. <span class=\"citation\">Ruth R. to IV, 1</span> <span dir=\"rtl\">הטִיסוֹ וכ׳</span> the Lord would have made him fly and brought him (to the place). <span class=\"citation\">Gen. R. s. 59</span>, end. <span class=\"citation\">Cant. R. to I, 9</span> <span dir=\"rtl\">הֵטִיסָן</span>; <span class=\"citation\">Ex. R. s. 23</span> end <span dir=\"rtl\">הסיטן</span> (corr. acc.).—<span class=\"citation\">Lev. R. s. 16</span> <span dir=\"rtl\">הסיט׳</span>, (read as) <span class=\"citation\">Yalk. Kings 232</span>. <span class=\"citation\">Lev. R. s. 11</span>, beg. <span dir=\"rtl\">הסיטן</span> (corr. acc.) he winged them; a. fr.</div></div>","alt":[]},"10377":{"h":"טוּס ²","r":"I00190","html":"<div class=\"sense\"><span class=\"citation\">Targ. Job V, 7</span> (Ms. <a href=\"#\" data-headword=\"טוּשׂ\">טוּשׂ</a>); a. fr.—Part. <a href=\"#\" data-headword=\"טָיִיס\">טָיֵיס</a>, <a href=\"#\" data-headword=\"טָיִיס\">טָיֵס</a>, <a href=\"#\" data-headword=\"טָאֵיס\">טָאֵיס</a>, <a href=\"#\" data-headword=\"טָאֵס\">טָאֵס</a>. <span class=\"citation\">Ib. XXXIX, 18</span>.—Targ. II Esth. I, 2 <span dir=\"rtl\">שונרין טייסין</span> (read: <span dir=\"rtl\">נשרין</span>).—<span class=\"citation\">Targ. Is. XVIII, 1</span> (ed. Lag. <span dir=\"rtl\">דטאס</span>]; a. fr.—<span class=\"citation\">Y. Yeb. XVI, 15ᶜ</span> bot. <span dir=\"rtl\">נפשא טָיְיסָא וכ׳</span> the soul hovers over the body; Y. M. Kat. III, 82ᵇ bot.; <span class=\"citation\">Lev. R. s. 18</span>; (<span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">תייבא</span>).</div><div class=\"sense\"><b>Pa. טַיֵּיס</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"טוּס\">same</a>. Targ. II Esth. l. c. <span dir=\"rtl\">טַיְיסִית</span> I flew.</div><div class=\"sense\"><b>—2)</b> <i>to cause to fly</i>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 49</span>. [Ib. <span dir=\"rtl\">טַיֵּיס נישרא</span>, read: <a href=\"#\" data-headword=\"טָיִיס\">טָיֵיס</a>, v. supra.]</div></div>","alt":[]},"10378":{"h":"טַוָּס","r":"I00191","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"טָוִי\">טַוו׳</a>.</div>","alt":["טַוְסָא"]},"10379":{"h":"טוּעֵי","r":"I00192","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְעֵי\">טְעִי</a>) <i>thoughtlessness</i>. <span class=\"citation\">Targ. Prov. I, 32</span> (ed. Lag. <span dir=\"rtl\">טועיי</span>, Var. <a href=\"#\" data-headword=\"טוּעֵי\">טועי</a>).</div>","alt":[]},"10380":{"h":"טוֹעַן","r":"I00193","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טָעַן I) <i>requirement</i>. Sifra introd., v. <a href=\"#\" data-headword=\"טָעַן I\"><span dir=\"rtl\">טָעַן</span> I</a>.</div>","alt":["טֹעַן","(טָעוּן)"]},"10381":{"h":"טוּעֲנָא","r":"I00194","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טְעַן II) <i>burden, load, bag</i>. <span class=\"citation\">Targ. O. Ex. XXIII, 5</span>; a. fr.; v. <a href=\"#\" data-headword=\"טוּנָא I\"><span dir=\"rtl\">טוּנָא</span> I</a>.—V. <a href=\"#\" data-headword=\"טְעוּנָא\">טְעוֹנָא</a>.</div>","alt":[]},"10382":{"h":"טוּף","r":"I00195","html":"<div class=\"sense\"><b>1)</b>  [<i>to shine</i>,] <i>to come to the surface, float, bubble up</i>. Part. <a href=\"#\" data-headword=\"טָאֵיף\">טָאֵיף</a>, <a href=\"#\" data-headword=\"טוּף\">טָיֵיף</a>. <span class=\"citation\">Targ. Y. Deut. XXI, 1</span>. <span class=\"citation\">Targ. Y. Gen. XXVIII, 10</span>; a. e.—<span class=\"citation\">Koh. R. to V, 8</span> (mixed diction) <span dir=\"rtl\">וטָפַת בארה של וכ׳</span> Miriam’s well came up.—<span class=\"citation\">Ab. II, 6</span>; <span class=\"citation\">Succ. 53ᵃ</span>, v. infra.—<span class=\"citation\">Y. Shebi. IX, 38ᵈ</span>; Pesik. B’shall. p. 89ᵇ <span dir=\"rtl\">הוה טָיֵיף</span> the corpse came up to the surface. <span class=\"citation\">Gen. R. s. 81</span> (in Hebr. dict.) <span dir=\"rtl\">וטָפַת רוחי וכ׳</span> and my mind in me was swimming (I became proud, v. <a href=\"#\" data-headword=\"טָפַח I\">טָפַח</a>); a. fr.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"טִיף I\">טיף</a>) <i>to drip; to be inundated</i>. <span class=\"citation\">Targ. O. Gen. XLIX, 12</span>; a. e.—<span class=\"citation\">Keth. 111ᵇ</span> <span dir=\"rtl\">חלבא טייף וכ׳</span> milk was dripping &amp;c. <span class=\"citation\">Y. Taan. III, end, 67ᵃ</span> <span dir=\"rtl\">הוה עלמא ט׳</span> the world would have been flooded. <span class=\"citation\">Gen. R. s. 32</span>; <span class=\"citation\">Yalk. ib. 57</span> <span dir=\"rtl\">דלא טף וכ׳</span> it (the mount Gerizim) was not flooded by the waters of the flood; a. e.—[<span class=\"citation\">Targ. Y. Deut. XXI, 23</span> <span dir=\"rtl\">תטופון</span>, v. <a href=\"#\" data-headword=\"טְנַף\">טְנַף</a> a. <a href=\"#\" data-headword=\"נְטַף\">נְטַף</a>.]</div><div class=\"sense\"><b>Pa. טַיֵּיף  טָאֵף</b> <div class=\"sense\"><b>1)</b> <i>to direct the overflow, to assign channels</i>. <span class=\"citation\">Targ. Job XXXVIII, 24</span>, v. <a href=\"#\" data-headword=\"טְיָפָא\">טְיָפָא</a>.—<span class=\"citation\">Gitt. 69ᵇ</span> top <span dir=\"rtl\">ונִיטַּיְיפֵיה וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>to cause to glisten, to turn in all directions</i>. <span class=\"citation\">Keth. 60ᵇ</span> מְטַיְּפֵי עינא Ar. (ed. <span dir=\"rtl\">מציצי</span>, v. infra) with restless eyes.</div><div class=\"sense\"><b>—3)</b> <i>to cause to float</i>, v. infra.</div></div><div class=\"sense\"><b>Af. אָטֵיף  אַטֵּיף</b> <div class=\"sense\"> (fr. <a href=\"#\" data-headword=\"נְטַף\">נְטַף</a>) </div><div class=\"sense\"><b>1)</b> <i>to make flow</i>. <span class=\"citation\">Targ. Deut. XI, 4</span>.—[Keth. l. c. <span dir=\"rtl\">מְטִיפֵי עינא</span> Ar. s. v. <a href=\"#\" data-headword=\"טַף\">טף</a> I ‘with dripping eyes’, v. supra.]</div><div class=\"sense\"><b>—2)</b> <i>to cause to float.</i> <span class=\"citation\">Ab. II, 6</span> <span dir=\"rtl\">על דאֲטֵפְתְּ אֲטִיפוּךְ וסוף מְטִיפָיךְ יְטוּפוּן</span> ed. Strack (oth. eds. <span dir=\"rtl\">אַטְפוּךְ</span>; Strack reads <span dir=\"rtl\">מְטַיְפָיךְ</span> <i>Pa.</i>; oth. pointed eds. <span dir=\"rtl\">מְטיְּפָיִךְ</span> h. form) because thou (the person whose skull was seen to float) hast caused (a corpse) to float, they made thee float, and those who made thee float, shall also float.</div></div><div class=\"sense\"><b>Ithpa. אִיטַּיֵּיף</b> <div class=\"sense\"><i>to be glittering, to be turned in all directions</i>. <span class=\"citation\">B. Kam. 92ᵇ</span>; <span class=\"citation\">Meg. 14ᵇ</span> <span dir=\"rtl\">ועיניה מִטַּיְּיפֵי</span> and its eyes look all around (for food).</div></div>","alt":[]},"10383":{"h":"טופא","r":"I00196","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to V, 10</span> <span dir=\"rtl\">לית ט׳ דהדא</span>. read: <a href=\"#\" data-headword=\"סוֹף ²\">סוֹפָא</a>.</div>","alt":[]},"10384":{"h":"טְוָפָא","r":"I00197","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">טְוָפֵי</span>, v. <a href=\"#\" data-headword=\"טְיָפָא\">טְיָפָא</a>.</div>","alt":[]},"10385":{"h":"טוֹפוֹס","r":"I00198","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טָפוּס\">טָפוּס</a> a. <a href=\"#\" data-headword=\"טוֹפֵס\"><a href=\"#\" data-headword=\"טוֹפֵס\">טוֹפֵס</a>.</a></div>","alt":[]},"10386":{"h":"טוֹפֵחַ","r":"I00199","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טָפַח II) <i>irrigating engine</i>. <span class=\"citation\">Peah V, 3</span> <span dir=\"rtl\">אין מגלגלין בט׳</span> (Y. ed. <a href=\"#\" data-headword=\"טוֹפֵיחַ\">טוֹפֵיחַ</a>) one must not irrigate (a field) with an irrigator (before the poor have collected their share; v. Tosef. ib. II, 20); Y. ib. V, 19ᵃ top. [Maim. identifying our w. with <a href=\"#\" data-headword=\"טוֹפַח\">next w.</a> explains: you must not <i>sow the tofaḥ</i> in conjunction with other seeds.]</div>","alt":[]},"10387":{"h":"טוֹפַח","r":"I00200","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טוֹפֵחַ\">preced.</a>) an <i>aquatic plant</i> like the Colocasia; <i>bean, tofaḥ;</i> [Maim. <span dir=\"rtl\">קרטמאן</span> Arab., defining it ‘a seed similar to barley.’] <span class=\"citation\">Kil. I, 1</span>. T’bul Yom I, 2; <span class=\"citation\">Tosef. ib. I, 1</span><span class=\"citation\">T’bul Yom I, 2</span>; <span class=\"citation\">Tosef. ib. I, 1</span>, sq. <a href=\"#\" data-headword=\"טְפִיחַ I\">טפיח</a> (R. S. to T’bul Yom l. c. quotes <span dir=\"rtl\">טופח</span>). <span class=\"citation\">Tosef. Makhsh. III, 6</span> <a href=\"#\" data-headword=\"טוֹפֵיחַ\">טוֹפֵיחַ</a>. Tosef. T’rum. VI, 11 <a href=\"#\" data-headword=\"טְפִיחַ I\">טפיח</a> ed. Zuck. (Var. <span dir=\"rtl\">טופח</span>, <a href=\"#\" data-headword=\"טוֹפֵיחַ\">טופיח</a>). <span class=\"citation\">Peah VI, 7</span> <span dir=\"rtl\">אפי׳ היא של ט׳</span> even if the barley in the field have the size of <i>tofaḥ</i> (R. S.; Maim.: “even if it be a field of the inferior kind of barley named <i>t</i>.”).—V. <a href=\"#\" data-headword=\"טְפִיחַ II\"><span dir=\"rtl\">טְפִיחַ</span> II</a>.</div>","alt":[]},"10388":{"h":"טוֹפֵיחַ","r":"I00201","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טוֹפַח\">preced.</a> wds.</div>","alt":[]},"10389":{"h":"טוּפְיָינָא","r":"I00202","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (טְכֵּי III) <i>additional amount, surplus</i>. <span class=\"citation\">B. Mets. 63ᵇ</span> <span dir=\"rtl\">ואשכח ביה ט׳</span> (Var. <span dir=\"rtl\">טפייתא</span>, <a href=\"#\" data-headword=\"טְפִיתָא\">טפיתא</a>, <span dir=\"rtl\">טפיאתא</span>, v. Rabb. D. S. a. l. note 9) and he (the borrower) finds in the bundle more money than the loan agreed upon. V. <a href=\"#\" data-headword=\"טִיפוּנָא\">טִיפוּנָא</a> a. <a href=\"#\" data-headword=\"טְפִיתָא\">טְפִיתָא</a>.</div>","alt":[]},"10390":{"h":"טופיסוס","r":"I00203","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 21</span>, read: <a href=\"#\" data-headword=\"סוֹפִיסְטָא\">סוֹפִיסְטֵיס</a>.</div>","alt":["טופיסטוס"]},"10391":{"h":"טופיתא","r":"I00204","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Job XXVIII, 7</span> ed. Lag., v. <a href=\"#\" data-headword=\"טַרְפִיתָא\">טַרְפִיתָא</a></div>","alt":[]},"10392":{"h":"טוּפִיתָא","r":"I00205","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">טוּפְיָאתָא</span>, <a href=\"#\" data-headword=\"טוּפְיָינָא\">טוּפְיָיתָא</a>, v. <a href=\"#\" data-headword=\"טְפִיתָא\">טְפִיתָא</a>.</div>","alt":[]},"10393":{"h":"טוּפְלָא","r":"I00206","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"טַפְלָא\">טַפְלָא</a></div>","alt":[]},"10394":{"h":"טוֹפָנָא","r":"I00207","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טוּף\">טוּף</a>) <i>flood</i>. <span class=\"citation\">Targ. O. Gen. VI, 17</span> (Y. <a href=\"#\" data-headword=\"טוֹבְעָנָא\">טוֹבְעָנָא</a>); a. fr.</div>","alt":["טוּ׳"]},"10395":{"h":"טוֹפֵס","r":"I00208","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"טָפַס\">טָפַס</a>; cmp. <a href=\"#\" data-headword=\"דָּפוּס\">דָּפוּס</a>, <a href=\"#\" data-headword=\"טָפוּס\">טָפוּס</a>) <i>frame</i>; trnsf. (influenced by Greek τύπος) <i>formula</i> (to be filled out according to occasion). <span class=\"citation\">Y. Ber. I, 3ᵈ</span> <span dir=\"rtl\">ט׳ ברכות וכ׳</span> such is the formula of the benedictions; <span class=\"citation\">Lev. R. s. 34</span>, end; <span class=\"citation\">Y. Sabb. XV, end, 15ᵇ</span> <a href=\"#\" data-headword=\"טוֹפוֹס\">טופוס</a>.—Esp. <i>the formula</i> or <i>blank of documents</i>, opp. <span dir=\"rtl\">תורף</span> containing names, dates &amp;c. <span class=\"citation\">Y. Gitt. III, beg. 44ᶜ</span> <span dir=\"rtl\">כתב תרפו בט׳</span> (also <span dir=\"rtl\">בתוֹפֵס</span>) if the writer filled out a blank. <span class=\"citation\">B. Mets. 7ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">טוֹפְסִין</span>, constr. <span dir=\"rtl\">טוֹפְסֵי</span>. <span class=\"citation\">Y. Gitt. II, beg. 44ᵃ</span> <span dir=\"rtl\">פוסל בט׳</span> declares illegal deeds of divorce written into ready-made blanks. <span class=\"citation\">Gitt. III, 2</span> <span dir=\"rtl\">הכותב ט׳ גיטין וכ׳</span> he who writes formulas of letters of divorce must leave blanks for the name &amp;c.; a. fr.</div>","alt":[]},"10396":{"h":"טוּפְסָא","r":"I00209","html":"<div class=\"sense\">, ch. <a href=\"#\" data-headword=\"טוֹפֵס\">same</a>, = h. <a href=\"#\" data-headword=\"טָפוּס\">טָפוּס</a>, <a href=\"#\" data-headword=\"דָּפוּס\">דָּפוּס</a>, <i>frame, mould, cast</i>. <span class=\"citation\">Targ. Y. Num. XXV, 1</span> (cmp. <span class=\"citation\">Sabb. 64ᵃ</span> s. v. <a href=\"#\" data-headword=\"דָּפוּס\">דָּפוּס</a>). <span class=\"citation\">Targ. Y. Ex. XXXII, 4</span> בטֻפְסָא Ar. a Levita (ed. <span dir=\"rtl\">בטופרא</span>, corr. acc.) in a mould.—[<span class=\"citation\">B. Bath. 103ᵇ</span> טופסא Ar., v. <a href=\"#\" data-headword=\"טַפְתָּא\">טַפְתָּא</a>.]</div>","alt":[]},"10397":{"h":"טוּפְרָא","r":"I00210","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"צִפֹּרֶן\">צִפֹּרֶן</a>, </div><div class=\"sense\"><b>1)</b> <i>nail</i> of the human finger; <i>claw; hoof</i>; trnsf. <i>pencil</i>. <span class=\"citation\">Targ. Jer. XVII, 1</span>.—<span class=\"citation\">Ḥull. 17ᵇ</span> the knife must be examined, <span dir=\"rtl\">אבישרא ואט׳ וכ׳</span> on the fleshy top of the finger and on the nail &amp;c.; a. fr.—Pl. <span dir=\"rtl\">טוּפְרִין</span>, <a href=\"#\" data-headword=\"טִיפְתָא\">טִפְ׳</a>, <span dir=\"rtl\">טוּפְרַיָּיא</span>. <span class=\"citation\">Targ. Jud. V, 22</span> (h. text <span dir=\"rtl\">עקבות</span>) <span class=\"citation\">Targ. O. Deut. XXI, 12</span> <span dir=\"rtl\">טוֹפְרָהָא</span> ed. Berl. (ed. Vien. <a href=\"#\" data-headword=\"טוּפְרָנָא\">טוּפְרָנָהָא</a>; Y. <span dir=\"rtl\">טוּפְרַיָּיהָא</span>).—<span class=\"citation\">M. Kat. 18ᵃ</span> <span dir=\"rtl\">חזנהו לטופריה וכ׳</span> (not <span dir=\"rtl\">לטופרי</span>) saw that his nails were long; a. e.—Midr. Sam. ch. XI, v. <a href=\"#\" data-headword=\"אִסְטְלִי\">אִסְטְלִי</a>.</div><div class=\"sense\"><b>—2)</b> <i>onycha</i> (<i>unguis odoratus</i>) a spice. <span class=\"citation\">Targ. O. Ex. XXX, 34</span>.—[<span class=\"citation\">Targ. Y. Gen. III, 7</span> <span dir=\"rtl\">לבוש טופרא</span>, read: <a href=\"#\" data-headword=\"שׁוּפְרָא\">שׂוּפְרָא</a>.—<span class=\"citation\">Lev. R. s. 33</span> <span dir=\"rtl\">טופרין ושער ועצמות</span>, read: <span dir=\"rtl\">טפוסין של צלמים</span>, v. Yalk. Dan. 1061.—<span class=\"citation\">Targ. Y. Ex. XXXII, 4</span>, v. <a href=\"#\" data-headword=\"טוּפְסָא\">טוּפְסָא</a>.]—V. <a href=\"#\" data-headword=\"טוּפְרָנָא\">next w.</a></div>","alt":["טְפַר"]},"10398":{"h":"טוּפְרָנָא","r":"I00211","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, collect. noun (<a href=\"#\" data-headword=\"טוּפְרָא\">preced.</a>) <i>nails</i>. <span class=\"citation\">Targ. O. Deut. XXI, 2</span>.—[<span class=\"citation\">Y. Snh. I, 18ᶜ</span> bot. <span dir=\"rtl\">טופרני</span>, read: <span dir=\"rtl\">טוּפְרוֹי</span>; <span class=\"citation\">Y. R. Hash. II, 58ᵇ</span> top <span dir=\"rtl\">טפרוי</span>; v. <a href=\"#\" data-headword=\"דְּקָקָה\">דְּקָקָה</a>.]</div>","alt":[]},"10399":{"h":"*טוֹפֶת","r":"I00212","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Valley of Beth-Tofeth</i> <span class=\"citation\">Koh. R. to V, 8</span>; v., however, <a href=\"#\" data-headword=\"נְטוֹפָה II\"><span dir=\"rtl\">נְטוֹפָה</span> II</a>.</div>","alt":["בקעת בית ט׳"]}};
